INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C1','kor',5,2,'u3',1,'지역마다 다른 인사말 — 「어서 오세요 · 어서 오슈 · 어서 오이소 · 혼저 옵서예」처럼 뜻은 같아도 지역에 따라 끝말과 말소리가 다르다',ARRAY['6국04-02 문법']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C2','kor',5,2,'u3',1,'표준어의 뜻 — 우리나라 사람들이 공통으로 쓸 수 있도록 정한 말로, 어느 지역 사람이든 함께 알아듣게 해 준다',ARRAY['6국04-02 문법']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C3','kor',5,2,'u3',1,'방언의 뜻 — 특정 지역에서 주로 쓰는, 표준어가 아닌 말로 도시든 시골이든 그 지역 사람들이 오랫동안 써 온 우리말이다',ARRAY['6국04-02 문법']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C4','kor',5,2,'u3',1,'단원의 흐름 — 표준어와 방언의 뜻 알기 → 쓰는 상황 조사하기 → 방언의 가치 알기 → 방언이 나오는 작품 감상하기 → 방언으로 작품 만들기',ARRAY['6국04-02 문법']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C5','kor',5,2,'u3',2,'방언이 생긴 까닭 — 옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고 이야기할 기회가 적어 지역마다 말이 조금씩 달라졌다(지리적 특성)',ARRAY['6국04-02 문법']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C6','kor',5,2,'u3',2,'표준어를 정한 까닭 — 지역마다 말이 다르면 뜻을 나누기 어려워서 사는 곳이 달라도 원활하게 이야기할 수 있도록 표준어를 정했다',ARRAY['6국04-02 문법']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C7','kor',5,2,'u3',2,'표준어를 정하는 곳과 기준 — 국립국어원이 사람들이 두루 쓰는지 · 문법에 맞는지 · 발음하기 편하고 자연스러운지를 살펴 정한다',ARRAY['6국04-02 문법']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C8','kor',5,2,'u3',2,'방언이 표준어가 되기도 해요 — 「멍게」처럼 방언이 표준어보다 더 널리 쓰이게 되면 표준어로 인정되기도 하여 둘 사이는 움직이는 경계이다',ARRAY['6국04-02 문법']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C9','kor',5,2,'u3',2,'한 낱말을 가리키는 여러 방언 — 개구리(까구리 · 깨고락지) · 부추(분추 · 정구지 · 소풀 · 세우리) · 김치(짐끼 · 짐치)처럼 한 낱말을 지역마다 다르게 부른다',ARRAY['6국04-02 문법']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C10','kor',5,2,'u3',2,'온라인 사전으로 방언 찾기 — 국립국어원 지역어 누리집에서 표준어 낱말을 검색하면 지역별 방언과 발음을 확인할 수 있어 짐작이 아닌 근거로 찾는다',ARRAY['6국04-02 문법']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C11','kor',5,2,'u3',2,'방언은 정답이 하나가 아니에요 — 방언은 같은 지역 안에서도 마을마다 다르고 지역 경계와 똑같이 나뉘지 않아, 서로 다른 답을 근거로 함께 확인한다',ARRAY['6국04-02 문법']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C12','kor',5,2,'u3',4,'상황에 따라 고르는 말 — 뜻이 같은 말도 누구에게, 어떤 자리에서 말하느냐에 따라 표준어나 방언으로 골라 쓴다',ARRAY['6국04-02 문법']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C13','kor',5,2,'u3',4,'표준어가 어울리는 상황 — 뉴스 · 많은 사람 앞 발표 · 학교 방송처럼 여러 지역 사람에게 공식적으로 정확히 전할 때는 주로 표준어를 쓴다',ARRAY['6국04-02 문법']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C14','kor',5,2,'u3',4,'방언이 어울리는 상황 — 고향 친구와 통화 · 시장 단골손님과 대화 · 지역 축제처럼 같은 지역 사람끼리 친근함과 정을 나눌 때 방언을 쓰기도 한다',ARRAY['6국04-02 문법']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C15','kor',5,2,'u3',4,'표준어로 바꾸어 보는 까닭 — 방언을 표준어로 바꾸어 보는 것은 고치기 위해서가 아니라 같은 뜻이 상황에 따라 다르게 골라 쓰인다는 것을 알기 위해서이다',ARRAY['6국04-02 문법']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C16','kor',5,2,'u3',4,'사용 상황 조사의 세 가지 — 누구에게 · 어떤 상황에서 · 어떤 사이인지 살피고, 그 말을 고른 까닭까지 적어야 상황과 말의 관계가 보인다',ARRAY['6국04-02 문법']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C17','kor',5,2,'u3',6,'방언에 담긴 생활 모습 — 올레(좁은 돌담길) · 정낭(대문 가로대) · 삼춘(마을 어른) · 물허벅(물동이)처럼 방언에는 그 마을의 생활과 관계가 담겨 있다',ARRAY['6국04-02 문법']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C18','kor',5,2,'u3',6,'방언에 담긴 자연환경 — 감재옹심이(산이 많은 강원의 감자) · 뻘(넓은 갯벌) · 돔배기(절인 상어고기)처럼 방언에는 지역의 자연과 먹을거리가 반영된다',ARRAY['6국04-02 문법']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C19','kor',5,2,'u3',6,'방언의 가치 — 방언은 지역의 자연환경과 생활 모습, 우리말의 옛 모습, 지역 사람들의 정서를 간직한 지역 문화의 자산이다',ARRAY['6국04-02 문법']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C20','kor',5,2,'u3',6,'방언을 지키는 일 — 방언이 사라지면 그 말에 담긴 생활과 이야기도 잊힐 수 있어 방언 사전 · 그림책처럼 기록해 물려주려는 노력을 한다',ARRAY['6국04-02 문법']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C21','kor',5,2,'u3',8,'줄거리와 인물의 마음 — 방언이 나오는 작품도 먼저 일어난 일과 인물의 마음이 어떻게 바뀌는지를 파악하며 읽는다',ARRAY['6국05-06 문학']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C22','kor',5,2,'u3',8,'앞뒤 장면으로 뜻 짐작하기 — 작품 속 방언의 뜻을 모를 때는 앞뒤 장면으로 짐작하고 사전이나 지역어 누리집으로 확인한다',ARRAY['6국05-06 문학']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C23','kor',5,2,'u3',8,'방언과 표준어로 읽고 느낌 견주기 — 방언을 표준어로 바꾸어도 뜻은 같지만 인물의 목소리와 분위기 같은 느낌은 달라지므로 소리 내어 읽고 견준다',ARRAY['6국05-06 문학']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C24','kor',5,2,'u3',8,'작품에 방언을 쓰면 좋은 점 — 인물이 어디에 사는 누구인지 생생해지고, 인물 사이의 정과 분위기가 살아나며, 지역의 말을 기록하고 지킨다',ARRAY['6국05-06 문학']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C25','kor',5,2,'u3',8,'내 삶과 이어 감상하기 — 방언을 들었던 내 경험과 작품 장면을 이어 보면 인물의 마음을 더 가깝게 느끼고 내 언어생활을 돌아볼 수 있다',ARRAY['6국05-06 문학']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C26','kor',5,2,'u3',10,'방언으로 만드는 작품 — 우리 반 방언 지도 · 방언 노랫말 · 방언 상황극 가운데 고르고, 반 전체 · 모둠 · 짝 · 혼자 가운데 할 방식도 함께 정한다',ARRAY['6국04-02 문법']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C27','kor',5,2,'u3',10,'방언 지도 만드는 차례 — 주제 정하기 → 모둠별 지역 나누기(고른 까닭) → 방언 · 뜻 · 생활 조사하기 → 지도에 지역명과 함께 붙이기',ARRAY['6국04-02 문법']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C28','kor',5,2,'u3',10,'개수보다 뜻과 생활 — 좋은 방언 지도는 방언을 많이 모은 지도가 아니라 방언과 뜻, 그 말과 이어지는 생활이 함께 드러난 지도이다',ARRAY['6국04-02 문법']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C29','kor',5,2,'u3',10,'방언을 존중하는 태도 — 방언을 흉내 내거나 웃음거리로 삼지 않고, 낯선 말도 그 지역 사람의 마음과 생활을 살려 궁금한 마음으로 대한다',ARRAY['6국04-02 문법']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C30','kor',5,2,'u3',12,'함께 어우러지는 우리말 — 표준어는 원활한 의사소통을, 방언은 지역의 특성과 정서를 지켜 주므로 둘은 겨루는 말이 아니라 함께 소중한 우리말이다',ARRAY['6국04-02 문법']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C31','kor',5,2,'u3',12,'상황 카드 — 까닭과 함께 고르기 — 뉴스 · 회의는 표준어, 고향 친구 · 지역 축제는 방언처럼 고르되 까닭을 함께 말하고, 표준어를 쓰는 지역이라면 표준어도 답이 된다',ARRAY['6국04-02 문법']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C32','kor',5,2,'u3',12,'동형어 — 배 · 눈 · 말 · 김 · 쓰다 · 장수처럼 글자 모양은 같지만 뜻이 다른 말을 동형어라 하고, 문장의 앞뒤 말로 뜻을 가린다 (기초 다지기)',ARRAY['기초 다지기(동형어)']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X01','kor',5,'u3',ARRAY['K5-2-u3-C3']::text[],'방언은 표준어를 잘못 말한 틀린 말이라고 여긴다','오랫동안 써 온 우리말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X02','kor',5,'u3',ARRAY['K5-2-u3-C1']::text[],'지역마다 인사말의 말소리가 다르면 뜻도 서로 다르다고 여긴다','뜻은 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X03','kor',5,'u3',ARRAY['K5-2-u3-C2','K5-2-u3-C3']::text[],'표준어는 서울 사람만 쓰는 말이고 방언은 시골에서만 쓰는 말이라고 여긴다','도시에도 방언') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X04','kor',5,'u3',ARRAY['K5-2-u3-C4']::text[],'단원에서 배우는 차례를 거꾸로 알거나 작품 감상부터 한다고 여긴다','뜻 → 상황 → 가치 → 작품') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X05','kor',5,'u3',ARRAY['K5-2-u3-C5']::text[],'방언은 옛사람들이 일부러 말을 바꾸었거나 표준어를 몰라서 생겼다고 여긴다','오가기 어려웠어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X06','kor',5,'u3',ARRAY['K5-2-u3-C6']::text[],'표준어는 방언보다 더 높고 고운 말이라서 정했다고 여긴다','함께 알아듣게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X07','kor',5,'u3',ARRAY['K5-2-u3-C7']::text[],'표준어를 아무나 마음대로 정하거나 글자 수 같은 엉뚱한 기준으로 정한다고 여긴다','두루 · 문법 · 발음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X08','kor',5,'u3',ARRAY['K5-2-u3-C8']::text[],'방언은 어떤 경우에도 표준어가 될 수 없다고 여긴다','멍게를 떠올려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X09','kor',5,'u3',ARRAY['K5-2-u3-C9']::text[],'한 낱말을 가리키는 방언은 하나뿐이라고 여기거나 서로 다른 방언을 다른 대상으로 여긴다','한 낱말, 여러 이름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X10','kor',5,'u3',ARRAY['K5-2-u3-C10']::text[],'방언의 뜻을 근거 없이 짐작만으로 정하고 확인하지 않는다','지역어 누리집') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X11','kor',5,'u3',ARRAY['K5-2-u3-C11']::text[],'같은 지역이면 방언이 모두 똑같아서 다른 답은 틀렸다고 여긴다','정답은 하나가 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X12','kor',5,'u3',ARRAY['K5-2-u3-C12']::text[],'같은 말을 누구에게나 어떤 자리에서나 같은 말투로 써야 한다고 여긴다','누구에게 · 어디서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X13','kor',5,'u3',ARRAY['K5-2-u3-C13']::text[],'여러 지역 사람에게 전하는 방송이나 발표에서도 방언만 쓰면 똑같이 잘 전해진다고 여긴다','모두가 알아듣게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X14','kor',5,'u3',ARRAY['K5-2-u3-C14']::text[],'방언은 쓰면 안 되는 말이라 고향 사람과도 표준어만 써야 한다고 여긴다','친근함과 정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X15','kor',5,'u3',ARRAY['K5-2-u3-C15']::text[],'방언을 표준어로 바꾸어 보는 것을 틀린 말을 고치는 일로 여긴다','고치기가 아니라 선택') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X16','kor',5,'u3',ARRAY['K5-2-u3-C16']::text[],'사용 상황을 조사할 때 쓴 말만 적고 누구에게 · 어떤 상황 · 어떤 사이 · 고른 까닭을 빠뜨린다','세 가지 + 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X17','kor',5,'u3',ARRAY['K5-2-u3-C17']::text[],'방언은 말투만 다를 뿐 마을의 생활 모습은 담겨 있지 않다고 여긴다','말에 담긴 생활') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X18','kor',5,'u3',ARRAY['K5-2-u3-C18']::text[],'방언과 표준어를 짝짓기만 하고 지역의 자연환경 · 먹을거리와 잇지 않는다','자연과 이어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X19','kor',5,'u3',ARRAY['K5-2-u3-C19']::text[],'방언은 쓸모없는 옛말이라 소중하지 않다고 여긴다','지역 문화의 자산') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X20','kor',5,'u3',ARRAY['K5-2-u3-C20','K5-2-u3-C19']::text[],'방언이 사라져도 표준어가 있으니 잃는 것이 없다고 여기거나 방언을 소통을 막는 말로만 본다','함께 잊히는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X21','kor',5,'u3',ARRAY['K5-2-u3-C21']::text[],'작품 속 방언 뜻만 맞히고 줄거리와 인물의 마음을 놓친다','일어난 일 · 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X22','kor',5,'u3',ARRAY['K5-2-u3-C22']::text[],'모르는 방언이 나오면 건너뛰거나 앞뒤 장면을 보지 않고 아무 뜻으로 넘겨짚는다','앞뒤 장면으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X23','kor',5,'u3',ARRAY['K5-2-u3-C23']::text[],'방언을 표준어로 바꾸어 읽어도 느낌까지 똑같다고 여기거나 뜻까지 달라진다고 여긴다','뜻은 같고 느낌은 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X24','kor',5,'u3',ARRAY['K5-2-u3-C24']::text[],'방언이 나오는 작품은 읽기 어려우니 표준어로 쓴 글이 더 좋은 글이라고 여긴다','생동감과 정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X25','kor',5,'u3',ARRAY['K5-2-u3-C25']::text[],'작품을 내 경험과 잇지 않고 근거 없는 느낌이나 작품과 관계없는 말만 한다','내 경험과 이어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X26','kor',5,'u3',ARRAY['K5-2-u3-C26']::text[],'방언으로 만들 수 있는 작품은 정해진 한 가지뿐이라고 여기거나 할 방식을 함께 정하지 않는다','지도 · 노랫말 · 상황극') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X27','kor',5,'u3',ARRAY['K5-2-u3-C27']::text[],'방언 지도 만드는 차례를 섞어 지도부터 꾸미고 주제는 나중에 정한다','주제가 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X28','kor',5,'u3',ARRAY['K5-2-u3-C28']::text[],'방언 지도는 방언을 많이 모을수록 잘 만든 것이라고 여긴다','개수보다 생활') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X29','kor',5,'u3',ARRAY['K5-2-u3-C29']::text[],'방언을 과장해 흉내 내거나 웃음거리로 삼아도 괜찮다고 여긴다','마음을 살려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X30','kor',5,'u3',ARRAY['K5-2-u3-C30']::text[],'표준어와 방언 가운데 어느 한쪽이 언제나 더 좋은 말이라고 여긴다','둘 다 소중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X31','kor',5,'u3',ARRAY['K5-2-u3-C31']::text[],'상황을 살피지 않고 까닭 없이 고르거나 축제면 무조건 방언이라고 외운다','듣는 사람 · 목적') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X32','kor',5,'u3',ARRAY['K5-2-u3-C32']::text[],'동형어를 한 가지 뜻으로만 알고 앞뒤 말을 보지 않는다','앞뒤 말로 가려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#1','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C1',1,'mc','auto','휴게소 안내판의 「어서 오이소.」와 뜻이 같은 표준어 인사말은 어느 것인가요?',ARRAY['K5-2-u3-X02']::text[],false,'{"seq":1,"concept":"K5-2-u3-C1","difficulty":1,"kind":"mc","stem":"휴게소 안내판의 「어서 오이소.」와 뜻이 같은 표준어 인사말은 어느 것인가요?","options":[{"t":"어서 오세요.","correct":true},{"t":"안녕히 가세요.","mis":"K5-2-u3-X02"},{"t":"잘 먹겠습니다.","mis":"K5-2-u3-X02"},{"t":"다녀오겠습니다.","mis":"K5-2-u3-X02"}],"explanation":["헤어질 때 하는 인사예요.","밥 먹기 전 인사예요.","손님을 맞는 같은 뜻이에요."],"asset":{"type":"speech","turns":[{"who":"서울·경기 지역","text":"어서 오세요."},{"who":"충청 지역","text":"어서 오슈."},{"who":"경상 지역","text":"어서 오이소."},{"who":"제주 지역","text":"혼저 옵서예."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#2','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C2',1,'mc','auto','우리나라 사람들이 공통으로 쓸 수 있도록 정한 말을 무엇이라고 하나요?',ARRAY['K5-2-u3-X03','K5-2-u3-X01']::text[],false,'{"seq":2,"concept":"K5-2-u3-C2","difficulty":1,"kind":"mc","stem":"우리나라 사람들이 공통으로 쓸 수 있도록 정한 말을 무엇이라고 하나요?","options":[{"t":"표준어","correct":true},{"t":"방언","mis":"K5-2-u3-X03"},{"t":"외래어","mis":"K5-2-u3-X01"},{"t":"줄임말","mis":"K5-2-u3-X01"}],"explanation":["방언은 특정 지역의 말이에요.","다른 나라에서 온 말이에요.","모두가 함께 쓰도록 정한 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#3','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',1,'mc','auto','특정 지역에서 주로 쓰는, 표준어가 아닌 말을 무엇이라고 하나요?',ARRAY['K5-2-u3-X03','K5-2-u3-X01','K5-2-u3-X29']::text[],false,'{"seq":3,"concept":"K5-2-u3-C3","difficulty":1,"kind":"mc","stem":"특정 지역에서 주로 쓰는, 표준어가 아닌 말을 무엇이라고 하나요?","options":[{"t":"방언","correct":true},{"t":"표준어","mis":"K5-2-u3-X03"},{"t":"높임말","mis":"K5-2-u3-X01"},{"t":"흉내 말","mis":"K5-2-u3-X29"}],"explanation":["표준어는 함께 쓰도록 정한 말이에요.","높이는 말이에요.","지역의 말을 방언이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#4','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',1,'ox','auto','방언은 표준어를 잘못 말한 틀린 말이에요.',ARRAY['K5-2-u3-X01']::text[],false,'{"seq":4,"concept":"K5-2-u3-C3","difficulty":1,"kind":"ox","stem":"방언은 표준어를 잘못 말한 틀린 말이에요.","answer":"X","reason_options":[{"t":"그 지역 사람들이 오랫동안 써 온 우리말이기 때문에","correct":true},{"t":"표준어와 다르면 모두 틀린 말이기 때문에","mis":"K5-2-u3-X01"}],"mis":"K5-2-u3-X01","explanation":["방언도 우리말이에요.","틀린 말이 아니에요.","지역의 삶이 담긴 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#5','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',2,'mc','auto','시 「감재 한 바구니」에 나온 방언과 표준어를 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":5,"concept":"K5-2-u3-C3","difficulty":2,"kind":"mc","stem":"시 「감재 한 바구니」에 나온 방언과 표준어를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"감재 — 감자, 옥시기 — 옥수수","correct":true},{"t":"감재 — 고추, 옥시기 — 옥수수","mis":"K5-2-u3-X10"},{"t":"감재 — 감자, 옥시기 — 감","mis":"K5-2-u3-X10"},{"t":"감재 — 감, 옥시기 — 오이","mis":"K5-2-u3-X10"}],"explanation":["시 넷째 줄을 다시 봐요.","옥시기는 키가 큰 옥수수예요.","시 넷째 줄에 나와요."],"asset":{"type":"passage","lines":["할머니가 밭에서 감재를 캐신다","「올해는 감재가 실하다.」","옆 고랑엔 옥시기가 내 키를 넘었다","감재는 감자, 옥시기는 옥수수","부르는 이름은 달라도","할머니 손에선 똑같이 따끈하다"],"title":"감재 한 바구니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#6','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C1',2,'mc','auto','네 지역의 인사말을 보고 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X02','K5-2-u3-X01']::text[],false,'{"seq":6,"concept":"K5-2-u3-C1","difficulty":2,"kind":"mc","stem":"네 지역의 인사말을 보고 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뜻은 같지만 지역에 따라 끝말과 말소리가 다르다","correct":true},{"t":"지역마다 손님을 맞는 뜻이 다르다","mis":"K5-2-u3-X02"},{"t":"서울·경기 지역 인사만 바른 말이다","mis":"K5-2-u3-X01"},{"t":"제주 지역 인사는 우리말이 아니다","mis":"K5-2-u3-X01"}],"explanation":["뜻은 모두 같아요.","모두 바른 우리말이에요.","말소리만 달라요."],"asset":{"type":"speech","turns":[{"who":"서울·경기 지역","text":"어서 오세요."},{"who":"충청 지역","text":"어서 오슈."},{"who":"경상 지역","text":"어서 오이소."},{"who":"제주 지역","text":"혼저 옵서예."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#7','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C4',2,'match','auto','이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u3-C4","difficulty":2,"kind":"match","stem":"이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.","pairs":[{"l":"표준어와 방언","r":"뜻과 생긴 까닭 알기"},{"l":"사용 상황","r":"누구에게 어떤 자리에서 쓰는지 조사하기"},{"l":"작품 속 방언","r":"방언이 하는 역할 감상하기"}],"mis":"K5-2-u3-X04","explanation":["뜻부터 알아요.","쓰는 자리를 조사해요.","작품에서 감상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#8','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',2,'error','auto','시를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X30','K5-2-u3-X03']::text[],false,'{"seq":8,"concept":"K5-2-u3-C3","difficulty":2,"kind":"error","stem":"시를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「감재는 감자를 틀리게 쓴 말이니 고쳐 읽어야 해.」","correct":true,"mis_target":"K5-2-u3-X01"},{"t":"「부르는 이름은 달라도 똑같이 따끈하다는 줄이 좋아.」","mis":"K5-2-u3-X30"},{"t":"「감재와 옥시기는 강원 지역 방언이야.」","mis":"K5-2-u3-X03"}],"explanation":["시를 잘 느꼈어요.","바르게 알았어요.","방언은 틀린 말이 아니에요."],"asset":{"type":"passage","lines":["할머니가 밭에서 감재를 캐신다","「올해는 감재가 실하다.」","옆 고랑엔 옥시기가 내 키를 넘었다","감재는 감자, 옥시기는 옥수수","부르는 이름은 달라도","할머니 손에선 똑같이 따끈하다"],"title":"감재 한 바구니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#9','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C2',2,'mc','auto','기차역 안내 방송을 어느 지역에서든 표준어로 하는 까닭은 무엇인가요?',ARRAY['K5-2-u3-X06','K5-2-u3-X14','K5-2-u3-X03']::text[],false,'{"seq":9,"concept":"K5-2-u3-C2","difficulty":2,"kind":"mc","stem":"기차역 안내 방송을 어느 지역에서든 표준어로 하는 까닭은 무엇인가요?","options":[{"t":"어느 지역 사람이든 함께 알아들을 수 있게 하려고","correct":true},{"t":"표준어가 방언보다 더 높은 말이라서","mis":"K5-2-u3-X06"},{"t":"방언은 방송에서 쓰면 안 되는 말이라서","mis":"K5-2-u3-X14"},{"t":"안내하는 사람이 모두 서울 사람이라서","mis":"K5-2-u3-X03"}],"explanation":["높고 낮은 말이 아니에요.","방언이 금지된 것은 아니에요.","모두가 알아듣게 하려는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#10','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',3,'mc','auto','할머니께서 「감재 쪄 놨다.」라고 하셨을 때 손녀의 행동으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X29','K5-2-u3-X19']::text[],false,'{"seq":10,"concept":"K5-2-u3-C3","difficulty":3,"kind":"mc","stem":"할머니께서 「감재 쪄 놨다.」라고 하셨을 때 손녀의 행동으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「감재가 뭐예요?」 하고 궁금한 마음으로 여쭈어본다","correct":true},{"t":"틀린 말이라며 표준어로 고쳐 드린다","mis":"K5-2-u3-X01"},{"t":"말투를 흉내 내며 웃는다","mis":"K5-2-u3-X29"},{"t":"모르는 말이니 못 들은 척한다","mis":"K5-2-u3-X19"}],"explanation":["방언은 틀린 말이 아니에요.","흉내는 예의가 아니에요.","모르는 것은 궁금한 마음으로 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#1','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C1',2,'ox','auto','「어서 오슈.」와 「혼저 옵서예.」는 모두 손님을 반갑게 맞는 같은 뜻의 인사예요.',ARRAY['K5-2-u3-X02']::text[],false,'{"seq":1,"concept":"K5-2-u3-C1","difficulty":2,"kind":"ox","stem":"「어서 오슈.」와 「혼저 옵서예.」는 모두 손님을 반갑게 맞는 같은 뜻의 인사예요.","answer":"O","reason_options":[{"t":"지역에 따라 끝말과 말소리만 다를 뿐 뜻은 같기 때문에","correct":true},{"t":"말소리가 다르면 뜻도 달라지기 때문에","mis":"K5-2-u3-X02"}],"mis":"K5-2-u3-X02","explanation":["뜻은 같아요.","말소리만 달라요.","모두 손님을 맞는 인사예요."],"asset":{"type":"speech","turns":[{"who":"서울·경기 지역","text":"어서 오세요."},{"who":"충청 지역","text":"어서 오슈."},{"who":"경상 지역","text":"어서 오이소."},{"who":"제주 지역","text":"혼저 옵서예."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#2','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C4',2,'mc','auto','이 단원에서 표준어와 방언의 뜻을 안 다음에 배우는 내용은 어느 것인가요?',ARRAY['K5-2-u3-X04']::text[],false,'{"seq":2,"concept":"K5-2-u3-C4","difficulty":2,"kind":"mc","stem":"이 단원에서 표준어와 방언의 뜻을 안 다음에 배우는 내용은 어느 것인가요?","options":[{"t":"표준어와 방언을 쓰는 상황 조사하기","correct":true},{"t":"우리 반 방언 지도를 맨 먼저 만들기","mis":"K5-2-u3-X04"},{"t":"문장 성분 찾기","mis":"K5-2-u3-X04"},{"t":"토론 절차 익히기","mis":"K5-2-u3-X04"}],"explanation":["방언 지도는 맨 끝이에요.","지난 단원이에요.","뜻 다음은 쓰는 상황이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#3','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C2',3,'mc','auto','표준어에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X03','K5-2-u3-X06']::text[],false,'{"seq":3,"concept":"K5-2-u3-C2","difficulty":3,"kind":"mc","stem":"표준어에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"어느 지역 사람이든 함께 알아듣도록 정한 말이다","correct":true},{"t":"서울에 사는 사람만 쓰는 말이다","mis":"K5-2-u3-X03"},{"t":"방언보다 더 고운 말이라서 정한 말이다","mis":"K5-2-u3-X06"},{"t":"시골에서는 쓰지 않는 말이다","mis":"K5-2-u3-X03"}],"explanation":["어디서나 써요.","곱고 덜 고운 말이 아니에요.","함께 알아듣게 정한 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#4','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C3',3,'mc','auto','「방언은 시골에서만 쓰는 말이야.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X03','K5-2-u3-X01']::text[],false,'{"seq":4,"concept":"K5-2-u3-C3","difficulty":3,"kind":"mc","stem":"「방언은 시골에서만 쓰는 말이야.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「큰 도시에서도 그 지역에서 주로 쓰는 방언이 있어.」","correct":true},{"t":"「맞아, 도시 사람은 모두 표준어만 써.」","mis":"K5-2-u3-X03"},{"t":"「방언은 틀린 말이니 어디서도 안 써.」","mis":"K5-2-u3-X01"},{"t":"「방언은 할머니들만 쓰는 말이야.」","mis":"K5-2-u3-X03"}],"explanation":["도시에서도 방언을 써요.","방언은 틀린 말이 아니에요.","방언은 그 지역의 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#5','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C1',3,'error','auto','인사말 안내판을 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X02','K5-2-u3-X12']::text[],false,'{"seq":5,"concept":"K5-2-u3-C1","difficulty":3,"kind":"error","stem":"인사말 안내판을 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「어서 오세요만 바른 인사이고 나머지는 잘못된 인사야.」","correct":true,"mis_target":"K5-2-u3-X01"},{"t":"「말소리는 달라도 손님을 반기는 마음은 같아.」","mis":"K5-2-u3-X02"},{"t":"「우리 지역에서는 손님을 어떻게 맞는지 떠올려 보자.」","mis":"K5-2-u3-X12"}],"explanation":["마음은 같아요.","좋은 생각이에요.","모두 바른 우리말이에요."],"asset":{"type":"speech","turns":[{"who":"서울·경기 지역","text":"어서 오세요."},{"who":"충청 지역","text":"어서 오슈."},{"who":"경상 지역","text":"어서 오이소."},{"who":"제주 지역","text":"혼저 옵서예."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#6','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C1',3,'mc','auto','지역마다 인사말이 조금씩 다른 까닭을 짐작한 말 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X02','K5-2-u3-X05','K5-2-u3-X01']::text[],false,'{"seq":6,"concept":"K5-2-u3-C1","difficulty":3,"kind":"mc","stem":"지역마다 인사말이 조금씩 다른 까닭을 짐작한 말 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옛날에는 지역 사이를 오가기 어려워 말이 따로따로 자랐을 것이다","correct":true},{"t":"지역마다 손님을 반기는 마음이 달라서일 것이다","mis":"K5-2-u3-X02"},{"t":"한 지역 사람들이 일부러 말을 바꾸었을 것이다","mis":"K5-2-u3-X05"},{"t":"안내판을 만든 사람이 실수했을 것이다","mis":"K5-2-u3-X01"}],"explanation":["마음은 같아요.","일부러 바꾼 것이 아니에요.","오가기 어려워 달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#7','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C29',3,'mc','auto','방언을 처음 들었을 때의 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X19','K5-2-u3-X01']::text[],false,'{"seq":7,"concept":"K5-2-u3-C29","difficulty":3,"kind":"mc","stem":"방언을 처음 들었을 때의 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"궁금한 마음으로 뜻을 묻고 정다운 느낌을 말해 본다","correct":true},{"t":"말투를 과장해 따라 하며 웃음거리로 삼는다","mis":"K5-2-u3-X29"},{"t":"모르는 말이니 들을 필요가 없다고 여긴다","mis":"K5-2-u3-X19"},{"t":"틀린 말이라고 바로 지적한다","mis":"K5-2-u3-X01"}],"explanation":["흉내는 예의가 아니에요.","들어 볼 가치가 있어요.","궁금한 마음으로 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#8','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C3',4,'essay','teacher','시 「감재 한 바구니」에서 방언을 모두 찾아 표준어로 바꾸어 쓰고, 방언으로 읽을 때의 느낌을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C3","difficulty":4,"kind":"essay","stem":"시 「감재 한 바구니」에서 방언을 모두 찾아 표준어로 바꾸어 쓰고, 방언으로 읽을 때의 느낌을 쓰세요.","answer_guide":{"answer":"예: 방언은 「감재」와 「옥시기」이고, 표준어로 바꾸면 「감자」와 「옥수수」이다. 방언으로 읽으니 할머니가 밭에서 직접 말씀해 주시는 것처럼 정답고 따뜻하게 느껴진다.","scoring_points":["방언 두 개를 찾았는가","표준어로 바르게 바꾸었는가","방언으로 읽을 때의 느낌을 썼는가"]},"explanation":["감재 · 옥시기를 찾아요.","감자 · 옥수수로 바꿔요.","느낌을 써요."],"asset":{"type":"passage","lines":["할머니가 밭에서 감재를 캐신다","「올해는 감재가 실하다.」","옆 고랑엔 옥시기가 내 키를 넘었다","감재는 감자, 옥시기는 옥수수","부르는 이름은 달라도","할머니 손에선 똑같이 따끈하다"],"title":"감재 한 바구니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#9','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C2',4,'essay','teacher','표준어와 방언의 뜻을 각각 쓰고, 두 말이 하는 일의 다른 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u3-C2","difficulty":4,"kind":"essay","stem":"표준어와 방언의 뜻을 각각 쓰고, 두 말이 하는 일의 다른 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 표준어는 우리나라 사람들이 공통으로 쓸 수 있도록 정한 말이고, 방언은 특정 지역에서 주로 쓰는 표준어가 아닌 말이다. 표준어는 어느 지역 사람과도 뜻이 통하게 해 주고, 방언은 그 지역 사람들의 생활과 정을 담아 준다.","scoring_points":["표준어의 뜻을 썼는가","방언의 뜻을 썼는가","하는 일의 다른 점을 썼는가"]},"explanation":["함께 쓰도록 정한 말이에요.","지역에서 주로 쓰는 말이에요.","하는 일을 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#10','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C4',4,'essay','teacher','이 단원에서 가장 알고 싶은 것을 하나 쓰고, 그것을 알면 내 언어생활에 어떤 도움이 될지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u3-C4","difficulty":4,"kind":"essay","stem":"이 단원에서 가장 알고 싶은 것을 하나 쓰고, 그것을 알면 내 언어생활에 어떤 도움이 될지 쓰세요.","answer_guide":{"answer":"예: 우리 할아버지께서 쓰시는 말이 어느 지역 방언인지 알고 싶다. 그것을 알면 할아버지 말씀을 더 잘 알아듣고, 친구들 앞에서는 표준어로, 가족끼리는 정다운 말로 상황에 맞게 골라 쓸 수 있을 것 같다.","scoring_points":["알고 싶은 것을 하나 썼는가","단원 내용과 이어지는가","언어생활에 주는 도움을 썼는가"]},"explanation":["알고 싶은 것을 골라요.","단원과 이어요.","도움을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#1','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C5',1,'mc','auto','「말에도 고향이 있어요」에서 방언이 생긴 까닭으로 든 것은 어느 것인가요?',ARRAY['K5-2-u3-X05']::text[],false,'{"seq":1,"concept":"K5-2-u3-C5","difficulty":1,"kind":"mc","stem":"「말에도 고향이 있어요」에서 방언이 생긴 까닭으로 든 것은 어느 것인가요?","options":[{"t":"산과 강이 많아 지역 사이를 오가기 어려워서","correct":true},{"t":"표준어를 외우기 귀찮아서","mis":"K5-2-u3-X05"},{"t":"한 지역 사람들이 일부러 말을 바꾸어서","mis":"K5-2-u3-X05"},{"t":"책이 많지 않아서","mis":"K5-2-u3-X05"}],"explanation":["글에 없는 까닭이에요.","일부러 바꾼 것이 아니에요.","셋째 문장에 나와요."],"asset":{"type":"passage","lines":["개구리를 어떤 곳에서는 「까구리」, 어떤 곳에서는 「깨고락지」라고 불러요.","이처럼 특정 지역에서 주로 쓰는, 표준어가 아닌 말을 방언이라고 해요.","옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고, 그래서 지역마다 말이 조금씩 달라졌어요.","말이 다르면 서로 뜻을 나누기 어려워서, 어느 지역 사람이든 함께 쓸 수 있도록","정한 말이 표준어예요.","우리나라 표준어는 국립국어원이 사람들이 두루 쓰는지, 문법에 맞는지,","발음하기 편하고 자연스러운지를 살펴 정해요.","「멍게」처럼 한 지역의 방언이 표준어보다 더 널리 쓰여 표준어가 된 말도 있어요."],"title":"말에도 고향이 있어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#2','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C7',1,'mc','auto','우리나라 표준어를 정하는 곳은 어디인가요?',ARRAY['K5-2-u3-X07']::text[],false,'{"seq":2,"concept":"K5-2-u3-C7","difficulty":1,"kind":"mc","stem":"우리나라 표준어를 정하는 곳은 어디인가요?","options":[{"t":"국립국어원","correct":true},{"t":"각 지역 마을 회관","mis":"K5-2-u3-X07"},{"t":"방송국","mis":"K5-2-u3-X07"},{"t":"우리 학교 방송부","mis":"K5-2-u3-X07"}],"explanation":["마을 회관이 아니에요.","방송국은 표준어를 써요.","국립국어원이 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#3','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C9',1,'mc','auto','「까구리」와 「깨고락지」가 가리키는 동물을 표준어로 쓰면 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":3,"concept":"K5-2-u3-C9","difficulty":1,"kind":"mc","stem":"「까구리」와 「깨고락지」가 가리키는 동물을 표준어로 쓰면 어느 것인가요?","options":[{"t":"개구리","correct":true},{"t":"고양이","mis":"K5-2-u3-X10"},{"t":"까치","mis":"K5-2-u3-X10"},{"t":"거북","mis":"K5-2-u3-X10"}],"explanation":["고양이는 겡이 · 고냉이예요.","새가 아니에요.","글 첫 문장에 나와요."],"asset":{"type":"passage","lines":["개구리를 어떤 곳에서는 「까구리」, 어떤 곳에서는 「깨고락지」라고 불러요.","이처럼 특정 지역에서 주로 쓰는, 표준어가 아닌 말을 방언이라고 해요.","옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고, 그래서 지역마다 말이 조금씩 달라졌어요.","말이 다르면 서로 뜻을 나누기 어려워서, 어느 지역 사람이든 함께 쓸 수 있도록","정한 말이 표준어예요.","우리나라 표준어는 국립국어원이 사람들이 두루 쓰는지, 문법에 맞는지,","발음하기 편하고 자연스러운지를 살펴 정해요.","「멍게」처럼 한 지역의 방언이 표준어보다 더 널리 쓰여 표준어가 된 말도 있어요."],"title":"말에도 고향이 있어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#4','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C8',1,'ox','auto','원래 방언이었던 말이 표준어가 되기도 해요.',ARRAY['K5-2-u3-X08']::text[],false,'{"seq":4,"concept":"K5-2-u3-C8","difficulty":1,"kind":"ox","stem":"원래 방언이었던 말이 표준어가 되기도 해요.","answer":"O","reason_options":[{"t":"「멍게」처럼 표준어보다 더 널리 쓰이게 되면 표준어로 인정하기 때문에","correct":true},{"t":"방언은 어떤 경우에도 표준어가 될 수 없기 때문에","mis":"K5-2-u3-X08"}],"mis":"K5-2-u3-X08","explanation":["멍게를 떠올려요.","널리 쓰이면 인정해요.","움직이는 경계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#5','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C6',2,'mc','auto','표준어를 정한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X14','K5-2-u3-X06','K5-2-u3-X07']::text[],false,'{"seq":5,"concept":"K5-2-u3-C6","difficulty":2,"kind":"mc","stem":"표준어를 정한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"사는 지역이 달라도 서로 원활하게 이야기할 수 있게 하려고","correct":true},{"t":"방언을 쓰지 못하게 막으려고","mis":"K5-2-u3-X14"},{"t":"서울 말이 가장 고운 말이라서","mis":"K5-2-u3-X06"},{"t":"글자 수를 줄이려고","mis":"K5-2-u3-X07"}],"explanation":["막으려는 것이 아니에요.","곱고 덜 고운 말이 아니에요.","함께 이야기하려고 정했어요."],"asset":{"type":"passage","lines":["개구리를 어떤 곳에서는 「까구리」, 어떤 곳에서는 「깨고락지」라고 불러요.","이처럼 특정 지역에서 주로 쓰는, 표준어가 아닌 말을 방언이라고 해요.","옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고, 그래서 지역마다 말이 조금씩 달라졌어요.","말이 다르면 서로 뜻을 나누기 어려워서, 어느 지역 사람이든 함께 쓸 수 있도록","정한 말이 표준어예요.","우리나라 표준어는 국립국어원이 사람들이 두루 쓰는지, 문법에 맞는지,","발음하기 편하고 자연스러운지를 살펴 정해요.","「멍게」처럼 한 지역의 방언이 표준어보다 더 널리 쓰여 표준어가 된 말도 있어요."],"title":"말에도 고향이 있어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#6','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C7',2,'mc','auto','국립국어원이 표준어를 정할 때 살펴보는 것이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u3-X07']::text[],false,'{"seq":6,"concept":"K5-2-u3-C7","difficulty":2,"kind":"mc","stem":"국립국어원이 표준어를 정할 때 살펴보는 것이 아닌 것은 어느 것인가요?","options":[{"t":"글자 수가 가장 적은지","correct":true},{"t":"사람들이 두루 쓰는지","mis":"K5-2-u3-X07"},{"t":"문법에 맞는지","mis":"K5-2-u3-X07"},{"t":"발음하기 편하고 자연스러운지","mis":"K5-2-u3-X07"}],"explanation":["살펴보는 기준이에요.","살펴보는 기준이에요.","글자 수는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#7','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C9',2,'mc','auto','다섯 고개의 정답을 표준어로 쓰면 어느 것인가요?',ARRAY['K5-2-u3-X09','K5-2-u3-X10']::text[],false,'{"seq":7,"concept":"K5-2-u3-C9","difficulty":2,"kind":"mc","stem":"다섯 고개의 정답을 표준어로 쓰면 어느 것인가요?","options":[{"t":"김치","correct":true},{"t":"부추","mis":"K5-2-u3-X09"},{"t":"감자","mis":"K5-2-u3-X09"},{"t":"고추","mis":"K5-2-u3-X10"}],"explanation":["부추는 정구지 · 소풀이에요.","감자는 감재예요.","짐끼 · 짐치는 김치예요."],"asset":{"type":"speech","turns":[{"who":"첫째 고개","text":"제주 지역에서는 「짐끼」라고 해요."},{"who":"둘째 고개","text":"강원 지역에서는 「짐치」라고 해요."},{"who":"셋째 고개","text":"반찬으로 먹고 매운맛이 나요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#8','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C9',2,'match','auto','방언과 뜻이 같은 표준어를 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C9","difficulty":2,"kind":"match","stem":"방언과 뜻이 같은 표준어를 알맞게 이으세요.","pairs":[{"l":"정구지","r":"부추"},{"l":"고냉이","r":"고양이"},{"l":"까구리","r":"개구리"}],"mis":"K5-2-u3-X09","explanation":["경상 지역에서 써요.","강원 지역에서 써요.","한 낱말을 여러 이름으로 불러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#9','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C8',2,'error','auto','「멍게」에 대한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X08','K5-2-u3-X09','K5-2-u3-X07']::text[],false,'{"seq":9,"concept":"K5-2-u3-C8","difficulty":2,"kind":"error","stem":"「멍게」에 대한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「멍게는 방언이라서 지금도 표준어로 쓸 수 없어.」","correct":true,"mis_target":"K5-2-u3-X08"},{"t":"「원래 경상 지역 방언이었어.」","mis":"K5-2-u3-X09"},{"t":"「우렁쉥이보다 더 널리 쓰여 표준어가 되었어.」","mis":"K5-2-u3-X07"}],"explanation":["맞는 말이에요.","맞는 말이에요.","지금은 표준어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#10','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C10',3,'mc','auto','어떤 지역에서 「나무」를 어떻게 부르는지 정확히 알아보는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X10','K5-2-u3-X11']::text[],false,'{"seq":10,"concept":"K5-2-u3-C10","difficulty":3,"kind":"mc","stem":"어떤 지역에서 「나무」를 어떻게 부르는지 정확히 알아보는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국립국어원 지역어 누리집에서 「나무」를 검색해 본다","correct":true},{"t":"뜻이 비슷한 말을 짐작해서 적는다","mis":"K5-2-u3-X10"},{"t":"친구 한 명의 말만 듣고 정답으로 정한다","mis":"K5-2-u3-X11"},{"t":"표준어 사전에서 「나무」의 뜻만 찾는다","mis":"K5-2-u3-X10"}],"explanation":["짐작은 확인이 필요해요.","한 사람 말만으로는 부족해요.","지역별 방언이 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#1','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C5',2,'ox','auto','옛날 사람들이 일부러 지역마다 다른 말을 만들어 써서 방언이 생겼어요.',ARRAY['K5-2-u3-X05']::text[],false,'{"seq":1,"concept":"K5-2-u3-C5","difficulty":2,"kind":"ox","stem":"옛날 사람들이 일부러 지역마다 다른 말을 만들어 써서 방언이 생겼어요.","answer":"X","reason_options":[{"t":"오가기 어려워 이야기할 기회가 적다 보니 말이 자연스럽게 달라졌기 때문에","correct":true},{"t":"지역끼리 서로 말이 통하지 않게 하려고 정했기 때문에","mis":"K5-2-u3-X05"}],"mis":"K5-2-u3-X05","explanation":["일부러가 아니에요.","자연스럽게 달라졌어요.","지리적 특성 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#2','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C9',2,'mc','auto','「겡이」, 「고냉이」, 「궤이」를 보고 알 수 있는 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X09','K5-2-u3-X11','K5-2-u3-X03']::text[],false,'{"seq":2,"concept":"K5-2-u3-C9","difficulty":2,"kind":"mc","stem":"「겡이」, 「고냉이」, 「궤이」를 보고 알 수 있는 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 낱말을 가리키는 방언이 지역마다 여러 가지일 수 있다","correct":true},{"t":"세 말은 서로 다른 동물을 가리킨다","mis":"K5-2-u3-X09"},{"t":"셋 가운데 하나만 맞는 방언이다","mis":"K5-2-u3-X11"},{"t":"세 말은 모두 표준어이다","mis":"K5-2-u3-X03"}],"explanation":["모두 고양이예요.","모두 그 지역의 방언이에요.","한 낱말, 여러 이름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#3','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C5',3,'mc','auto','옛날에도 지금처럼 교통과 통신이 발달했다면 방언은 어떠했을지 짐작한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X05','K5-2-u3-X06']::text[],false,'{"seq":3,"concept":"K5-2-u3-C5","difficulty":3,"kind":"mc","stem":"옛날에도 지금처럼 교통과 통신이 발달했다면 방언은 어떠했을지 짐작한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지역 사이에 자주 오가 말이 지금보다 덜 달랐을 것이다","correct":true},{"t":"방언이 지금보다 훨씬 많아졌을 것이다","mis":"K5-2-u3-X05"},{"t":"표준어가 저절로 사라졌을 것이다","mis":"K5-2-u3-X06"},{"t":"교통과 말은 아무 관계가 없을 것이다","mis":"K5-2-u3-X05"}],"explanation":["오가면 말이 닮아 가요.","표준어와 관계없어요.","오가기 어려워 말이 달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#4','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C6',3,'mc','auto','표준어가 없다면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X19','K5-2-u3-X08','K5-2-u3-X06']::text[],false,'{"seq":4,"concept":"K5-2-u3-C6","difficulty":3,"kind":"mc","stem":"표준어가 없다면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다른 지역 사람과 공식적인 소식을 나눌 때 뜻을 잘못 알아들을 수 있다","correct":true},{"t":"모든 사람이 방언을 잊어버린다","mis":"K5-2-u3-X19"},{"t":"방언이 모두 표준어가 된다","mis":"K5-2-u3-X08"},{"t":"아무 문제도 생기지 않는다","mis":"K5-2-u3-X06"}],"explanation":["방언은 그대로예요.","방언이 다 바뀌지 않아요.","뜻을 나누기 어려워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#5','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C7',3,'error','auto','표준어를 정하는 방법에 대한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X07','K5-2-u3-X06','K5-2-u3-X08']::text[],false,'{"seq":5,"concept":"K5-2-u3-C7","difficulty":3,"kind":"error","stem":"표준어를 정하는 방법에 대한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「목소리가 큰 사람들이 쓰는 말을 표준어로 정해.」","correct":true,"mis_target":"K5-2-u3-X07"},{"t":"「사람들이 두루 쓰는지 살펴.」","mis":"K5-2-u3-X06"},{"t":"「문법에 맞고 발음이 자연스러운지도 봐.」","mis":"K5-2-u3-X08"}],"explanation":["기준이 맞아요.","기준이 맞아요.","목소리 크기는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#6','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C11',3,'mc','auto','방언 카드에 「가새기 — 경상 지역 — 가위」라고 쓴 친구와, 경상 지역 할머니께서 가위를 다르게 말씀하신다는 친구가 있어요. 가장 알맞은 생각은 어느 것인가요?',ARRAY['K5-2-u3-X11','K5-2-u3-X01','K5-2-u3-X10']::text[],false,'{"seq":6,"concept":"K5-2-u3-C11","difficulty":3,"kind":"mc","stem":"방언 카드에 「가새기 — 경상 지역 — 가위」라고 쓴 친구와, 경상 지역 할머니께서 가위를 다르게 말씀하신다는 친구가 있어요. 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"같은 지역 안에서도 마을마다 다를 수 있으니 누리집 같은 근거를 함께 찾아본다","correct":true},{"t":"카드를 쓴 친구가 틀렸으니 카드를 지운다","mis":"K5-2-u3-X11"},{"t":"할머니 말씀이 틀렸다고 말씀드린다","mis":"K5-2-u3-X01"},{"t":"둘 다 방언이니 아무렇게나 적어도 된다","mis":"K5-2-u3-X10"}],"explanation":["둘 다 맞을 수 있어요.","할머니 말씀도 그 마을의 방언이에요.","근거로 함께 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#7','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C10',3,'mc','auto','방언 카드 놀이에서 친구가 표준어를 잘 맞히지 못할 때 도와주는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X10']::text[],false,'{"seq":7,"concept":"K5-2-u3-C10","difficulty":3,"kind":"mc","stem":"방언 카드 놀이에서 친구가 표준어를 잘 맞히지 못할 때 도와주는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"표준어의 첫 글자나 초성을 알려 준다","correct":true},{"t":"맞히지 못하면 놀이에서 빼 준다","mis":"K5-2-u3-X29"},{"t":"방언을 과장해 다시 흉내 낸다","mis":"K5-2-u3-X29"},{"t":"아무 표준어나 말하게 한다","mis":"K5-2-u3-X10"}],"explanation":["함께 해야 해요.","흉내는 예의가 아니에요.","첫 글자나 초성으로 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#8','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C5',4,'essay','teacher','방언이 생긴 까닭과 표준어를 정한 까닭을 이어서 설명하는 글을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C5","difficulty":4,"kind":"essay","stem":"방언이 생긴 까닭과 표준어를 정한 까닭을 이어서 설명하는 글을 쓰세요.","answer_guide":{"answer":"예: 옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고, 서로 이야기할 기회가 적어 지역마다 말이 조금씩 달라져 방언이 생겼다. 그런데 말이 다르면 다른 지역 사람과 뜻을 나누기 어렵기 때문에, 어디에 살든 원활하게 이야기할 수 있도록 표준어를 정했다.","scoring_points":["방언이 생긴 까닭을 썼는가","표준어를 정한 까닭을 썼는가","두 까닭을 앞뒤로 이어 설명했는가"]},"explanation":["지리적 특성이에요.","원활한 의사소통이에요.","이어서 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#9','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C8',4,'essay','teacher','「멍게」가 표준어가 된 과정을 설명하고, 이를 보고 표준어와 방언의 관계에 대해 알 수 있는 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u3-C8","difficulty":4,"kind":"essay","stem":"「멍게」가 표준어가 된 과정을 설명하고, 이를 보고 표준어와 방언의 관계에 대해 알 수 있는 점을 쓰세요.","answer_guide":{"answer":"예: 멍게는 원래 경상 지역 방언이었지만 표준어 「우렁쉥이」보다 더 널리 쓰이게 되어 지금은 둘 다 표준어가 되었다. 이를 보면 표준어와 방언 사이는 꽉 막힌 벽이 아니라, 사람들이 두루 쓰는 말에 따라 움직이는 경계라는 것을 알 수 있다.","scoring_points":["원래 방언이었음을 썼는가","더 널리 쓰여 표준어가 되었음을 썼는가","둘의 관계를 정리했는가"]},"explanation":["원래 지역을 써요.","널리 쓰인 것이 까닭이에요.","움직이는 경계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#10','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C9',4,'essay','teacher','내가 아는 낱말로 방언 고개 문제를 만들어 쓰세요. 고개를 셋 이상 만들고, 고개마다 지역과 방언 또는 특징을 넣은 뒤 정답을 표준어로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u3-C9","difficulty":4,"kind":"essay","stem":"내가 아는 낱말로 방언 고개 문제를 만들어 쓰세요. 고개를 셋 이상 만들고, 고개마다 지역과 방언 또는 특징을 넣은 뒤 정답을 표준어로 쓰세요.","answer_guide":{"answer":"예: 첫째 고개 — 경상 지역에서는 「정구지」라고 해요. 둘째 고개 — 전라 지역에서는 「소풀」이라고 해요. 셋째 고개 — 부침개에 넣는 초록색 채소예요. 정답 — 부추.","scoring_points":["고개를 셋 이상 만들었는가","지역과 방언 또는 특징을 넣었는가","정답을 표준어로 썼는가"]},"explanation":["고개를 만들어요.","지역과 방언을 넣어요.","정답은 표준어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#1','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C14',1,'mc','auto','「설날, 외할머니 댁에서」에서 엄마가 외삼촌과 이야기할 때 방언을 쓴 까닭은 무엇인가요?',ARRAY['K5-2-u3-X14','K5-2-u3-X03','K5-2-u3-X13']::text[],false,'{"seq":1,"concept":"K5-2-u3-C14","difficulty":1,"kind":"mc","stem":"「설날, 외할머니 댁에서」에서 엄마가 외삼촌과 이야기할 때 방언을 쓴 까닭은 무엇인가요?","options":[{"t":"고향 사람과 이야기하면 더 가깝게 느껴져서","correct":true},{"t":"표준어를 몰라서","mis":"K5-2-u3-X14"},{"t":"외삼촌이 표준어를 못 알아들어서","mis":"K5-2-u3-X03"},{"t":"방송에 나가야 해서","mis":"K5-2-u3-X13"}],"explanation":["엄마는 표준어도 써요.","외삼촌도 표준어를 알아요.","넷째 · 다섯째 줄에 나와요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#2','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C13',1,'mc','auto','기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 표준어로 말한 까닭은 무엇인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X14','K5-2-u3-X06']::text[],false,'{"seq":2,"concept":"K5-2-u3-C13","difficulty":1,"kind":"mc","stem":"기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 표준어로 말한 까닭은 무엇인가요?","options":[{"t":"전국 사람에게 똑같이 정확히 전하려고","correct":true},{"t":"방언은 틀린 말이라서","mis":"K5-2-u3-X01"},{"t":"고향 사람과 가까워지려고","mis":"K5-2-u3-X14"},{"t":"표준어가 더 높은 말이라서","mis":"K5-2-u3-X06"}],"explanation":["방언은 틀린 말이 아니에요.","그건 엄마의 까닭이에요.","여러 지역 사람에게 전해요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#3','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C15',1,'blank','auto','「길 막혀서 힘들었슈?」를 표준어로 바꾸면 「길 막혀서 ( ? )」예요. 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u3-X15','K5-2-u3-X22','K5-2-u3-X09']::text[],false,'{"seq":3,"concept":"K5-2-u3-C15","difficulty":1,"kind":"blank","stem":"「길 막혀서 힘들었슈?」를 표준어로 바꾸면 「길 막혀서 ( ? )」예요. 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"힘들었어요?","correct":true},{"t":"힘들었슈.","mis":"K5-2-u3-X15"},{"t":"힘들겠지?","mis":"K5-2-u3-X22"},{"t":"힘들었당께.","mis":"K5-2-u3-X09"}],"explanation":["그대로예요.","뜻이 바뀌었어요.","「~슈」는 「~어요」예요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#4','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C12',1,'ox','auto','뜻이 같은 말이라도 누구에게, 어떤 자리에서 말하느냐에 따라 표준어나 방언으로 골라 쓸 수 있어요.',ARRAY['K5-2-u3-X12']::text[],false,'{"seq":4,"concept":"K5-2-u3-C12","difficulty":1,"kind":"ox","stem":"뜻이 같은 말이라도 누구에게, 어떤 자리에서 말하느냐에 따라 표준어나 방언으로 골라 쓸 수 있어요.","answer":"O","reason_options":[{"t":"듣는 사람과 상황에 따라 어울리는 말이 다르기 때문에","correct":true},{"t":"어떤 자리에서든 같은 말투로만 말해야 하기 때문에","mis":"K5-2-u3-X12"}],"mis":"K5-2-u3-X12","explanation":["자리에 따라 골라요.","듣는 사람이 기준이에요.","같은 뜻도 달리 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#5','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C13',2,'mc','auto','주로 표준어를 쓰는 상황으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X14']::text[],false,'{"seq":5,"concept":"K5-2-u3-C13","difficulty":2,"kind":"mc","stem":"주로 표준어를 쓰는 상황으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학교 방송으로 전교생에게 행사를 안내할 때","correct":true},{"t":"고향 친구와 오랜만에 통화할 때","mis":"K5-2-u3-X14"},{"t":"시장에서 단골손님과 이야기할 때","mis":"K5-2-u3-X14"},{"t":"지역 축제에서 고장 분위기를 살려 인사할 때","mis":"K5-2-u3-X14"}],"explanation":["방언을 쓰기도 해요.","방언을 쓰기도 해요.","여럿에게 정확히 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#6','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C14',2,'mc','auto','시장 상인이 단골손님에게 그 지역 방언으로 말하면 어떤 점이 좋을까요?',ARRAY['K5-2-u3-X13','K5-2-u3-X01','K5-2-u3-X12']::text[],false,'{"seq":6,"concept":"K5-2-u3-C14","difficulty":2,"kind":"mc","stem":"시장 상인이 단골손님에게 그 지역 방언으로 말하면 어떤 점이 좋을까요?","options":[{"t":"손님이 더 친근하고 정답게 느낄 수 있다","correct":true},{"t":"손님이 뜻을 하나도 알아듣지 못한다","mis":"K5-2-u3-X13"},{"t":"상인이 표준어를 모른다는 것을 알린다","mis":"K5-2-u3-X01"},{"t":"물건값이 저절로 싸진다","mis":"K5-2-u3-X12"}],"explanation":["같은 지역 사람은 알아들어요.","표준어를 몰라서가 아니에요.","정을 나누는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#7','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C15',2,'mc','auto','방언 문장을 표준어로 바꾸어 보는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X15','K5-2-u3-X14','K5-2-u3-X07']::text[],false,'{"seq":7,"concept":"K5-2-u3-C15","difficulty":2,"kind":"mc","stem":"방언 문장을 표준어로 바꾸어 보는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 뜻이 상황에 따라 다르게 골라 쓰인다는 것을 알기 위해서","correct":true},{"t":"방언이 틀린 말이라 고치기 위해서","mis":"K5-2-u3-X15"},{"t":"방언을 쓰지 못하게 하려고","mis":"K5-2-u3-X14"},{"t":"글자 수를 줄이려고","mis":"K5-2-u3-X07"}],"explanation":["고치기가 아니에요.","금지하려는 게 아니에요.","상황에 따른 선택을 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#8','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C16',2,'match','auto','「설날, 외할머니 댁에서」의 엄마 말을 조사표로 정리했어요. 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C16","difficulty":2,"kind":"match","stem":"「설날, 외할머니 댁에서」의 엄마 말을 조사표로 정리했어요. 알맞게 이으세요.","pairs":[{"l":"누구에게","r":"외삼촌에게"},{"l":"어떤 상황에서","r":"설날 고향 집 마당에서"},{"l":"어떤 사이","r":"어릴 때부터 함께 자란 가족"}],"mis":"K5-2-u3-X16","explanation":["듣는 사람이에요.","장소와 자리예요.","관계예요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#9','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C12',2,'error','auto','축제 날 두 무대를 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X12','K5-2-u3-X13','K5-2-u3-X14']::text[],false,'{"seq":9,"concept":"K5-2-u3-C12","difficulty":2,"kind":"error","stem":"축제 날 두 무대를 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「방송부원처럼 어르신도 표준어로만 말해야 했어.」","correct":true,"mis_target":"K5-2-u3-X12"},{"t":"「방송부원은 전교생에게 정확히 안내하려고 표준어를 썼어.」","mis":"K5-2-u3-X13"},{"t":"「어르신은 고향 말로 정다운 분위기를 살렸어.」","mis":"K5-2-u3-X14"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","자리마다 어울리는 말이 달라요."],"asset":{"type":"passage","lines":["학교 축제 날, 방송실에서는 방송부원이 전교생에게 행사 순서를","또박또박 표준어로 안내했다.","운동장 무대에서는 마을 어르신이 고향 말로 농악 공연을 소개했다.","어르신의 말에 관객들이 웃으며 손뼉을 쳤다."],"title":"축제 날 두 무대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#10','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C16',3,'mc','auto','표준어 · 방언 사용 상황 조사표에 꼭 함께 적어야 할 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X16','K5-2-u3-X29']::text[],false,'{"seq":10,"concept":"K5-2-u3-C16","difficulty":3,"kind":"mc","stem":"표준어 · 방언 사용 상황 조사표에 꼭 함께 적어야 할 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 말을 고른 까닭","correct":true},{"t":"말한 사람의 키","mis":"K5-2-u3-X16"},{"t":"조사한 날의 날씨","mis":"K5-2-u3-X16"},{"t":"방언을 흉내 낸 우스운 그림","mis":"K5-2-u3-X29"}],"explanation":["관계없어요.","관계없어요.","까닭을 적어야 상황과 말이 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#1','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C15',2,'ox','auto','방언은 고쳐야 할 말이라서 언제나 표준어로 바꾸어 말해야 해요.',ARRAY['K5-2-u3-X15']::text[],false,'{"seq":1,"concept":"K5-2-u3-C15","difficulty":2,"kind":"ox","stem":"방언은 고쳐야 할 말이라서 언제나 표준어로 바꾸어 말해야 해요.","answer":"X","reason_options":[{"t":"상황에 따라 방언이 더 어울리는 자리도 있기 때문에","correct":true},{"t":"방언은 틀린 말이기 때문에","mis":"K5-2-u3-X15"}],"mis":"K5-2-u3-X15","explanation":["고칠 말이 아니에요.","자리에 따라 골라요.","방언이 어울리는 자리도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#2','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C12',2,'mc','auto','「나」가 엄마의 말투에 고개를 갸웃한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":2,"concept":"K5-2-u3-C12","difficulty":2,"kind":"mc","stem":"「나」가 엄마의 말투에 고개를 갸웃한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"집에서와 다른 말투를 엄마가 고향 사람에게 썼기 때문에","correct":true},{"t":"엄마가 아파 보였기 때문에","mis":"K5-2-u3-X21"},{"t":"외삼촌이 늦게 왔기 때문에","mis":"K5-2-u3-X21"},{"t":"뉴스에서 눈 소식이 나왔기 때문에","mis":"K5-2-u3-X21"}],"explanation":["글에 없어요.","일찍 왔다고 했어요.","셋째 줄을 봐요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#3','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C13',3,'mc','auto','여러 지역 사람이 함께 듣는 방송에서 방언만 쓰면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X13','K5-2-u3-X12']::text[],false,'{"seq":3,"concept":"K5-2-u3-C13","difficulty":3,"kind":"mc","stem":"여러 지역 사람이 함께 듣는 방송에서 방언만 쓰면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말이 달라 내용을 잘 알아듣지 못하는 사람이 생길 수 있다","correct":true},{"t":"모든 사람이 더 정확히 알아듣는다","mis":"K5-2-u3-X13"},{"t":"방송이 저절로 짧아진다","mis":"K5-2-u3-X13"},{"t":"아무 일도 생기지 않는다","mis":"K5-2-u3-X12"}],"explanation":["오히려 어려워요.","관계없어요.","알아듣기 어려운 사람이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#4','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C14',3,'mc','auto','방언을 쓰기도 하는 상황끼리 바르게 묶은 것은 어느 것인가요?',ARRAY['K5-2-u3-X13','K5-2-u3-X12']::text[],false,'{"seq":4,"concept":"K5-2-u3-C14","difficulty":3,"kind":"mc","stem":"방언을 쓰기도 하는 상황끼리 바르게 묶은 것은 어느 것인가요?","options":[{"t":"고향 친구와 통화 · 지역 축제 사회","correct":true},{"t":"뉴스 일기 예보 · 전교생 앞 발표","mis":"K5-2-u3-X13"},{"t":"학교 방송 안내 · 고향 친구와 통화","mis":"K5-2-u3-X12"},{"t":"전국 어린이 회의 · 시장 단골 대화","mis":"K5-2-u3-X12"}],"explanation":["둘 다 표준어 자리예요.","학교 방송은 표준어예요.","정을 나누는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#5','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C16',3,'error','auto','조사표를 쓴 친구들이에요. 상황과 말의 관계가 잘 드러나지 않게 쓴 것은 어느 것인가요?',ARRAY['K5-2-u3-X16','K5-2-u3-X14','K5-2-u3-X13']::text[],false,'{"seq":5,"concept":"K5-2-u3-C16","difficulty":3,"kind":"error","stem":"조사표를 쓴 친구들이에요. 상황과 말의 관계가 잘 드러나지 않게 쓴 것은 어느 것인가요?","options":[{"t":"「할아버지 — 방언」","correct":true,"mis_target":"K5-2-u3-X16"},{"t":"「할아버지께서 고향 친구분과 통화하실 때 — 방언 — 편하고 정답게 이야기하시려고」","mis":"K5-2-u3-X14"},{"t":"「뉴스에서 전국 날씨를 전할 때 — 표준어 — 모두가 알아듣게 하려고」","mis":"K5-2-u3-X13"}],"explanation":["상황과 까닭이 있어요.","상황과 까닭이 있어요.","상황 · 사이 · 까닭이 빠졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#6','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C12',3,'mc','auto','학교 방송부가 「우리 고장 소개」 방송을 만들 때 두 말을 함께 살리는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X13','K5-2-u3-X15','K5-2-u3-X12']::text[],false,'{"seq":6,"concept":"K5-2-u3-C12","difficulty":3,"kind":"mc","stem":"학교 방송부가 「우리 고장 소개」 방송을 만들 때 두 말을 함께 살리는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"소개는 표준어로 하고 어르신 인터뷰는 방언 그대로 싣는다","correct":true},{"t":"처음부터 끝까지 방언으로만 한다","mis":"K5-2-u3-X13"},{"t":"어르신 인터뷰도 모두 표준어로 고쳐 싣는다","mis":"K5-2-u3-X15"},{"t":"두 의견이 다르니 방송을 하지 않는다","mis":"K5-2-u3-X12"}],"explanation":["다른 지역 사람이 알아듣기 어려워요.","고장의 분위기가 줄어요.","듣는 사람과 목적에 맞게 함께 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#7','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C15',3,'mc','auto','「오빠, 일찍 왔네유.」를 고향 집 마당에서와 학교 발표에서 읽어 본 뒤 알 수 있는 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X15','K5-2-u3-X23','K5-2-u3-X12']::text[],false,'{"seq":7,"concept":"K5-2-u3-C15","difficulty":3,"kind":"mc","stem":"「오빠, 일찍 왔네유.」를 고향 집 마당에서와 학교 발표에서 읽어 본 뒤 알 수 있는 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 말도 자리에 따라 어울리는 정도가 다르다","correct":true},{"t":"방언은 어디서 읽어도 틀린 문장이다","mis":"K5-2-u3-X15"},{"t":"표준어로 바꾸면 뜻이 달라진다","mis":"K5-2-u3-X23"},{"t":"두 자리에서 느낌이 똑같다","mis":"K5-2-u3-X12"}],"explanation":["틀린 문장이 아니에요.","뜻은 같아요.","자리마다 어울림이 달라요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#8','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C13',4,'essay','teacher','여러 사람에게 정보를 전하는 방송에서 방언만 쓰면 어떤 일이 생길지와, 같은 지역 사람끼리 방언을 쓰면 좋은 점을 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C13","difficulty":4,"kind":"essay","stem":"여러 사람에게 정보를 전하는 방송에서 방언만 쓰면 어떤 일이 생길지와, 같은 지역 사람끼리 방언을 쓰면 좋은 점을 함께 쓰세요.","answer_guide":{"answer":"예: 여러 지역 사람이 듣는 방송에서 방언만 쓰면 말이 달라 내용을 제대로 이해하지 못하는 사람이 생길 수 있다. 하지만 같은 지역 사람끼리 방언을 쓰면 어릴 때부터 쓰던 말로 이야기하니 더 친근하고 정답게 마음을 나눌 수 있다.","scoring_points":["방송에서 생길 수 있는 일을 썼는가","같은 지역 사람끼리의 좋은 점을 썼는가","두 가지를 함께 견주었는가"]},"explanation":["알아듣기 어려워요.","친근하고 정다워요.","둘을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#9','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C16',4,'essay','teacher','표준어나 방언을 쓰거나 들어 본 경험을 하나 골라 누구에게 · 어떤 상황에서 · 어떤 사이에서 썼는지와 그 말을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u3-C16","difficulty":4,"kind":"essay","stem":"표준어나 방언을 쓰거나 들어 본 경험을 하나 골라 누구에게 · 어떤 상황에서 · 어떤 사이에서 썼는지와 그 말을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 할머니께서 이모와 전화하실 때 고향 말을 쓰셨다. 누구에게 — 이모에게, 어떤 상황에서 — 명절 안부를 묻는 전화, 어떤 사이 — 같은 고향에서 자란 가족. 서로 편하고 정답게 이야기하시려고 방언을 고르신 것 같다.","scoring_points":["누구에게를 썼는가","어떤 상황 · 어떤 사이를 썼는가","그 말을 고른 까닭을 썼는가"]},"explanation":["듣는 사람을 써요.","상황과 관계를 써요.","까닭까지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#10','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C12',4,'essay','teacher','「설날, 외할머니 댁에서」의 엄마 말과 기상 캐스터의 말을 견주어, 말을 고르는 기준이 무엇인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u3-C12","difficulty":4,"kind":"essay","stem":"「설날, 외할머니 댁에서」의 엄마 말과 기상 캐스터의 말을 견주어, 말을 고르는 기준이 무엇인지 쓰세요.","answer_guide":{"answer":"예: 엄마는 고향 사람인 외삼촌과 더 가깝게 이야기하려고 방언을 썼고, 기상 캐스터는 전국 사람에게 똑같이 정확히 전하려고 표준어를 썼다. 이를 보면 말을 고르는 기준은 좋고 나쁨이 아니라 누구에게, 어떤 자리에서, 무엇을 위해 말하느냐이다.","scoring_points":["엄마가 방언을 쓴 까닭을 썼는가","기상 캐스터가 표준어를 쓴 까닭을 썼는가","말을 고르는 기준을 정리했는가"]},"explanation":["가까움이에요.","정확히 전하기예요.","기준은 듣는 사람과 자리예요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#1','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C17',1,'mc','auto','보고서에서 집과 집 사이 좁은 돌담길을 마을 사람들이 부른 말은 어느 것인가요?',ARRAY['K5-2-u3-X17']::text[],false,'{"seq":1,"concept":"K5-2-u3-C17","difficulty":1,"kind":"mc","stem":"보고서에서 집과 집 사이 좁은 돌담길을 마을 사람들이 부른 말은 어느 것인가요?","options":[{"t":"올레","correct":true},{"t":"정낭","mis":"K5-2-u3-X17"},{"t":"삼춘","mis":"K5-2-u3-X17"},{"t":"물허벅","mis":"K5-2-u3-X17"}],"explanation":["대문 가로대예요.","마을 어른이에요.","둘째 줄에 나와요."],"asset":{"type":"passage","lines":["우리 모둠은 체험 학습으로 제주 지역의 돌담 마을에 다녀왔다.","집과 집 사이 좁은 돌담길을 마을 사람들은 「올레」라고 불렀다.","집 앞에는 대문 대신 긴 나무 막대 「정낭」이 걸려 있었는데,","걸린 막대 수로 주인이 집에 있는지 알 수 있다고 했다.","안내해 주신 어른을 마을 아이들은 「삼춘」이라고 불렀다.","피를 나누지 않아도 가족처럼 부르는 말이라고 한다.","박물관에서는 물을 길어 나르던 동이 「물허벅」을 보았다.","방언 하나하나에 이 마을의 자연과 생활이 담겨 있다는 것을 알게 되었다."],"title":"돌담 마을 체험 학습 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#2','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C17',1,'mc','auto','「정낭」에 걸린 막대 수로 알 수 있는 것은 무엇인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":2,"concept":"K5-2-u3-C17","difficulty":1,"kind":"mc","stem":"「정낭」에 걸린 막대 수로 알 수 있는 것은 무엇인가요?","options":[{"t":"집주인이 집에 있는지","correct":true},{"t":"마을의 나이","mis":"K5-2-u3-X21"},{"t":"바닷물의 높이","mis":"K5-2-u3-X21"},{"t":"오늘의 날씨","mis":"K5-2-u3-X21"}],"explanation":["글에 없어요.","글에 없어요.","넷째 줄에 나와요."],"asset":{"type":"passage","lines":["우리 모둠은 체험 학습으로 제주 지역의 돌담 마을에 다녀왔다.","집과 집 사이 좁은 돌담길을 마을 사람들은 「올레」라고 불렀다.","집 앞에는 대문 대신 긴 나무 막대 「정낭」이 걸려 있었는데,","걸린 막대 수로 주인이 집에 있는지 알 수 있다고 했다.","안내해 주신 어른을 마을 아이들은 「삼춘」이라고 불렀다.","피를 나누지 않아도 가족처럼 부르는 말이라고 한다.","박물관에서는 물을 길어 나르던 동이 「물허벅」을 보았다.","방언 하나하나에 이 마을의 자연과 생활이 담겨 있다는 것을 알게 되었다."],"title":"돌담 마을 체험 학습 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#3','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C18',1,'mc','auto','갯벌이 넓은 전라 지역에서 갯벌을 가리키는 방언은 어느 것인가요?',ARRAY['K5-2-u3-X09']::text[],false,'{"seq":3,"concept":"K5-2-u3-C18","difficulty":1,"kind":"mc","stem":"갯벌이 넓은 전라 지역에서 갯벌을 가리키는 방언은 어느 것인가요?","options":[{"t":"뻘","correct":true},{"t":"돔배기","mis":"K5-2-u3-X09"},{"t":"정낭","mis":"K5-2-u3-X09"},{"t":"찌짐","mis":"K5-2-u3-X09"}],"explanation":["상어고기예요.","대문 가로대예요.","부침개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#4','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C19',1,'ox','auto','방언은 지역의 문화를 드러내는 소중한 자산이에요.',ARRAY['K5-2-u3-X17']::text[],false,'{"seq":4,"concept":"K5-2-u3-C19","difficulty":1,"kind":"ox","stem":"방언은 지역의 문화를 드러내는 소중한 자산이에요.","answer":"O","reason_options":[{"t":"지역의 자연과 생활, 사람들의 정이 담겨 있기 때문에","correct":true},{"t":"말투만 다를 뿐 담긴 것이 없기 때문에","mis":"K5-2-u3-X17"}],"mis":"K5-2-u3-X17","explanation":["방언에는 생활이 담겨요.","자연도 담겨요.","지역 문화의 자산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#5','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C17',2,'mc','auto','「삼춘」이라는 말에서 짐작할 수 있는 마을의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X17']::text[],false,'{"seq":5,"concept":"K5-2-u3-C17","difficulty":2,"kind":"mc","stem":"「삼춘」이라는 말에서 짐작할 수 있는 마을의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"피를 나누지 않은 이웃 어른도 가족처럼 여긴다","correct":true},{"t":"삼촌만 마을에 산다","mis":"K5-2-u3-X17"},{"t":"어른과 아이가 서로 말을 하지 않는다","mis":"K5-2-u3-X17"},{"t":"어른을 이름으로만 부른다","mis":"K5-2-u3-X17"}],"explanation":["이웃 어른을 불러요.","가깝게 지내요.","가족처럼 불러요."],"asset":{"type":"passage","lines":["우리 모둠은 체험 학습으로 제주 지역의 돌담 마을에 다녀왔다.","집과 집 사이 좁은 돌담길을 마을 사람들은 「올레」라고 불렀다.","집 앞에는 대문 대신 긴 나무 막대 「정낭」이 걸려 있었는데,","걸린 막대 수로 주인이 집에 있는지 알 수 있다고 했다.","안내해 주신 어른을 마을 아이들은 「삼춘」이라고 불렀다.","피를 나누지 않아도 가족처럼 부르는 말이라고 한다.","박물관에서는 물을 길어 나르던 동이 「물허벅」을 보았다.","방언 하나하나에 이 마을의 자연과 생활이 담겨 있다는 것을 알게 되었다."],"title":"돌담 마을 체험 학습 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#6','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C18',2,'match','auto','방언과 그 말에 담긴 지역의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-2-u3-C18","difficulty":2,"kind":"match","stem":"방언과 그 말에 담긴 지역의 모습을 알맞게 이으세요.","pairs":[{"l":"감재옹심이","r":"산이 많아 감자 농사가 활발한 강원 지역"},{"l":"뻘","r":"갯벌이 넓은 전라 지역"},{"l":"돔배기","r":"상어를 소금에 절여 먹는 경상 지역"}],"mis":"K5-2-u3-X18","explanation":["감자 음식이에요.","갯벌이에요.","절인 상어고기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#7','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C19',2,'mc','auto','방언의 가치로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u3-X19','K5-2-u3-X20']::text[],false,'{"seq":7,"concept":"K5-2-u3-C19","difficulty":2,"kind":"mc","stem":"방언의 가치로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"다른 지역 사람과 말이 통하지 않게 막아 준다","correct":true},{"t":"지역의 자연환경과 생활 모습을 담고 있다","mis":"K5-2-u3-X19"},{"t":"우리말의 옛 모습을 간직하고 있다","mis":"K5-2-u3-X20"},{"t":"그 지역 사람들의 정서를 보여 준다","mis":"K5-2-u3-X19"}],"explanation":["방언의 가치예요.","방언의 가치예요.","막으려고 생긴 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#8','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C17',2,'error','auto','보고서를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X17','K5-2-u3-X19','K5-2-u3-X18']::text[],false,'{"seq":8,"concept":"K5-2-u3-C17","difficulty":2,"kind":"error","stem":"보고서를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「정낭은 그냥 막대 이름이라 마을 생활과는 관계없어.」","correct":true,"mis_target":"K5-2-u3-X17"},{"t":"「정낭에는 이웃을 믿고 살던 생활이 담겨 있어.」","mis":"K5-2-u3-X19"},{"t":"「물허벅으로 섬에서 물을 길어 나르던 모습을 알 수 있어.」","mis":"K5-2-u3-X18"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","막대 하나에도 생활이 담겨요."],"asset":{"type":"passage","lines":["우리 모둠은 체험 학습으로 제주 지역의 돌담 마을에 다녀왔다.","집과 집 사이 좁은 돌담길을 마을 사람들은 「올레」라고 불렀다.","집 앞에는 대문 대신 긴 나무 막대 「정낭」이 걸려 있었는데,","걸린 막대 수로 주인이 집에 있는지 알 수 있다고 했다.","안내해 주신 어른을 마을 아이들은 「삼춘」이라고 불렀다.","피를 나누지 않아도 가족처럼 부르는 말이라고 한다.","박물관에서는 물을 길어 나르던 동이 「물허벅」을 보았다.","방언 하나하나에 이 마을의 자연과 생활이 담겨 있다는 것을 알게 되었다."],"title":"돌담 마을 체험 학습 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#9','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C20',2,'mc','auto','몇몇 지역에서 어르신들의 말을 녹음해 방언 사전을 만드는 까닭은 무엇인가요?',ARRAY['K5-2-u3-X14','K5-2-u3-X08','K5-2-u3-X29']::text[],false,'{"seq":9,"concept":"K5-2-u3-C20","difficulty":2,"kind":"mc","stem":"몇몇 지역에서 어르신들의 말을 녹음해 방언 사전을 만드는 까닭은 무엇인가요?","options":[{"t":"쓰는 사람이 줄어드는 말을 기록해 다음 세대에 물려주려고","correct":true},{"t":"방언을 쓰지 못하게 하려고","mis":"K5-2-u3-X14"},{"t":"표준어를 모두 바꾸려고","mis":"K5-2-u3-X08"},{"t":"방언을 흉내 내는 놀이를 하려고","mis":"K5-2-u3-X29"}],"explanation":["지키려는 일이에요.","표준어를 바꾸려는 게 아니에요.","기록해 물려줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#10','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C18',3,'mc','auto','「감재옹심이」라는 강원 지역 음식 이름에서 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X18','K5-2-u3-X17']::text[],false,'{"seq":10,"concept":"K5-2-u3-C18","difficulty":3,"kind":"mc","stem":"「감재옹심이」라는 강원 지역 음식 이름에서 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"산이 많은 강원 지역에서 감자를 즐겨 길러 먹었다","correct":true},{"t":"강원 지역에서는 감자가 나지 않았다","mis":"K5-2-u3-X18"},{"t":"바다에서 잡은 물고기로 만든 음식이다","mis":"K5-2-u3-X18"},{"t":"음식 이름과 생활은 아무 관계가 없다","mis":"K5-2-u3-X17"}],"explanation":["감재는 감자예요.","감자로 만들어요.","자연과 먹을거리가 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#1','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C20',2,'ox','auto','방언이 사라져도 표준어가 있으니 잃는 것은 하나도 없어요.',ARRAY['K5-2-u3-X20']::text[],false,'{"seq":1,"concept":"K5-2-u3-C20","difficulty":2,"kind":"ox","stem":"방언이 사라져도 표준어가 있으니 잃는 것은 하나도 없어요.","answer":"X","reason_options":[{"t":"방언에 담긴 생활과 이야기도 함께 잊힐 수 있기 때문에","correct":true},{"t":"표준어만으로 모든 것을 똑같이 나타낼 수 있기 때문에","mis":"K5-2-u3-X20"}],"mis":"K5-2-u3-X20","explanation":["함께 잊히는 것이 있어요.","표준어로 다 담기 어려워요.","방언은 지켜야 할 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#2','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C17',2,'mc','auto','보고서 마지막 줄에서 글쓴이가 새롭게 알게 된 점은 무엇인가요?',ARRAY['K5-2-u3-X21','K5-2-u3-X19']::text[],false,'{"seq":2,"concept":"K5-2-u3-C17","difficulty":2,"kind":"mc","stem":"보고서 마지막 줄에서 글쓴이가 새롭게 알게 된 점은 무엇인가요?","options":[{"t":"방언 하나하나에 마을의 자연과 생활이 담겨 있다는 것","correct":true},{"t":"돌담 마을에는 길이 없다는 것","mis":"K5-2-u3-X21"},{"t":"방언은 외우기 어렵다는 것","mis":"K5-2-u3-X19"},{"t":"박물관이 아주 크다는 것","mis":"K5-2-u3-X21"}],"explanation":["올레라는 길이 있어요.","글에 없어요.","마지막 줄을 봐요."],"asset":{"type":"passage","lines":["우리 모둠은 체험 학습으로 제주 지역의 돌담 마을에 다녀왔다.","집과 집 사이 좁은 돌담길을 마을 사람들은 「올레」라고 불렀다.","집 앞에는 대문 대신 긴 나무 막대 「정낭」이 걸려 있었는데,","걸린 막대 수로 주인이 집에 있는지 알 수 있다고 했다.","안내해 주신 어른을 마을 아이들은 「삼춘」이라고 불렀다.","피를 나누지 않아도 가족처럼 부르는 말이라고 한다.","박물관에서는 물을 길어 나르던 동이 「물허벅」을 보았다.","방언 하나하나에 이 마을의 자연과 생활이 담겨 있다는 것을 알게 되었다."],"title":"돌담 마을 체험 학습 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#3','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C19',3,'mc','auto','「물허벅은 물동이니까 그냥 물동이라고 하면 되지 않아?」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X17','K5-2-u3-X15','K5-2-u3-X03']::text[],false,'{"seq":3,"concept":"K5-2-u3-C19","difficulty":3,"kind":"mc","stem":"「물허벅은 물동이니까 그냥 물동이라고 하면 되지 않아?」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「물허벅에는 섬에서 물을 길어 나르던 생활과 그 모양이 함께 담겨 있어.」","correct":true},{"t":"「맞아, 같은 뜻이니 아무거나 써도 돼.」","mis":"K5-2-u3-X17"},{"t":"「물허벅은 틀린 말이니 물동이로 고쳐야 해.」","mis":"K5-2-u3-X15"},{"t":"「물동이는 방언이고 물허벅이 표준어야.」","mis":"K5-2-u3-X03"}],"explanation":["담긴 생활이 달라요.","고칠 말이 아니에요.","바꾸면 느낌이 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#4','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C18',3,'mc','auto','「돔배기」라는 방언으로 경상 지역에 대해 짐작한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X18','K5-2-u3-X10','K5-2-u3-X17']::text[],false,'{"seq":4,"concept":"K5-2-u3-C18","difficulty":3,"kind":"mc","stem":"「돔배기」라는 방언으로 경상 지역에 대해 짐작한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바다에서 잡은 상어를 소금에 절여 먹는 문화가 있었다","correct":true},{"t":"바다와 멀어 물고기를 먹지 않았다","mis":"K5-2-u3-X18"},{"t":"돔배기는 산에서 캐는 나물이다","mis":"K5-2-u3-X10"},{"t":"돔배기와 지역 생활은 관계없다","mis":"K5-2-u3-X17"}],"explanation":["동해와 가까워요.","상어고기예요.","먹을거리 문화가 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#5','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C20',3,'mc','auto','「정낭」이라는 말을 쓰지 않고 그 막대와 쓰임을 설명해 보면 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X20','K5-2-u3-X19','K5-2-u3-X30']::text[],false,'{"seq":5,"concept":"K5-2-u3-C20","difficulty":3,"kind":"mc","stem":"「정낭」이라는 말을 쓰지 않고 그 막대와 쓰임을 설명해 보면 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"방언 하나에 많은 생활 모습이 담겨 있어 설명이 길어진다","correct":true},{"t":"방언이 없어도 짧게 설명할 수 있다","mis":"K5-2-u3-X20"},{"t":"정낭은 쓸모없는 옛말이다","mis":"K5-2-u3-X19"},{"t":"표준어가 언제나 더 짧고 좋은 말이다","mis":"K5-2-u3-X30"}],"explanation":["설명이 길어져요.","쓸모없지 않아요.","말 하나에 많은 것이 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#6','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C19',3,'error','auto','방언의 가치를 말한 친구들이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X19','K5-2-u3-X17','K5-2-u3-X20']::text[],false,'{"seq":6,"concept":"K5-2-u3-C19","difficulty":3,"kind":"error","stem":"방언의 가치를 말한 친구들이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「방언은 옛날 말이라 지금 생활과는 아무 관계가 없어.」","correct":true,"mis_target":"K5-2-u3-X19"},{"t":"「방언에는 이웃을 가족처럼 여기는 정이 담겨 있어.」","mis":"K5-2-u3-X17"},{"t":"「방언은 우리말의 옛 모습을 간직하고 있어.」","mis":"K5-2-u3-X20"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","지금도 쓰이며 문화를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#7','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C29',3,'mc','auto','방언 속 지역 이야기 카드를 만들 때 지켜야 할 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X01','K5-2-u3-X28']::text[],false,'{"seq":7,"concept":"K5-2-u3-C29","difficulty":3,"kind":"mc","stem":"방언 속 지역 이야기 카드를 만들 때 지켜야 할 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지역의 말을 낮추어 보지 않고 생활을 존중하며 소개한다","correct":true},{"t":"재미있게 하려고 방언을 과장해 흉내 낸다","mis":"K5-2-u3-X29"},{"t":"낯선 방언은 이상한 말이라고 쓴다","mis":"K5-2-u3-X01"},{"t":"방언 뜻만 빠르게 많이 적는다","mis":"K5-2-u3-X28"}],"explanation":["흉내는 예의가 아니에요.","이상한 말이 아니에요.","생활을 함께 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#8','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C18',4,'essay','teacher','「뻘」에 전라 지역의 어떤 자연환경이 담겨 있는지 쓰고, 우리 지역의 자연이나 생활이 담겼을 것 같은 말을 하나 떠올려 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C18","difficulty":4,"kind":"essay","stem":"「뻘」에 전라 지역의 어떤 자연환경이 담겨 있는지 쓰고, 우리 지역의 자연이나 생활이 담겼을 것 같은 말을 하나 떠올려 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「뻘」에는 서해안에 갯벌이 넓게 펼쳐진 전라 지역의 자연환경이 담겨 있다. 우리 지역은 바다와 가까워 할아버지께서 쓰시는 고기잡이 도구 이름에 바닷가 생활이 담겨 있을 것 같다. 바다에서 일하는 모습이 말에 그대로 남았을 것이기 때문이다.","scoring_points":["뻘에 담긴 자연환경을 썼는가","우리 지역 말을 하나 떠올렸는가","자연이나 생활과 이은 까닭을 썼는가"]},"explanation":["갯벌이에요.","우리 지역 말을 떠올려요.","까닭을 써요. 표준어를 쓰는 지역이면 그 말도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#9','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C20',4,'essay','teacher','방언이 사라진다면 어떤 일이 생길지 상상해 쓰고, 방언이 소중한 까닭을 내 생각으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u3-C20","difficulty":4,"kind":"essay","stem":"방언이 사라진다면 어떤 일이 생길지 상상해 쓰고, 방언이 소중한 까닭을 내 생각으로 쓰세요.","answer_guide":{"answer":"예: 방언이 사라지면 할머니께서 쓰시던 말과 그 말에 담긴 옛 생활 이야기를 아무도 모르게 될 것이다. 방언은 지역의 자연과 생활, 사람들의 정을 담고 있어서 그 지역의 문화를 지키는 말이기 때문에 소중하다.","scoring_points":["사라질 때 생길 일을 상상해 썼는가","방언이 소중한 까닭을 썼는가","까닭이 방언의 가치와 이어지는가"]},"explanation":["잊히는 것을 떠올려요.","까닭을 써요.","가치와 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#10','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C17',4,'essay','teacher','「올레」, 「정낭」, 「삼춘」, 「물허벅」 가운데 하나를 골라 그 말에 담긴 마을의 생활 모습을 설명하는 카드 글을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u3-C17","difficulty":4,"kind":"essay","stem":"「올레」, 「정낭」, 「삼춘」, 「물허벅」 가운데 하나를 골라 그 말에 담긴 마을의 생활 모습을 설명하는 카드 글을 쓰세요.","answer_guide":{"answer":"예: 정낭 — 제주 지역 집 앞에 대문 대신 가로로 걸어 둔 긴 나무 막대이다. 걸어 둔 막대 수로 집주인이 집에 있는지 알렸다. 대문을 잠그지 않고 이웃을 믿으며 살던 열린 생활이 담겨 있다.","scoring_points":["방언 하나를 골라 뜻을 썼는가","쓰임을 설명했는가","담긴 생활 모습을 썼는가"]},"explanation":["뜻을 써요.","쓰임을 써요.","생활 모습을 써요."],"asset":{"type":"passage","lines":["우리 모둠은 체험 학습으로 제주 지역의 돌담 마을에 다녀왔다.","집과 집 사이 좁은 돌담길을 마을 사람들은 「올레」라고 불렀다.","집 앞에는 대문 대신 긴 나무 막대 「정낭」이 걸려 있었는데,","걸린 막대 수로 주인이 집에 있는지 알 수 있다고 했다.","안내해 주신 어른을 마을 아이들은 「삼춘」이라고 불렀다.","피를 나누지 않아도 가족처럼 부르는 말이라고 한다.","박물관에서는 물을 길어 나르던 동이 「물허벅」을 보았다.","방언 하나하나에 이 마을의 자연과 생활이 담겨 있다는 것을 알게 되었다."],"title":"돌담 마을 체험 학습 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#1','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C21',1,'mc','auto','「감 따는 날」에서 하준이가 가을 방학에 간 곳은 어디인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":1,"concept":"K5-2-u3-C21","difficulty":1,"kind":"mc","stem":"「감 따는 날」에서 하준이가 가을 방학에 간 곳은 어디인가요?","options":[{"t":"외할머니가 사시는 남쪽 바닷가 마을","correct":true},{"t":"큰 도시의 시장","mis":"K5-2-u3-X21"},{"t":"산속 마을의 절","mis":"K5-2-u3-X21"},{"t":"친구네 아파트","mis":"K5-2-u3-X21"}],"explanation":["글에 없어요.","글에 없어요.","첫 줄에 나와요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#2','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C22',1,'mc','auto','외할머니가 부른 「아야」를 표준어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u3-X22']::text[],false,'{"seq":2,"concept":"K5-2-u3-C22","difficulty":1,"kind":"mc","stem":"외할머니가 부른 「아야」를 표준어로 바꾸면 어느 것인가요?","options":[{"t":"얘야","correct":true},{"t":"아파","mis":"K5-2-u3-X22"},{"t":"어머나","mis":"K5-2-u3-X22"},{"t":"잘 가","mis":"K5-2-u3-X22"}],"explanation":["아픈 소리가 아니에요.","놀란 소리가 아니에요.","하준이를 부르는 말이에요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#3','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C22',1,'blank','auto','「못 보던 얼굴인디, 누구 손주여?」를 표준어로 바꾸면 「못 보던 ( ? ), 누구 손주니?」예요. 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u3-X22']::text[],false,'{"seq":3,"concept":"K5-2-u3-C22","difficulty":1,"kind":"blank","stem":"「못 보던 얼굴인디, 누구 손주여?」를 표준어로 바꾸면 「못 보던 ( ? ), 누구 손주니?」예요. 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"얼굴인데","correct":true},{"t":"얼굴이여","mis":"K5-2-u3-X22"},{"t":"얼굴이니까","mis":"K5-2-u3-X22"},{"t":"얼굴이겠지","mis":"K5-2-u3-X22"}],"explanation":["끝말이 그대로예요.","뜻이 달라요.","「~인디」는 「~인데」예요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#4','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C24',1,'ox','auto','이야기에 방언을 쓰면 인물이 어디에 사는 누구인지 더 생생하게 느껴져요.',ARRAY['K5-2-u3-X24']::text[],false,'{"seq":4,"concept":"K5-2-u3-C24","difficulty":1,"kind":"ox","stem":"이야기에 방언을 쓰면 인물이 어디에 사는 누구인지 더 생생하게 느껴져요.","answer":"O","reason_options":[{"t":"방언이 인물의 목소리와 지역의 분위기를 살려 주기 때문에","correct":true},{"t":"방언은 읽기 어려워 인물을 알 수 없게 하기 때문에","mis":"K5-2-u3-X24"}],"mis":"K5-2-u3-X24","explanation":["생동감이 생겨요.","분위기가 살아나요.","인물이 생생해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#5','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C21',2,'mc','auto','할머니들이 「그러니께 얼굴이 하얗겄제.」라고 말한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":5,"concept":"K5-2-u3-C21","difficulty":2,"kind":"mc","stem":"할머니들이 「그러니께 얼굴이 하얗겄제.」라고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"하준이가 서울에서 왔다는 말을 들어서","correct":true},{"t":"하준이가 아파 보여서","mis":"K5-2-u3-X21"},{"t":"감이 하얘서","mis":"K5-2-u3-X21"},{"t":"날이 추워서","mis":"K5-2-u3-X21"}],"explanation":["글에 없어요.","감 이야기가 아니에요.","셋째 줄 바로 뒤예요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#6','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C22',2,'mc','auto','감나무 아래에서 「싸게싸게 와서」라고 부른 말의 뜻을 앞뒤 장면으로 짐작하면 어느 것인가요?',ARRAY['K5-2-u3-X22']::text[],false,'{"seq":6,"concept":"K5-2-u3-C22","difficulty":2,"kind":"mc","stem":"감나무 아래에서 「싸게싸게 와서」라고 부른 말의 뜻을 앞뒤 장면으로 짐작하면 어느 것인가요?","options":[{"t":"빨리빨리 와서","correct":true},{"t":"천천히 와서","mis":"K5-2-u3-X22"},{"t":"조심조심 와서","mis":"K5-2-u3-X22"},{"t":"살금살금 와서","mis":"K5-2-u3-X22"}],"explanation":["서두르라는 장면이에요.","바구니를 잡으라고 불러요.","「싸게싸게」는 빨리빨리예요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#7','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C21',2,'mc','auto','하준이의 마음은 이야기 처음과 끝에서 어떻게 달라졌나요?',ARRAY['K5-2-u3-X21','K5-2-u3-X22']::text[],false,'{"seq":7,"concept":"K5-2-u3-C21","difficulty":2,"kind":"mc","stem":"하준이의 마음은 이야기 처음과 끝에서 어떻게 달라졌나요?","options":[{"t":"낯설던 말이 따뜻하게 들리게 되었다","correct":true},{"t":"따뜻하던 말이 무섭게 들리게 되었다","mis":"K5-2-u3-X21"},{"t":"처음부터 끝까지 지루했다","mis":"K5-2-u3-X21"},{"t":"할머니들 말을 끝까지 못 알아들어 속상했다","mis":"K5-2-u3-X22"}],"explanation":["거꾸로예요.","글에 없어요.","마지막 줄을 봐요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#8','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C22',2,'match','auto','이야기 속 방언 끝말과 뜻이 같은 표준어 끝말을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C22","difficulty":2,"kind":"match","stem":"이야기 속 방언 끝말과 뜻이 같은 표준어 끝말을 알맞게 이으세요.","pairs":[{"l":"~인디","r":"~인데"},{"l":"~당께","r":"~다니까"},{"l":"~겄제","r":"~겠지"}],"mis":"K5-2-u3-X22","explanation":["얼굴인디 → 얼굴인데예요.","왔당께 → 왔다니까예요.","하얗겄제 → 하얗겠지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#9','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C23',2,'error','auto','방언 문장과 표준어 문장을 읽어 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X23','K5-2-u3-X24','K5-2-u3-X15']::text[],false,'{"seq":9,"concept":"K5-2-u3-C23","difficulty":2,"kind":"error","stem":"방언 문장과 표준어 문장을 읽어 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「표준어로 바꾸면 뜻이 같으니 느낌도 똑같아.」","correct":true,"mis_target":"K5-2-u3-X23"},{"t":"「방언으로 읽으니 손주를 자랑하는 할머니 목소리가 들리는 것 같아.」","mis":"K5-2-u3-X24"},{"t":"「바꾸어 읽은 건 방언을 고치려는 게 아니라 느낌을 견주려는 거야.」","mis":"K5-2-u3-X15"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","뜻은 같아도 느낌은 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#10','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C24',3,'mc','auto','「감 따는 날」에서 방언이 한 역할로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X24','K5-2-u3-X21']::text[],false,'{"seq":10,"concept":"K5-2-u3-C24","difficulty":3,"kind":"mc","stem":"「감 따는 날」에서 방언이 한 역할로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마을 사람들이 하준이를 반갑게 맞는 정다운 분위기를 살렸다","correct":true},{"t":"이야기를 읽기 어렵게만 만들었다","mis":"K5-2-u3-X24"},{"t":"줄거리를 바꾸어 놓았다","mis":"K5-2-u3-X21"},{"t":"하준이가 서울에서 왔다는 것을 숨겼다","mis":"K5-2-u3-X21"}],"explanation":["생동감을 주었어요.","줄거리는 그대로예요.","정다운 분위기가 살아나요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#1','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C23',2,'ox','auto','이야기 속 방언을 표준어로 바꾸어 읽어 보는 것은 방언을 고쳐 쓰려는 것이에요.',ARRAY['K5-2-u3-X15']::text[],false,'{"seq":1,"concept":"K5-2-u3-C23","difficulty":2,"kind":"ox","stem":"이야기 속 방언을 표준어로 바꾸어 읽어 보는 것은 방언을 고쳐 쓰려는 것이에요.","answer":"X","reason_options":[{"t":"두 문장의 느낌을 견주어 방언이 하는 일을 알기 위한 것이기 때문에","correct":true},{"t":"방언은 이야기에 쓰면 안 되는 말이기 때문에","mis":"K5-2-u3-X15"}],"mis":"K5-2-u3-X15","explanation":["고치기가 아니에요.","느낌을 견주어요.","방언이 하는 일을 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#2','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C25',2,'mc','auto','작품을 내 삶과 이어 감상한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X25','K5-2-u3-X24']::text[],false,'{"seq":2,"concept":"K5-2-u3-C25","difficulty":2,"kind":"mc","stem":"작품을 내 삶과 이어 감상한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「나도 할머니 댁에서 정다운 고향 말을 들으면 반가웠는데, 하준이 마음을 알 것 같아.」","correct":true},{"t":"「감나무 잎은 초록색이야.」","mis":"K5-2-u3-X25"},{"t":"「이 이야기는 아주 짧아.」","mis":"K5-2-u3-X25"},{"t":"「방언은 어려우니 읽지 않을래.」","mis":"K5-2-u3-X24"}],"explanation":["작품과 내 삶이 이어지지 않아요.","감상이 아니에요.","내 경험과 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#3','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C23',3,'mc','auto','「우리 딸네 아들이여. 서울서 왔당께.」를 표준어로 바꾸면 줄어드는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X23','K5-2-u3-X21']::text[],false,'{"seq":3,"concept":"K5-2-u3-C23","difficulty":3,"kind":"mc","stem":"「우리 딸네 아들이여. 서울서 왔당께.」를 표준어로 바꾸면 줄어드는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"손주를 자랑하는 외할머니의 정다운 목소리","correct":true},{"t":"외할머니가 한 말의 뜻","mis":"K5-2-u3-X23"},{"t":"하준이가 어디서 왔는지에 대한 정보","mis":"K5-2-u3-X23"},{"t":"이야기의 줄거리","mis":"K5-2-u3-X21"}],"explanation":["뜻은 같아요.","정보는 그대로예요.","목소리와 정이 줄어요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#4','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C24',3,'mc','auto','이야기의 대사를 모두 표준어로 바꾸었더니 친구들이 「뭔가 허전하다.」라고 했어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X23','K5-2-u3-X13','K5-2-u3-X24']::text[],false,'{"seq":4,"concept":"K5-2-u3-C24","difficulty":3,"kind":"mc","stem":"이야기의 대사를 모두 표준어로 바꾸었더니 친구들이 「뭔가 허전하다.」라고 했어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"할머니들의 목소리와 마을 분위기, 정다운 마음이 줄어들어서","correct":true},{"t":"줄거리가 완전히 바뀌어서","mis":"K5-2-u3-X23"},{"t":"뜻을 알아들을 수 없게 되어서","mis":"K5-2-u3-X13"},{"t":"글자 수가 늘어나서","mis":"K5-2-u3-X24"}],"explanation":["줄거리는 같아요.","오히려 뜻은 잘 알아요.","분위기와 정이 줄었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#5','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C22',3,'mc','auto','작품을 읽다가 뜻을 모르는 방언을 만났을 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K5-2-u3-X22','K5-2-u3-X10','K5-2-u3-X24']::text[],false,'{"seq":5,"concept":"K5-2-u3-C22","difficulty":3,"kind":"mc","stem":"작품을 읽다가 뜻을 모르는 방언을 만났을 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"앞뒤 장면으로 짐작하고 지역어 누리집이나 사전에서 확인한다","correct":true},{"t":"모르는 말은 건너뛰고 읽는다","mis":"K5-2-u3-X22"},{"t":"아무 뜻이나 넣어 읽는다","mis":"K5-2-u3-X10"},{"t":"방언이 나오는 책은 읽지 않는다","mis":"K5-2-u3-X24"}],"explanation":["놓치는 것이 생겨요.","근거가 없어요.","짐작하고 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#6','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C21',3,'error','auto','「감 따는 날」을 읽고 감상을 나눈 친구들이에요. 감상의 초점이 가장 어긋난 것은 어느 것인가요?',ARRAY['K5-2-u3-X21','K5-2-u3-X25','K5-2-u3-X24']::text[],false,'{"seq":6,"concept":"K5-2-u3-C21","difficulty":3,"kind":"error","stem":"「감 따는 날」을 읽고 감상을 나눈 친구들이에요. 감상의 초점이 가장 어긋난 것은 어느 것인가요?","options":[{"t":"「방언 뜻 맞히기만 하면 이 이야기는 다 읽은 거야.」","correct":true,"mis_target":"K5-2-u3-X21"},{"t":"「낯설던 말이 따뜻하게 들린 하준이 마음이 좋았어.」","mis":"K5-2-u3-X25"},{"t":"「정자 장면에서 마을 사람들이 반기는 분위기가 느껴졌어.」","mis":"K5-2-u3-X24"}],"explanation":["마음을 읽었어요.","분위기를 느꼈어요.","줄거리와 마음도 읽어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#7','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C29',3,'mc','auto','방언 살려 낭독하기를 할 때 지켜야 할 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X24','K5-2-u3-X22']::text[],false,'{"seq":7,"concept":"K5-2-u3-C29","difficulty":3,"kind":"mc","stem":"방언 살려 낭독하기를 할 때 지켜야 할 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"과장해 흉내 내지 않고 인물의 마음을 살려 읽는다","correct":true},{"t":"웃음을 끌려고 말투를 크게 부풀린다","mis":"K5-2-u3-X29"},{"t":"방언은 빼고 표준어로만 읽는다","mis":"K5-2-u3-X24"},{"t":"뜻을 몰라도 빨리 읽고 끝낸다","mis":"K5-2-u3-X22"}],"explanation":["웃음거리가 돼요.","방언 낭독이 아니에요.","마음을 살려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#8','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C23',4,'essay','teacher','「서울서 왔당께.」를 표준어로 바꾸어 쓰고, 두 문장을 읽었을 때 느낌이 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C23","difficulty":4,"kind":"essay","stem":"「서울서 왔당께.」를 표준어로 바꾸어 쓰고, 두 문장을 읽었을 때 느낌이 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 표준어로 바꾸면 「서울에서 왔다니까.」이다. 뜻은 같지만 방언으로 읽으면 손주를 자랑하고 싶은 외할머니의 정다운 목소리가 들리는 것 같고, 표준어로 읽으면 그 느낌이 조금 줄어든다.","scoring_points":["표준어로 바르게 바꾸었는가","뜻은 같다는 것을 알았는가","느낌의 차이를 썼는가"]},"explanation":["「~당께」는 「~다니까」예요.","뜻은 같아요.","느낌이 달라요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#9','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C25',4,'essay','teacher','「감 따는 날」에서 가장 인상 깊은 장면을 고르고, 그 장면에서 방언이 한 역할을 내 경험과 이어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u3-C25","difficulty":4,"kind":"essay","stem":"「감 따는 날」에서 가장 인상 깊은 장면을 고르고, 그 장면에서 방언이 한 역할을 내 경험과 이어 쓰세요.","answer_guide":{"answer":"예: 정자에서 할머니들이 하준이에게 누구 손주냐고 묻는 장면이 인상 깊다. 할머니들의 방언 덕분에 마을 사람들이 처음 온 아이를 반갑게 맞아 주는 분위기가 살아났다. 나도 시골 할머니 댁에 갔을 때 이웃 어르신들이 고향 말로 반겨 주셔서 마음이 따뜻했던 기억이 난다.","scoring_points":["장면을 하나 골랐는가","그 장면에서 방언의 역할을 썼는가","내 경험과 이었는가"]},"explanation":["장면을 골라요.","역할을 써요.","내 경험과 이어요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#10','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C24',4,'essay','teacher','이야기에 방언을 쓰면 좋은 점을 두 가지 쓰고, 「감 따는 날」에서 근거가 되는 장면을 하나씩 드세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u3-C24","difficulty":4,"kind":"essay","stem":"이야기에 방언을 쓰면 좋은 점을 두 가지 쓰고, 「감 따는 날」에서 근거가 되는 장면을 하나씩 드세요.","answer_guide":{"answer":"예: 첫째, 인물이 어디에 사는 누구인지 생생하게 느껴진다. 할머니들의 「~인디, ~여」 하는 말에서 남쪽 바닷가 마을 할머니들이 떠오른다. 둘째, 인물 사이의 정이 살아난다. 외할머니가 「아야, 싸게싸게 와서」라고 부르는 장면에서 손주를 아끼는 마음이 느껴진다.","scoring_points":["좋은 점 두 가지를 썼는가","각각 장면 근거를 들었는가","근거가 좋은 점과 맞는가"]},"explanation":["좋은 점을 써요.","장면을 들어요.","근거를 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#1','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C27',1,'mc','auto','우리 반 방언 지도를 만드는 첫 단계로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X27']::text[],false,'{"seq":1,"concept":"K5-2-u3-C27","difficulty":1,"kind":"mc","stem":"우리 반 방언 지도를 만드는 첫 단계로 알맞은 것은 어느 것인가요?","options":[{"t":"조사할 방언 주제 정하기","correct":true},{"t":"지도에 색칠하기","mis":"K5-2-u3-X27"},{"t":"다른 반 지도 베끼기","mis":"K5-2-u3-X27"},{"t":"잘한 모둠에게 줄 상장 만들기","mis":"K5-2-u3-X27"}],"explanation":["주제가 먼저예요.","우리 반이 조사해요.","주제부터 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#2','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C26',1,'mc','auto','방언을 활용해 만들 수 있는 작품이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u3-X26']::text[],false,'{"seq":2,"concept":"K5-2-u3-C26","difficulty":1,"kind":"mc","stem":"방언을 활용해 만들 수 있는 작품이 아닌 것은 어느 것인가요?","options":[{"t":"곱셈 구구표","correct":true},{"t":"우리 반 방언 지도","mis":"K5-2-u3-X26"},{"t":"방언 노랫말","mis":"K5-2-u3-X26"},{"t":"방언 상황극","mis":"K5-2-u3-X26"}],"explanation":["방언 작품이에요.","방언 작품이에요.","방언과 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#3','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C9',1,'mc','auto','조사표에서 명절이나 비 오는 날 즐겨 부쳐 먹는 음식으로 소개한 「찌짐」을 표준어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":3,"concept":"K5-2-u3-C9","difficulty":1,"kind":"mc","stem":"조사표에서 명절이나 비 오는 날 즐겨 부쳐 먹는 음식으로 소개한 「찌짐」을 표준어로 바꾸면 어느 것인가요?","options":[{"t":"부침개","correct":true},{"t":"떡국","mis":"K5-2-u3-X10"},{"t":"비빔밥","mis":"K5-2-u3-X10"},{"t":"김밥","mis":"K5-2-u3-X10"}],"explanation":["부쳐 먹는 음식이 아니에요.","부쳐 먹는 음식이 아니에요.","찌짐은 부침개예요."],"asset":{"type":"passage","lines":["찌짐 — 명절이나 비 오는 날 즐겨 부쳐 먹는 음식","무시 — 깍두기를 담그거나 국에 넣는 흰 뿌리채소","짐치 — 밥상에 빠지지 않는 매운 반찬","돔배기 — 소금에 절여 토막 낸 상어고기"],"title":"우리 반 방언 조사표 — 음식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#4','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C28',1,'ox','auto','방언 지도는 방언을 많이 모을수록 잘 만든 것이에요.',ARRAY['K5-2-u3-X28']::text[],false,'{"seq":4,"concept":"K5-2-u3-C28","difficulty":1,"kind":"ox","stem":"방언 지도는 방언을 많이 모을수록 잘 만든 것이에요.","answer":"X","reason_options":[{"t":"방언이 어떤 지역의 어떤 생활을 보여 주는지가 잘 드러나야 하기 때문에","correct":true},{"t":"개수가 많으면 저절로 지역이 잘 보이기 때문에","mis":"K5-2-u3-X28"}],"mis":"K5-2-u3-X28","explanation":["개수보다 내용이에요.","생활이 드러나야 해요.","뜻과 생활을 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#5','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C28',2,'mc','auto','방언 지도에 방언과 함께 적으면 좋은 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u3-X28','K5-2-u3-X18']::text[],false,'{"seq":5,"concept":"K5-2-u3-C28","difficulty":2,"kind":"mc","stem":"방언 지도에 방언과 함께 적으면 좋은 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"방언을 흉내 낸 우스운 그림","correct":true},{"t":"방언을 쓰는 지역 이름","mis":"K5-2-u3-X28"},{"t":"방언의 뜻","mis":"K5-2-u3-X28"},{"t":"방언과 이어지는 생활 모습","mis":"K5-2-u3-X18"}],"explanation":["함께 적어요.","함께 적어요.","웃음거리로 삼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#6','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C27',2,'mc','auto','방언 지도를 만드는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X27']::text[],false,'{"seq":6,"concept":"K5-2-u3-C27","difficulty":2,"kind":"mc","stem":"방언 지도를 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 정하기 → 지역 나누기 → 조사하기 → 지도에 붙이기","correct":true},{"t":"지도에 붙이기 → 조사하기 → 주제 정하기 → 지역 나누기","mis":"K5-2-u3-X27"},{"t":"조사하기 → 주제 정하기 → 지도에 붙이기 → 지역 나누기","mis":"K5-2-u3-X27"},{"t":"지역 나누기 → 지도에 붙이기 → 주제 정하기 → 조사하기","mis":"K5-2-u3-X27"}],"explanation":["붙이기는 맨 끝이에요.","주제가 먼저예요.","주제 → 지역 → 조사 → 붙이기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#7','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C29',2,'mc','auto','방언 상황극을 할 때 조심할 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X26']::text[],false,'{"seq":7,"concept":"K5-2-u3-C29","difficulty":2,"kind":"mc","stem":"방언 상황극을 할 때 조심할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"방언을 웃음거리로 흉내 내지 않고 그 지역 사람의 마음을 살린다","correct":true},{"t":"방언을 과장할수록 잘한 연기이다","mis":"K5-2-u3-X29"},{"t":"대사에 방언을 하나도 넣지 않는다","mis":"K5-2-u3-X26"},{"t":"관객이 웃도록 말투를 일부러 이상하게 한다","mis":"K5-2-u3-X29"}],"explanation":["과장은 흉내가 돼요.","방언이 들어가야 해요.","마음을 살려요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"여러분! 우리 강원 지역 감재 축제에 오신 걸 환영하드래요!"},{"who":"관객들","text":"반갑드래요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#8','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C28',2,'match','auto','조사표의 생활 설명을 보고 방언과 표준어를 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C28","difficulty":2,"kind":"match","stem":"조사표의 생활 설명을 보고 방언과 표준어를 알맞게 이으세요.","pairs":[{"l":"찌짐","r":"부침개"},{"l":"무시","r":"무"},{"l":"짐치","r":"김치"}],"mis":"K5-2-u3-X10","explanation":["부쳐 먹는 음식이에요.","흰 뿌리채소예요.","매운 반찬이에요."],"asset":{"type":"passage","lines":["찌짐 — 명절이나 비 오는 날 즐겨 부쳐 먹는 음식","무시 — 깍두기를 담그거나 국에 넣는 흰 뿌리채소","짐치 — 밥상에 빠지지 않는 매운 반찬","돔배기 — 소금에 절여 토막 낸 상어고기"],"title":"우리 반 방언 조사표 — 음식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#9','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C26',2,'error','auto','방언 활동을 고르는 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X26','K5-2-u3-X29','K5-2-u3-X27']::text[],false,'{"seq":9,"concept":"K5-2-u3-C26","difficulty":2,"kind":"error","stem":"방언 활동을 고르는 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「방언 활동은 지도 만들기 한 가지뿐이니 다른 건 생각하지 말자.」","correct":true,"mis_target":"K5-2-u3-X26"},{"t":"「아는 노래를 방언으로 바꾸어 부르는 것도 좋겠어.」","mis":"K5-2-u3-X29"},{"t":"「반 전체로 할지 모둠으로 할지도 함께 정하자.」","mis":"K5-2-u3-X27"}],"explanation":["좋은 생각이에요.","좋은 생각이에요.","노랫말 · 상황극도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#10','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C28',3,'mc','auto','방언 지도 가운데 지역을 가장 잘 알려 주는 지도는 어느 것인가요?',ARRAY['K5-2-u3-X28','K5-2-u3-X29']::text[],false,'{"seq":10,"concept":"K5-2-u3-C28","difficulty":3,"kind":"mc","stem":"방언 지도 가운데 지역을 가장 잘 알려 주는 지도는 어느 것인가요?","options":[{"t":"방언 셋에 뜻과 생활 이야기를 붙인 지도","correct":true},{"t":"방언만 아주 많이 붙인 지도","mis":"K5-2-u3-X28"},{"t":"지역 이름 없이 방언만 붙인 지도","mis":"K5-2-u3-X28"},{"t":"우스운 그림만 가득한 지도","mis":"K5-2-u3-X29"}],"explanation":["개수만 많아요.","어느 지역인지 몰라요.","뜻과 생활이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#1','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C11',2,'ox','auto','서로 다른 두 지역에 같은 방언 「짐치」가 붙었다면 한 모둠이 틀린 것이에요.',ARRAY['K5-2-u3-X11']::text[],false,'{"seq":1,"concept":"K5-2-u3-C11","difficulty":2,"kind":"ox","stem":"서로 다른 두 지역에 같은 방언 「짐치」가 붙었다면 한 모둠이 틀린 것이에요.","answer":"X","reason_options":[{"t":"「짐치」는 강원 · 경상 · 전라 등 여러 지역에서 쓰여 방언이 지역 경계와 똑같이 나뉘지 않기 때문에","correct":true},{"t":"한 방언은 꼭 한 지역에서만 쓰이기 때문에","mis":"K5-2-u3-X11"}],"mis":"K5-2-u3-X11","explanation":["여러 지역에서 써요.","둘 다 맞을 수 있어요.","근거로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#2','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C27',2,'mc','auto','모둠마다 조사할 지역을 정할 때 함께 말하면 좋은 것은 어느 것인가요?',ARRAY['K5-2-u3-X27','K5-2-u3-X28']::text[],false,'{"seq":2,"concept":"K5-2-u3-C27","difficulty":2,"kind":"mc","stem":"모둠마다 조사할 지역을 정할 때 함께 말하면 좋은 것은 어느 것인가요?","options":[{"t":"그 지역을 고른 까닭","correct":true},{"t":"그 지역에 가 본 횟수","mis":"K5-2-u3-X27"},{"t":"조사할 방언의 개수","mis":"K5-2-u3-X28"},{"t":"지도를 꾸밀 색깔","mis":"K5-2-u3-X27"}],"explanation":["관계가 적어요.","개수가 중요하지 않아요.","고른 까닭을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#3','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C28',3,'mc','auto','조사표의 「찌짐」 옆에 덧붙일 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X28','K5-2-u3-X01','K5-2-u3-X30']::text[],false,'{"seq":3,"concept":"K5-2-u3-C28","difficulty":3,"kind":"mc","stem":"조사표의 「찌짐」 옆에 덧붙일 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"명절이나 비 오는 날 즐겨 부쳐 먹는 음식","correct":true},{"t":"찌짐 찌짐 찌짐","mis":"K5-2-u3-X28"},{"t":"뜻을 모르는 이상한 말","mis":"K5-2-u3-X01"},{"t":"표준어보다 못한 말","mis":"K5-2-u3-X30"}],"explanation":["되풀이일 뿐이에요.","이상한 말이 아니에요.","생활 이야기를 덧붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#4','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C26',3,'mc','auto','상황극 대본에서 사회자의 방언 인사가 하는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X13','K5-2-u3-X01','K5-2-u3-X29']::text[],false,'{"seq":4,"concept":"K5-2-u3-C26","difficulty":3,"kind":"mc","stem":"상황극 대본에서 사회자의 방언 인사가 하는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지역 축제의 분위기를 실감 나고 친근하게 살린다","correct":true},{"t":"관객이 뜻을 전혀 모르게 만든다","mis":"K5-2-u3-X13"},{"t":"사회자가 표준어를 모른다는 것을 보여 준다","mis":"K5-2-u3-X01"},{"t":"웃음거리로 삼기 위해 넣은 말이다","mis":"K5-2-u3-X29"}],"explanation":["관객도 함께 대답해요.","표준어를 몰라서가 아니에요.","축제 분위기가 살아나요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"여러분! 우리 강원 지역 감재 축제에 오신 걸 환영하드래요!"},{"who":"관객들","text":"반갑드래요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#5','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C28',3,'error','auto','우리 반 방언 지도를 보고 나눈 말이에요. 지도를 만드는 목적에서 가장 벗어난 말은 어느 것인가요?',ARRAY['K5-2-u3-X28','K5-2-u3-X09','K5-2-u3-X18']::text[],false,'{"seq":5,"concept":"K5-2-u3-C28","difficulty":3,"kind":"error","stem":"우리 반 방언 지도를 보고 나눈 말이에요. 지도를 만드는 목적에서 가장 벗어난 말은 어느 것인가요?","options":[{"t":"「우리 모둠이 제일 많이 붙였으니 우리가 이긴 거야.」","correct":true,"mis_target":"K5-2-u3-X28"},{"t":"「같은 김치도 지역마다 이름이 여러 가지라 신기해.」","mis":"K5-2-u3-X09"},{"t":"「돔배기 카드를 보니 경상 지역 바다 생활이 보여.」","mis":"K5-2-u3-X18"}],"explanation":["새롭게 안 점이에요.","생활을 읽었어요.","개수 겨루기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#6','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C27',3,'mc','auto','조사한 방언을 지도에 붙이기 전에 확인할 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X10','K5-2-u3-X11','K5-2-u3-X28']::text[],false,'{"seq":6,"concept":"K5-2-u3-C27","difficulty":3,"kind":"mc","stem":"조사한 방언을 지도에 붙이기 전에 확인할 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지역어 누리집 같은 근거로 방언과 지역이 맞는지 확인한다","correct":true},{"t":"짐작한 대로 바로 붙인다","mis":"K5-2-u3-X10"},{"t":"친구가 붙인 것과 다르면 내 것을 뗀다","mis":"K5-2-u3-X11"},{"t":"방언 개수만 세어 본다","mis":"K5-2-u3-X28"}],"explanation":["근거가 없어요.","둘 다 맞을 수 있어요.","근거로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#7','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C26',3,'mc','auto','반 친구 한 명이 혼자서 방언 노랫말을 만들고 싶다고 해요. 가장 알맞은 생각은 어느 것인가요?',ARRAY['K5-2-u3-X26','K5-2-u3-X14']::text[],false,'{"seq":7,"concept":"K5-2-u3-C26","difficulty":3,"kind":"mc","stem":"반 친구 한 명이 혼자서 방언 노랫말을 만들고 싶다고 해요. 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"반 전체 · 모둠 · 짝 · 혼자 가운데 알맞은 방식을 함께 정할 수 있다","correct":true},{"t":"방언 활동은 반 전체로만 해야 한다","mis":"K5-2-u3-X26"},{"t":"혼자 하면 방언을 쓰면 안 된다","mis":"K5-2-u3-X14"},{"t":"노랫말은 방언 활동이 될 수 없다","mis":"K5-2-u3-X26"}],"explanation":["여러 방식이 있어요.","관계없어요.","노랫말도 방언 작품이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#8','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C27',4,'essay','teacher','우리 반 방언 지도를 만든다고 할 때 정할 주제와 조사할 지역, 그 지역을 고른 까닭을 쓰고, 지도에 붙일 카드 한 장의 내용을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C27","difficulty":4,"kind":"essay","stem":"우리 반 방언 지도를 만든다고 할 때 정할 주제와 조사할 지역, 그 지역을 고른 까닭을 쓰고, 지도에 붙일 카드 한 장의 내용을 쓰세요.","answer_guide":{"answer":"예: 주제는 음식, 조사할 지역은 경상 지역이다. 할머니 고향이라 궁금했기 때문이다. 카드 — 돔배기 · 경상 지역 · 소금에 절여 토막 낸 상어고기 · 동해에서 잡은 상어를 절여 두고 명절 상에 올리던 생활이 담겨 있다.","scoring_points":["주제와 지역을 정했는가","지역을 고른 까닭을 썼는가","카드에 방언 · 뜻 · 생활을 담았는가"]},"explanation":["주제와 지역이에요.","까닭을 써요.","카드에 생활까지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#9','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C29',4,'essay','teacher','방언이 실감 나는 상황극 장면을 하나 정하고 방언을 넣은 대사를 한 줄 쓴 뒤, 연기할 때 조심할 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u3-C29","difficulty":4,"kind":"essay","stem":"방언이 실감 나는 상황극 장면을 하나 정하고 방언을 넣은 대사를 한 줄 쓴 뒤, 연기할 때 조심할 점을 쓰세요.","answer_guide":{"answer":"예: 시골 할아버지와 통화하는 장면 — 「할아버지, 진지 잡수셨슈?」 연기할 때에는 말투를 과장해 웃음거리로 만들지 않고, 할아버지를 걱정하는 손주의 마음을 살려 정답게 말한다.","scoring_points":["장면을 정했는가","방언을 넣은 대사를 썼는가","흉내 내지 않는 태도를 썼는가"]},"explanation":["장면을 정해요.","대사를 써요.","마음을 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#10','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C9',4,'essay','teacher','방언 지도에서 같은 「짐치」가 여러 지역에 붙은 것을 보고 알 수 있는 점과, 지도를 만들며 새롭게 안 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u3-C9","difficulty":4,"kind":"essay","stem":"방언 지도에서 같은 「짐치」가 여러 지역에 붙은 것을 보고 알 수 있는 점과, 지도를 만들며 새롭게 안 점을 쓰세요.","answer_guide":{"answer":"예: 「짐치」가 강원 · 경상 · 전라 지역에 함께 붙은 것을 보니 방언이 지역 경계에 딱 맞추어 나뉘지 않고 여러 지역에 퍼져 쓰인다는 것을 알 수 있다. 지도를 만들며 같은 김치도 「짐끼」처럼 여러 이름이 있다는 것을 새롭게 알았다.","scoring_points":["여러 지역에 퍼져 쓰임을 썼는가","지도를 만들며 새롭게 안 점을 썼는가","근거가 지도에서 나왔는가"]},"explanation":["퍼져 쓰여요.","새롭게 안 점을 써요.","지도를 근거로 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#1','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C2',1,'mc','auto','어디서나 누구와도 뜻이 통하도록 우리나라 사람들이 공통으로 쓰기로 정한 말은 어느 것인가요?',ARRAY['K5-2-u3-X03','K5-2-u3-X29','K5-2-u3-X19']::text[],false,'{"seq":1,"concept":"K5-2-u3-C2","difficulty":1,"kind":"mc","stem":"어디서나 누구와도 뜻이 통하도록 우리나라 사람들이 공통으로 쓰기로 정한 말은 어느 것인가요?","options":[{"t":"표준어","correct":true},{"t":"방언","mis":"K5-2-u3-X03"},{"t":"흉내 말","mis":"K5-2-u3-X29"},{"t":"옛말","mis":"K5-2-u3-X19"}],"explanation":["지역의 말이에요.","흉내는 말이 아니에요.","함께 쓰도록 정한 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#2','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C32',1,'mc','auto','글자 모양은 같지만 뜻이 다른 말을 무엇이라고 하나요?',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":2,"concept":"K5-2-u3-C32","difficulty":1,"kind":"mc","stem":"글자 모양은 같지만 뜻이 다른 말을 무엇이라고 하나요?","options":[{"t":"동형어","correct":true},{"t":"방언","mis":"K5-2-u3-X32"},{"t":"표준어","mis":"K5-2-u3-X32"},{"t":"높임말","mis":"K5-2-u3-X32"}],"explanation":["지역의 말이에요.","함께 쓰도록 정한 말이에요.","모양이 같고 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#3','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C5',1,'mc','auto','옛날에 방언이 생긴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X05']::text[],false,'{"seq":3,"concept":"K5-2-u3-C5","difficulty":1,"kind":"mc","stem":"옛날에 방언이 생긴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"산과 강 때문에 지역 사이를 오가기 어려워서","correct":true},{"t":"사람들이 표준어를 싫어해서","mis":"K5-2-u3-X05"},{"t":"지역마다 글자가 달라서","mis":"K5-2-u3-X05"},{"t":"방송이 방언을 가르쳐서","mis":"K5-2-u3-X05"}],"explanation":["싫어해서가 아니에요.","글자는 같아요.","지리적 특성 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#4','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C31',1,'mc','auto','상황 카드 ㉯ 「여러 지역 소식을 전하는 뉴스」에 가장 어울리는 말은 어느 것인가요?',ARRAY['K5-2-u3-X13','K5-2-u3-X31']::text[],false,'{"seq":4,"concept":"K5-2-u3-C31","difficulty":1,"kind":"mc","stem":"상황 카드 ㉯ 「여러 지역 소식을 전하는 뉴스」에 가장 어울리는 말은 어느 것인가요?","options":[{"t":"표준어","correct":true},{"t":"방언","mis":"K5-2-u3-X13"},{"t":"줄임말","mis":"K5-2-u3-X31"},{"t":"외국어","mis":"K5-2-u3-X31"}],"explanation":["여러 지역 사람이 봐요.","알맞지 않아요.","모두가 알아듣는 말이에요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#5','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C9',1,'mc','auto','「고냉이」를 표준어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":5,"concept":"K5-2-u3-C9","difficulty":1,"kind":"mc","stem":"「고냉이」를 표준어로 바꾸면 어느 것인가요?","options":[{"t":"고양이","correct":true},{"t":"개구리","mis":"K5-2-u3-X10"},{"t":"거위","mis":"K5-2-u3-X10"},{"t":"고래","mis":"K5-2-u3-X10"}],"explanation":["까구리 · 깨고락지예요.","관계없어요.","고냉이는 고양이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#6','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C17',1,'mc','auto','제주 지역 마을에서 이웃 어른을 가족처럼 부르는 방언은 어느 것인가요?',ARRAY['K5-2-u3-X17']::text[],false,'{"seq":6,"concept":"K5-2-u3-C17","difficulty":1,"kind":"mc","stem":"제주 지역 마을에서 이웃 어른을 가족처럼 부르는 방언은 어느 것인가요?","options":[{"t":"삼춘","correct":true},{"t":"올레","mis":"K5-2-u3-X17"},{"t":"정낭","mis":"K5-2-u3-X17"},{"t":"물허벅","mis":"K5-2-u3-X17"}],"explanation":["좁은 길이에요.","대문 가로대예요.","마을 어른을 불러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#7','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C12',1,'ox','auto','같은 사람도 듣는 사람과 자리에 따라 표준어와 방언을 골라 쓸 수 있어요.',ARRAY['K5-2-u3-X12']::text[],false,'{"seq":7,"concept":"K5-2-u3-C12","difficulty":1,"kind":"ox","stem":"같은 사람도 듣는 사람과 자리에 따라 표준어와 방언을 골라 쓸 수 있어요.","answer":"O","reason_options":[{"t":"말을 고르는 기준은 누구에게, 어떤 자리에서 말하느냐이기 때문에","correct":true},{"t":"한 사람은 한 가지 말만 써야 하기 때문에","mis":"K5-2-u3-X12"}],"mis":"K5-2-u3-X12","explanation":["자리에 따라 골라요.","듣는 사람이 기준이에요.","골라 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#8','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C21',1,'mc','auto','「감 따는 날」에서 마을 정자에 모여 하준이에게 말을 건 사람은 누구인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":8,"concept":"K5-2-u3-C21","difficulty":1,"kind":"mc","stem":"「감 따는 날」에서 마을 정자에 모여 하준이에게 말을 건 사람은 누구인가요?","options":[{"t":"할머니들","correct":true},{"t":"하준이 친구들","mis":"K5-2-u3-X21"},{"t":"선생님들","mis":"K5-2-u3-X21"},{"t":"관광객들","mis":"K5-2-u3-X21"}],"explanation":["글에 없어요.","글에 없어요.","둘째 줄에 나와요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#9','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C9',2,'mc','auto','「우리 집 말 조사 일지」에서 외할머니가 쓰시는 방언 「할망」의 표준어는 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":9,"concept":"K5-2-u3-C9","difficulty":2,"kind":"mc","stem":"「우리 집 말 조사 일지」에서 외할머니가 쓰시는 방언 「할망」의 표준어는 어느 것인가요?","options":[{"t":"할머니","correct":true},{"t":"할아버지","mis":"K5-2-u3-X10"},{"t":"아주머니","mis":"K5-2-u3-X10"},{"t":"어머니","mis":"K5-2-u3-X10"}],"explanation":["다른 분이에요.","다른 분이에요.","할망은 할머니예요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#10','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C8',2,'mc','auto','방언이 표준어가 된 예와 그 까닭을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-2-u3-X07','K5-2-u3-X08']::text[],false,'{"seq":10,"concept":"K5-2-u3-C8","difficulty":2,"kind":"mc","stem":"방언이 표준어가 된 예와 그 까닭을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"멍게 — 표준어보다 더 널리 쓰이게 되어서","correct":true},{"t":"멍게 — 국립국어원이 아무렇게나 골라서","mis":"K5-2-u3-X07"},{"t":"개구리 — 원래 제주 지역 방언이라서","mis":"K5-2-u3-X08"},{"t":"정구지 — 글자 수가 적어서","mis":"K5-2-u3-X07"}],"explanation":["기준을 살펴 정해요.","개구리는 원래 표준어예요.","널리 쓰인 것이 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#11','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C31',2,'mc','auto','상황 카드 네 장에 어울리는 말을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-2-u3-X31','K5-2-u3-X30']::text[],false,'{"seq":11,"concept":"K5-2-u3-C31","difficulty":2,"kind":"mc","stem":"상황 카드 네 장에 어울리는 말을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"㉮ 방언 · ㉯ 표준어 · ㉰ 표준어 · ㉱ 방언","correct":true},{"t":"㉮ 표준어 · ㉯ 방언 · ㉰ 방언 · ㉱ 표준어","mis":"K5-2-u3-X31"},{"t":"㉮ ㉯ ㉰ ㉱ 모두 표준어","mis":"K5-2-u3-X30"},{"t":"㉮ ㉯ ㉰ ㉱ 모두 방언","mis":"K5-2-u3-X30"}],"explanation":["거꾸로예요.","자리마다 달라요.","듣는 사람과 목적을 봐요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#12','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C19',2,'mc','auto','방언의 가치를 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u3-X20','K5-2-u3-X07','K5-2-u3-X19']::text[],false,'{"seq":12,"concept":"K5-2-u3-C19","difficulty":2,"kind":"mc","stem":"방언의 가치를 바르게 말한 것은 어느 것인가요?","options":[{"t":"지역의 자연과 생활, 사람들의 정을 담아 지역의 문화를 지킨다","correct":true},{"t":"다른 지역과 말이 통하지 않게 막아 준다","mis":"K5-2-u3-X20"},{"t":"표준어보다 글자 수가 적다","mis":"K5-2-u3-X07"},{"t":"쓸모없는 옛말이라 곧 사라져도 된다","mis":"K5-2-u3-X19"}],"explanation":["막는 말이 아니에요.","관계없어요.","문화를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#13','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C22',2,'mc','auto','「하얗겄제」처럼 뜻을 모르는 방언 끝말이 나왔을 때 앞뒤 장면으로 짐작하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X22','K5-2-u3-X10']::text[],false,'{"seq":13,"concept":"K5-2-u3-C22","difficulty":2,"kind":"mc","stem":"「하얗겄제」처럼 뜻을 모르는 방언 끝말이 나왔을 때 앞뒤 장면으로 짐작하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"서울에서 왔다는 말을 듣고 한 말이니 「하얗겠지」로 짐작한다","correct":true},{"t":"뜻을 모르니 그 문장은 빼고 읽는다","mis":"K5-2-u3-X22"},{"t":"아무 뜻이 없는 소리라고 여긴다","mis":"K5-2-u3-X22"},{"t":"처음 떠오른 뜻을 확인 없이 정답으로 정한다","mis":"K5-2-u3-X10"}],"explanation":["놓치는 것이 생겨요.","뜻이 있어요.","앞뒤 장면이 근거예요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#14','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C27',2,'mc','auto','방언 지도를 만들 때 조사하기 바로 앞에 하는 일은 어느 것인가요?',ARRAY['K5-2-u3-X27']::text[],false,'{"seq":14,"concept":"K5-2-u3-C27","difficulty":2,"kind":"mc","stem":"방언 지도를 만들 때 조사하기 바로 앞에 하는 일은 어느 것인가요?","options":[{"t":"모둠마다 조사할 지역 나누기","correct":true},{"t":"지도에 카드 붙이기","mis":"K5-2-u3-X27"},{"t":"둘러보며 이야기 나누기","mis":"K5-2-u3-X27"},{"t":"상장 나누어 주기","mis":"K5-2-u3-X27"}],"explanation":["맨 끝이에요.","맨 끝이에요.","지역을 나누고 조사해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#15','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C16',2,'mc','auto','표준어와 방언 사용 상황을 조사할 때 살펴볼 세 가지로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X16','K5-2-u3-X15']::text[],false,'{"seq":15,"concept":"K5-2-u3-C16","difficulty":2,"kind":"mc","stem":"표준어와 방언 사용 상황을 조사할 때 살펴볼 세 가지로 알맞은 것은 어느 것인가요?","options":[{"t":"누구에게 · 어떤 상황에서 · 어떤 사이","correct":true},{"t":"언제 태어났는지 · 키 · 몸무게","mis":"K5-2-u3-X16"},{"t":"목소리 크기 · 말 빠르기 · 날씨","mis":"K5-2-u3-X16"},{"t":"글자 수 · 맞춤법 · 띄어쓰기","mis":"K5-2-u3-X15"}],"explanation":["관계없어요.","관계없어요.","듣는 사람 · 자리 · 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#16','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C32',2,'mc','auto','「장수」가 「군사를 거느리는 우두머리」의 뜻으로 쓰인 문장은 어느 것인가요?',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":16,"concept":"K5-2-u3-C32","difficulty":2,"kind":"mc","stem":"「장수」가 「군사를 거느리는 우두머리」의 뜻으로 쓰인 문장은 어느 것인가요?","options":[{"t":"장수가 군사들을 이끌고 앞으로 나아갔다.","correct":true},{"t":"과일 장수에게서 사과를 샀다.","mis":"K5-2-u3-X32"},{"t":"거북은 장수하는 동물로 알려져 있다.","mis":"K5-2-u3-X32"},{"t":"시장의 생선 장수가 크게 외쳤다.","mis":"K5-2-u3-X32"}],"explanation":["장사하는 사람이에요.","오래도록 사는 것이에요.","군사를 이끌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#17','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C30',3,'mc','auto','「우리 집 말 조사 일지」 글쓴이의 생각과 가장 가까운 것은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X30']::text[],false,'{"seq":17,"concept":"K5-2-u3-C30","difficulty":3,"kind":"mc","stem":"「우리 집 말 조사 일지」 글쓴이의 생각과 가장 가까운 것은 어느 것인가요?","options":[{"t":"가족의 방언은 신기하고 소중하며, 여럿이 듣는 발표에서는 표준어로 바꾸되 뜻과 함께 소개한다","correct":true},{"t":"가족의 방언은 틀린 말이니 쓰지 않게 해야 한다","mis":"K5-2-u3-X01"},{"t":"방언만 소중하니 발표도 방언으로만 한다","mis":"K5-2-u3-X30"},{"t":"표준어만 소중하니 방언은 조사할 필요가 없다","mis":"K5-2-u3-X30"}],"explanation":["틀린 말이 아니에요.","듣는 친구들을 생각해요.","둘 다 살려요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#18','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C31',3,'mc','auto','표준어를 주로 쓰는 경기 지역 마을이 축제 홍보 문구를 정할 때 가장 알맞은 생각은 어느 것인가요?',ARRAY['K5-2-u3-X31']::text[],false,'{"seq":18,"concept":"K5-2-u3-C31","difficulty":3,"kind":"mc","stem":"표준어를 주로 쓰는 경기 지역 마을이 축제 홍보 문구를 정할 때 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"그 지역에서 실제로 쓰는 말이 표준어라면 표준어로 지역의 정서를 보여 줄 수도 있다","correct":true},{"t":"축제니까 무조건 방언을 써야 한다","mis":"K5-2-u3-X31"},{"t":"다른 지역 방언을 빌려 써야 한다","mis":"K5-2-u3-X31"},{"t":"홍보 문구에는 아무 말도 쓰지 않는다","mis":"K5-2-u3-X31"}],"explanation":["외워서 고르지 않아요.","그 지역의 말이 아니에요.","목적과 실제 쓰는 말이 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#19','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C24',3,'mc','auto','「감 따는 날」의 할머니들 대사를 모두 표준어로 바꾼다면 가장 크게 달라지는 것은 어느 것인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":19,"concept":"K5-2-u3-C24","difficulty":3,"kind":"mc","stem":"「감 따는 날」의 할머니들 대사를 모두 표준어로 바꾼다면 가장 크게 달라지는 것은 어느 것인가요?","options":[{"t":"남쪽 바닷가 마을의 분위기와 할머니들의 정다운 목소리","correct":true},{"t":"하준이가 감을 딴 일","mis":"K5-2-u3-X21"},{"t":"이야기의 계절","mis":"K5-2-u3-X21"},{"t":"등장인물의 수","mis":"K5-2-u3-X21"}],"explanation":["줄거리는 같아요.","그대로예요.","분위기와 목소리가 달라져요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#20','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C18',3,'mc','auto','강원 지역의 「감재옹심이」와 전라 지역의 「뻘」에 공통으로 담긴 것은 어느 것인가요?',ARRAY['K5-2-u3-X07','K5-2-u3-X29','K5-2-u3-X17']::text[],false,'{"seq":20,"concept":"K5-2-u3-C18","difficulty":3,"kind":"mc","stem":"강원 지역의 「감재옹심이」와 전라 지역의 「뻘」에 공통으로 담긴 것은 어느 것인가요?","options":[{"t":"그 지역의 자연환경과 생활 모습","correct":true},{"t":"표준어를 정하는 기준","mis":"K5-2-u3-X07"},{"t":"웃음거리가 되는 말투","mis":"K5-2-u3-X29"},{"t":"아무 뜻 없는 소리","mis":"K5-2-u3-X17"}],"explanation":["관계없어요.","존중해야 해요.","자연과 생활이 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#21','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C29',3,'mc','auto','방언 지도를 둘러보다 낯선 방언이 나왔을 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X11','K5-2-u3-X19']::text[],false,'{"seq":21,"concept":"K5-2-u3-C29","difficulty":3,"kind":"mc","stem":"방언 지도를 둘러보다 낯선 방언이 나왔을 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"어떤 생활과 이어지는 말인지 궁금해하며 묻는다","correct":true},{"t":"이상한 말이라며 웃는다","mis":"K5-2-u3-X29"},{"t":"틀린 카드라고 떼어 낸다","mis":"K5-2-u3-X11"},{"t":"못 본 척 지나간다","mis":"K5-2-u3-X19"}],"explanation":["웃음거리로 삼지 않아요.","틀린 것이 아니에요.","궁금한 마음으로 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#22','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C30',3,'mc','auto','표준어와 방언의 관계를 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K5-2-u3-X30']::text[],false,'{"seq":22,"concept":"K5-2-u3-C30","difficulty":3,"kind":"mc","stem":"표준어와 방언의 관계를 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"서로 겨루는 말이 아니라 함께 어우러지는 우리말이다","correct":true},{"t":"표준어가 방언을 대신해야 한다","mis":"K5-2-u3-X30"},{"t":"방언이 표준어보다 늘 낫다","mis":"K5-2-u3-X30"},{"t":"둘 가운데 하나는 없어져야 한다","mis":"K5-2-u3-X30"}],"explanation":["둘 다 필요해요.","늘 나은 말은 없어요.","함께 어우러져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#23','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C31',4,'essay','teacher','상황 카드 ㉮~㉱에서 각각 표준어와 방언 가운데 어울리는 말을 고르고, 그렇게 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u3-C31","difficulty":4,"kind":"essay","stem":"상황 카드 ㉮~㉱에서 각각 표준어와 방언 가운데 어울리는 말을 고르고, 그렇게 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉮는 방언 — 어릴 적부터 함께 쓰던 말로 마음을 나누기 때문이다. ㉯는 표준어 — 여러 지역 사람들이 보기 때문이다. ㉰는 표준어 — 여러 지역 사람들이 서로 잘 이해해야 하기 때문이다. ㉱는 방언 — 지역의 정서와 특성을 보여 주어야 하기 때문이다(표준어를 쓰는 지역이라면 표준어도 답이 된다).","scoring_points":["네 상황에 어울리는 말을 골랐는가","상황마다 까닭을 썼는가","까닭이 듣는 사람이나 목적과 이어지는가"]},"explanation":["네 장을 모두 골라요.","까닭을 써요.","듣는 사람과 목적이 근거예요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#24','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C19',4,'essay','teacher','우리 가족이나 이웃이 쓰는 말 가운데 지키고 싶은 말을 하나 골라, 그 말에 담긴 생활이나 마음과 지키고 싶은 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u3-C19","difficulty":4,"kind":"essay","stem":"우리 가족이나 이웃이 쓰는 말 가운데 지키고 싶은 말을 하나 골라, 그 말에 담긴 생활이나 마음과 지키고 싶은 까닭을 쓰세요.","answer_guide":{"answer":"예: 할머니께서 나를 부르실 때 쓰시는 「아야」를 지키고 싶다. 이 말에는 손주를 아끼시는 할머니의 마음과 고향 마을의 정이 담겨 있다. 이 말이 사라지면 할머니와의 추억과 고향 이야기도 함께 잊힐 것 같아 지키고 싶다.","scoring_points":["지키고 싶은 말을 골랐는가","담긴 생활이나 마음을 썼는가","지키고 싶은 까닭을 썼는가"]},"explanation":["말을 골라요.","담긴 것을 써요.","까닭을 써요. 표준어 표현이어도 괜찮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#25','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C28',4,'essay','teacher','우리 반 방언 지도에 붙일 카드 한 장을 써 보세요. 방언, 쓰는 지역, 뜻, 이어지는 생활을 모두 넣으세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u3-C28","difficulty":4,"kind":"essay","stem":"우리 반 방언 지도에 붙일 카드 한 장을 써 보세요. 방언, 쓰는 지역, 뜻, 이어지는 생활을 모두 넣으세요.","answer_guide":{"answer":"예: 방언 — 뻘, 쓰는 지역 — 전라 지역, 뜻 — 갯벌, 이어지는 생활 — 서해안에 넓게 펼쳐진 갯벌에서 조개를 캐고 물고기를 잡으며 살아온 마을 사람들의 생활이 담겨 있다.","scoring_points":["방언과 쓰는 지역을 썼는가","뜻을 썼는가","이어지는 생활을 썼는가"]},"explanation":["방언과 지역이에요.","뜻이에요.","생활까지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#1','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C3',1,'mc','auto','특정 지역에서 주로 쓰고 그 지역의 생활과 정을 담은, 표준어가 아닌 말은 어느 것인가요?',ARRAY['K5-2-u3-X03','K5-2-u3-X01']::text[],false,'{"seq":1,"concept":"K5-2-u3-C3","difficulty":1,"kind":"mc","stem":"특정 지역에서 주로 쓰고 그 지역의 생활과 정을 담은, 표준어가 아닌 말은 어느 것인가요?","options":[{"t":"방언","correct":true},{"t":"표준어","mis":"K5-2-u3-X03"},{"t":"외래어","mis":"K5-2-u3-X01"},{"t":"줄임말","mis":"K5-2-u3-X01"}],"explanation":["함께 쓰도록 정한 말이에요.","다른 나라에서 온 말이에요.","지역의 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#2','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C32',1,'mc','auto','「하늘에서 하얀 눈이 내린다.」의 「눈」과 같은 뜻으로 쓰인 것은 어느 것인가요?',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":2,"concept":"K5-2-u3-C32","difficulty":1,"kind":"mc","stem":"「하늘에서 하얀 눈이 내린다.」의 「눈」과 같은 뜻으로 쓰인 것은 어느 것인가요?","options":[{"t":"밤새 눈이 소복이 쌓였다.","correct":true},{"t":"눈을 감고 소원을 빌었다.","mis":"K5-2-u3-X32"},{"t":"눈이 나빠 안경을 썼다.","mis":"K5-2-u3-X32"},{"t":"눈으로 글자를 따라 읽었다.","mis":"K5-2-u3-X32"}],"explanation":["보는 눈이에요.","보는 눈이에요.","하늘에서 내리는 눈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#3','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C6',1,'mc','auto','지역마다 말이 다르면 생기는 어려움을 덜려고 정한 말은 어느 것인가요?',ARRAY['K5-2-u3-X06','K5-2-u3-X32','K5-2-u3-X29']::text[],false,'{"seq":3,"concept":"K5-2-u3-C6","difficulty":1,"kind":"mc","stem":"지역마다 말이 다르면 생기는 어려움을 덜려고 정한 말은 어느 것인가요?","options":[{"t":"표준어","correct":true},{"t":"방언","mis":"K5-2-u3-X06"},{"t":"동형어","mis":"K5-2-u3-X32"},{"t":"흉내 말","mis":"K5-2-u3-X29"}],"explanation":["방언은 지역의 말이에요.","모양이 같은 말이에요.","함께 알아듣게 정한 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#4','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C31',1,'mc','auto','상황 카드 ㉮ 「고향 친구와 오랜만에 만나 이야기할 때」에 어울리기도 하는 말은 어느 것인가요?',ARRAY['K5-2-u3-X14','K5-2-u3-X31']::text[],false,'{"seq":4,"concept":"K5-2-u3-C31","difficulty":1,"kind":"mc","stem":"상황 카드 ㉮ 「고향 친구와 오랜만에 만나 이야기할 때」에 어울리기도 하는 말은 어느 것인가요?","options":[{"t":"방언","correct":true},{"t":"표준어만 써야 한다","mis":"K5-2-u3-X14"},{"t":"외국어","mis":"K5-2-u3-X31"},{"t":"아무 말도 하지 않는다","mis":"K5-2-u3-X31"}],"explanation":["방언도 어울려요.","알맞지 않아요.","어릴 적 함께 쓰던 말이에요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#5','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C9',1,'mc','auto','「정구지」를 표준어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":5,"concept":"K5-2-u3-C9","difficulty":1,"kind":"mc","stem":"「정구지」를 표준어로 바꾸면 어느 것인가요?","options":[{"t":"부추","correct":true},{"t":"가위","mis":"K5-2-u3-X10"},{"t":"나무","mis":"K5-2-u3-X10"},{"t":"김치","mis":"K5-2-u3-X10"}],"explanation":["가새기예요.","낭구예요.","정구지는 부추예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#6','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C18',1,'mc','auto','「돔배기」는 무엇을 가리키는 방언인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":6,"concept":"K5-2-u3-C18","difficulty":1,"kind":"mc","stem":"「돔배기」는 무엇을 가리키는 방언인가요?","options":[{"t":"소금에 절여 토막 낸 상어고기","correct":true},{"t":"갯벌","mis":"K5-2-u3-X10"},{"t":"감자를 갈아 빚은 음식","mis":"K5-2-u3-X10"},{"t":"집과 집 사이 좁은 길","mis":"K5-2-u3-X10"}],"explanation":["뻘이에요.","감재옹심이예요.","경상 지역 먹을거리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#7','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C15',1,'ox','auto','방언을 표준어로 바꾸어 보는 것은 틀린 방언을 고치는 일이에요.',ARRAY['K5-2-u3-X15']::text[],false,'{"seq":7,"concept":"K5-2-u3-C15","difficulty":1,"kind":"ox","stem":"방언을 표준어로 바꾸어 보는 것은 틀린 방언을 고치는 일이에요.","answer":"X","reason_options":[{"t":"상황에 따라 말이 달리 쓰인다는 것을 알기 위한 것이기 때문에","correct":true},{"t":"방언은 고쳐야 할 말이기 때문에","mis":"K5-2-u3-X15"}],"mis":"K5-2-u3-X15","explanation":["고치기가 아니에요.","선택을 알아요.","방언은 틀린 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#8','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C24',1,'mc','auto','이야기에 방언을 쓸 때 잘 살아나는 것은 어느 것인가요?',ARRAY['K5-2-u3-X24']::text[],false,'{"seq":8,"concept":"K5-2-u3-C24","difficulty":1,"kind":"mc","stem":"이야기에 방언을 쓸 때 잘 살아나는 것은 어느 것인가요?","options":[{"t":"인물 사이의 정과 마을 분위기","correct":true},{"t":"글자의 크기","mis":"K5-2-u3-X24"},{"t":"책의 쪽수","mis":"K5-2-u3-X24"},{"t":"표지의 색깔","mis":"K5-2-u3-X24"}],"explanation":["관계없어요.","관계없어요.","정과 분위기가 살아나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#9','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C9',2,'mc','auto','「우리 집 말 조사 일지」의 「낭구」는 무엇을 가리키나요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":9,"concept":"K5-2-u3-C9","difficulty":2,"kind":"mc","stem":"「우리 집 말 조사 일지」의 「낭구」는 무엇을 가리키나요?","options":[{"t":"나무","correct":true},{"t":"나물","mis":"K5-2-u3-X10"},{"t":"낫","mis":"K5-2-u3-X10"},{"t":"냇물","mis":"K5-2-u3-X10"}],"explanation":["뒷산에 빽빽한 것이에요.","도구가 아니에요.","낭구는 나무예요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#10','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C7',2,'mc','auto','다음 가운데 표준어를 정하는 기준이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u3-X07']::text[],false,'{"seq":10,"concept":"K5-2-u3-C7","difficulty":2,"kind":"mc","stem":"다음 가운데 표준어를 정하는 기준이 아닌 것은 어느 것인가요?","options":[{"t":"말하는 사람이 서울에 사는지","correct":true},{"t":"사람들이 두루 쓰는지","mis":"K5-2-u3-X07"},{"t":"문법에 맞는지","mis":"K5-2-u3-X07"},{"t":"발음하기 자연스러운지","mis":"K5-2-u3-X07"}],"explanation":["기준이에요.","기준이에요.","사는 곳은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#11','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C31',2,'error','auto','상황 카드를 고른 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X31','K5-2-u3-X13','K5-2-u3-X14']::text[],false,'{"seq":11,"concept":"K5-2-u3-C31","difficulty":2,"kind":"error","stem":"상황 카드를 고른 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「까닭은 생각하지 않고 느낌대로 아무 말이나 고르면 돼.」","correct":true,"mis_target":"K5-2-u3-X31"},{"t":"「㉰는 여러 지역 사람이 서로 잘 알아들어야 하니 표준어야.」","mis":"K5-2-u3-X13"},{"t":"「㉮는 어릴 적부터 쓰던 말로 마음을 나누니 방언이야.」","mis":"K5-2-u3-X14"}],"explanation":["까닭이 있어요.","까닭이 있어요.","까닭과 함께 골라요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#12','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C19',2,'ox','auto','방언에는 우리말의 옛 모습이 간직되어 있어요.',ARRAY['K5-2-u3-X19']::text[],false,'{"seq":12,"concept":"K5-2-u3-C19","difficulty":2,"kind":"ox","stem":"방언에는 우리말의 옛 모습이 간직되어 있어요.","answer":"O","reason_options":[{"t":"지역의 삶과 함께 오랫동안 이어져 온 말이기 때문에","correct":true},{"t":"방언은 요즘 새로 만든 말이기 때문에","mis":"K5-2-u3-X19"}],"mis":"K5-2-u3-X19","explanation":["오래된 말이에요.","옛 모습이 남아요.","가치가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#13','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C23',2,'mc','auto','방언 문장과 표준어 문장을 견주어 읽을 때 살펴볼 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X15','K5-2-u3-X23','K5-2-u3-X24']::text[],false,'{"seq":13,"concept":"K5-2-u3-C23","difficulty":2,"kind":"mc","stem":"방언 문장과 표준어 문장을 견주어 읽을 때 살펴볼 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어느 쪽에서 인물의 목소리와 마음이 더 생생한지","correct":true},{"t":"어느 쪽이 맞춤법에 맞는지만","mis":"K5-2-u3-X15"},{"t":"어느 쪽 글자 수가 많은지","mis":"K5-2-u3-X23"},{"t":"어느 쪽이 더 빨리 읽히는지만","mis":"K5-2-u3-X24"}],"explanation":["고치기가 아니에요.","관계없어요.","느낌을 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#14','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C28',2,'mc','auto','좋은 방언 지도의 조건으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X28']::text[],false,'{"seq":14,"concept":"K5-2-u3-C28","difficulty":2,"kind":"mc","stem":"좋은 방언 지도의 조건으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"방언과 뜻, 그 말과 이어지는 생활이 함께 드러난다","correct":true},{"t":"방언 개수가 가장 많다","mis":"K5-2-u3-X28"},{"t":"그림이 가장 화려하다","mis":"K5-2-u3-X28"},{"t":"지역 이름이 없어도 된다","mis":"K5-2-u3-X28"}],"explanation":["개수보다 생활이에요.","꾸미기보다 내용이에요.","뜻과 생활이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#15','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C10',2,'mc','auto','방언을 온라인 사전으로 찾는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X10','K5-2-u3-X11']::text[],false,'{"seq":15,"concept":"K5-2-u3-C10","difficulty":2,"kind":"mc","stem":"방언을 온라인 사전으로 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"국립국어원 지역어 누리집에서 표준어 낱말을 검색해 지역별 방언과 발음을 확인한다","correct":true},{"t":"짐작한 말을 적고 확인하지 않는다","mis":"K5-2-u3-X10"},{"t":"한 사람에게만 물어 정답으로 정한다","mis":"K5-2-u3-X11"},{"t":"외국어 사전에서 찾는다","mis":"K5-2-u3-X10"}],"explanation":["근거가 없어요.","정답은 하나가 아니에요.","지역어 누리집이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#16','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C32',2,'mc','auto','「쓰다」가 「맛이 쓰다」의 뜻으로 쓰인 문장은 어느 것인가요?',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":16,"concept":"K5-2-u3-C32","difficulty":2,"kind":"mc","stem":"「쓰다」가 「맛이 쓰다」의 뜻으로 쓰인 문장은 어느 것인가요?","options":[{"t":"약이 너무 써서 얼굴을 찡그렸다.","correct":true},{"t":"공책에 일기를 썼다.","mis":"K5-2-u3-X32"},{"t":"햇볕이 뜨거워 모자를 썼다.","mis":"K5-2-u3-X32"},{"t":"붓으로 이름을 썼다.","mis":"K5-2-u3-X32"}],"explanation":["글을 쓰다예요.","모자를 쓰다예요.","맛이 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#17','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C9',3,'mc','auto','「우리 집 말 조사 일지」를 읽고 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X09','K5-2-u3-X03']::text[],false,'{"seq":17,"concept":"K5-2-u3-C9","difficulty":3,"kind":"mc","stem":"「우리 집 말 조사 일지」를 읽고 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 우리말이라도 지역마다 부르는 이름이 여러 가지이다","correct":true},{"t":"가족끼리는 모두 같은 말을 쓴다","mis":"K5-2-u3-X09"},{"t":"방언은 할머니만 쓰는 말이다","mis":"K5-2-u3-X03"},{"t":"표준어는 강원 지역 말이다","mis":"K5-2-u3-X03"}],"explanation":["가족마다 달라요.","고모 · 큰아버지도 써요.","부르는 이름이 여러 가지예요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#18','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C13',3,'mc','auto','전국 어린이 회의가 끝난 뒤 쉬는 시간에 자기 고장 말로 인사를 나누는 모습에서 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X12','K5-2-u3-X14','K5-2-u3-X30']::text[],false,'{"seq":18,"concept":"K5-2-u3-C13","difficulty":3,"kind":"mc","stem":"전국 어린이 회의가 끝난 뒤 쉬는 시간에 자기 고장 말로 인사를 나누는 모습에서 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"공식적인 회의와 쉬는 시간처럼 자리에 따라 어울리는 말을 고른다","correct":true},{"t":"회의에서 표준어를 쓴 것은 잘못이다","mis":"K5-2-u3-X12"},{"t":"쉬는 시간에도 표준어만 써야 한다","mis":"K5-2-u3-X14"},{"t":"고장 말로 인사하면 회의를 망친다","mis":"K5-2-u3-X30"}],"explanation":["회의에는 표준어가 알맞아요.","쉬는 시간엔 정을 나눠요.","자리에 따라 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#19','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C25',3,'mc','auto','「감 따는 날」을 내 삶과 이어 감상한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X25','K5-2-u3-X29']::text[],false,'{"seq":19,"concept":"K5-2-u3-C25","difficulty":3,"kind":"mc","stem":"「감 따는 날」을 내 삶과 이어 감상한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「처음 간 친척 집에서 낯선 말이 어색했지만 반겨 주셔서 금방 정이 들었던 기억이 떠올랐어.」","correct":true},{"t":"「감나무는 가을에 열매가 익어.」","mis":"K5-2-u3-X25"},{"t":"「할머니들 말투가 웃기니까 따라 해 봐야지.」","mis":"K5-2-u3-X29"},{"t":"「줄거리만 알면 됐지 내 이야기는 필요 없어.」","mis":"K5-2-u3-X25"}],"explanation":["작품과 내 삶이 이어지지 않아요.","흉내는 예의가 아니에요.","하준이 마음과 내 경험을 이었어요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#20','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C20',3,'mc','auto','방언이 사라지면 함께 잊힐 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X20','K5-2-u3-X32']::text[],false,'{"seq":20,"concept":"K5-2-u3-C20","difficulty":3,"kind":"mc","stem":"방언이 사라지면 함께 잊힐 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 말에 담긴 지역의 생활과 이야기","correct":true},{"t":"표준어","mis":"K5-2-u3-X20"},{"t":"국립국어원","mis":"K5-2-u3-X20"},{"t":"동형어","mis":"K5-2-u3-X32"}],"explanation":["그대로 남아요.","그대로 남아요.","관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#21','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C11',3,'mc','auto','두 모둠이 「짐치」를 각각 경상 지역과 강원 지역에 붙였을 때 지도에서 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X11','K5-2-u3-X03','K5-2-u3-X09']::text[],false,'{"seq":21,"concept":"K5-2-u3-C11","difficulty":3,"kind":"mc","stem":"두 모둠이 「짐치」를 각각 경상 지역과 강원 지역에 붙였을 때 지도에서 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"한 방언이 여러 지역에 퍼져 쓰이는 모습","correct":true},{"t":"한 모둠이 틀렸다는 것","mis":"K5-2-u3-X11"},{"t":"짐치는 표준어라는 것","mis":"K5-2-u3-X03"},{"t":"두 지역의 김치는 다른 음식이라는 것","mis":"K5-2-u3-X09"}],"explanation":["둘 다 맞아요.","방언이에요.","퍼져 쓰여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#22','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C4',3,'mc','auto','이 단원에서 배운 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X04']::text[],false,'{"seq":22,"concept":"K5-2-u3-C4","difficulty":3,"kind":"mc","stem":"이 단원에서 배운 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"뜻 알기 → 사용 상황 조사 → 방언의 가치 → 작품 감상 → 방언 지도","correct":true},{"t":"작품 감상 → 뜻 알기 → 방언 지도 → 사용 상황 조사 → 방언의 가치","mis":"K5-2-u3-X04"},{"t":"방언 지도 → 방언의 가치 → 뜻 알기 → 작품 감상 → 사용 상황 조사","mis":"K5-2-u3-X04"},{"t":"사용 상황 조사 → 방언 지도 → 작품 감상 → 뜻 알기 → 방언의 가치","mis":"K5-2-u3-X04"}],"explanation":["뜻이 먼저예요.","방언 지도는 끝이에요.","단원의 흐름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#23','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C30',4,'essay','teacher','표준어와 방언을 모두 소중히 여겨야 하는 까닭을 발표문 두세 문장으로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u3-C30","difficulty":4,"kind":"essay","stem":"표준어와 방언을 모두 소중히 여겨야 하는 까닭을 발표문 두세 문장으로 쓰세요.","answer_guide":{"answer":"예: 여러분, 표준어는 어느 지역 사람과도 뜻이 통하게 해 줍니다. 방언은 지역의 자연과 생활, 사람들의 정을 담고 있습니다. 그래서 우리는 두 말을 상황에 맞게 아끼며 써야 합니다.","scoring_points":["표준어의 가치를 썼는가","방언의 가치를 썼는가","발표문 형식으로 두 말을 함께 아끼자고 정리했는가"]},"explanation":["표준어가 하는 일이에요.","방언이 하는 일이에요.","둘 다 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#24','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C25',4,'essay','teacher','방언이 나오는 이야기나 영상을 보았거나 방언을 들었던 경험을 떠올려, 그때의 느낌과 방언이 한 역할을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u3-C25","difficulty":4,"kind":"essay","stem":"방언이 나오는 이야기나 영상을 보았거나 방언을 들었던 경험을 떠올려, 그때의 느낌과 방언이 한 역할을 쓰세요.","answer_guide":{"answer":"예: 명절에 큰집에 갔을 때 큰아버지께서 고향 말로 반겨 주셨다. 처음에는 낯설었지만 웃음이 섞인 말투에 마음이 금방 편해졌다. 방언이 오랜만에 만난 가족 사이를 더 가깝게 이어 주는 역할을 했다.","scoring_points":["경험을 떠올려 썼는가","그때의 느낌을 썼는가","방언이 한 역할을 썼는가"]},"explanation":["경험을 써요.","느낌을 써요.","역할을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#25','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C24',4,'essay','teacher','「감 따는 날」의 한 장면을 골라 방언 대사와 표준어 대사를 견주고, 작품에 방언을 쓴 효과를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u3-C24","difficulty":4,"kind":"essay","stem":"「감 따는 날」의 한 장면을 골라 방언 대사와 표준어 대사를 견주고, 작품에 방언을 쓴 효과를 쓰세요.","answer_guide":{"answer":"예: 외할머니가 「아야, 싸게싸게 와서 바구니 잡아라잉.」 하고 부르는 장면을 표준어로 바꾸면 「얘야, 빨리빨리 와서 바구니 잡아라.」이다. 뜻은 같지만 방언 대사에서 손주를 부르는 외할머니의 다정한 목소리와 바닷가 마을 분위기가 더 생생하게 살아난다.","scoring_points":["장면을 골라 방언 대사를 썼는가","표준어 대사로 바꾸어 견주었는가","방언을 쓴 효과를 썼는가"]},"explanation":["대사를 골라요.","바꾸어 견주어요.","효과를 써요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#1','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C2',1,'ox','auto','표준어는 서울에 사는 사람만 쓰는 말이에요.',ARRAY['K5-2-u3-X03']::text[],false,'{"seq":1,"concept":"K5-2-u3-C2","difficulty":1,"kind":"ox","stem":"표준어는 서울에 사는 사람만 쓰는 말이에요.","answer":"X","reason_options":[{"t":"어느 지역 사람이든 함께 알아듣도록 정한 말이기 때문에","correct":true},{"t":"서울 말이 가장 고운 말이기 때문에","mis":"K5-2-u3-X03"}],"mis":"K5-2-u3-X03","explanation":["어디서나 써요.","함께 알아듣게 정했어요.","모두의 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#2','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C32',1,'blank','auto','「( ? )을 먹다.」 · 「( ? )이 난다.」 · 「( ? )을 매다.」의 빈칸에 공통으로 들어갈 말은 어느 것인가요?',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":2,"concept":"K5-2-u3-C32","difficulty":1,"kind":"blank","stem":"「( ? )을 먹다.」 · 「( ? )이 난다.」 · 「( ? )을 매다.」의 빈칸에 공통으로 들어갈 말은 어느 것인가요?","options":[{"t":"김","correct":true},{"t":"밥","mis":"K5-2-u3-X32"},{"t":"물","mis":"K5-2-u3-X32"},{"t":"끈","mis":"K5-2-u3-X32"}],"explanation":["밥은 나지 않아요.","물은 매지 않아요.","먹는 김 · 나는 김 · 매는 김이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#3','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C7',1,'mc','auto','표준어를 정할 때 사람들이 두루 쓰는지, 문법에 맞는지 등을 살피는 곳은 어디인가요?',ARRAY['K5-2-u3-X07']::text[],false,'{"seq":3,"concept":"K5-2-u3-C7","difficulty":1,"kind":"mc","stem":"표준어를 정할 때 사람들이 두루 쓰는지, 문법에 맞는지 등을 살피는 곳은 어디인가요?","options":[{"t":"국립국어원","correct":true},{"t":"지역 신문사","mis":"K5-2-u3-X07"},{"t":"기차역","mis":"K5-2-u3-X07"},{"t":"동네 시장","mis":"K5-2-u3-X07"}],"explanation":["정하는 곳이 아니에요.","정하는 곳이 아니에요.","국립국어원이 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#4','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C13',1,'mc','auto','상황 카드 ㉰ 「전국 어린이 회의에서 발표할 때」 표준어를 쓰는 까닭은 무엇인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X03','K5-2-u3-X06']::text[],false,'{"seq":4,"concept":"K5-2-u3-C13","difficulty":1,"kind":"mc","stem":"상황 카드 ㉰ 「전국 어린이 회의에서 발표할 때」 표준어를 쓰는 까닭은 무엇인가요?","options":[{"t":"여러 지역 사람들이 서로 잘 알아들어야 해서","correct":true},{"t":"방언은 틀린 말이라서","mis":"K5-2-u3-X01"},{"t":"발표자가 서울 사람이라서","mis":"K5-2-u3-X03"},{"t":"표준어가 더 높은 말이라서","mis":"K5-2-u3-X06"}],"explanation":["틀린 말이 아니에요.","사는 곳과 관계없어요.","서로 알아들어야 해요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#5','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C22',1,'mc','auto','「감 따는 날」의 「그러니께」를 표준어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u3-X22']::text[],false,'{"seq":5,"concept":"K5-2-u3-C22","difficulty":1,"kind":"mc","stem":"「감 따는 날」의 「그러니께」를 표준어로 바꾸면 어느 것인가요?","options":[{"t":"그러니까","correct":true},{"t":"그런데","mis":"K5-2-u3-X22"},{"t":"그래도","mis":"K5-2-u3-X22"},{"t":"그러므로","mis":"K5-2-u3-X22"}],"explanation":["뜻이 달라요.","뜻이 달라요.","그러니께는 그러니까예요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#6','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C17',1,'mc','auto','「물허벅」은 무엇을 가리키는 방언인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":6,"concept":"K5-2-u3-C17","difficulty":1,"kind":"mc","stem":"「물허벅」은 무엇을 가리키는 방언인가요?","options":[{"t":"물을 길어 나르던 동이","correct":true},{"t":"대문 가로대","mis":"K5-2-u3-X10"},{"t":"마을 어른","mis":"K5-2-u3-X10"},{"t":"좁은 돌담길","mis":"K5-2-u3-X10"}],"explanation":["정낭이에요.","삼춘이에요.","물동이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#7','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C14',1,'ox','auto','고향 사람끼리 방언을 쓰면 더 친근하고 정답게 이야기할 수 있어요.',ARRAY['K5-2-u3-X14']::text[],false,'{"seq":7,"concept":"K5-2-u3-C14","difficulty":1,"kind":"ox","stem":"고향 사람끼리 방언을 쓰면 더 친근하고 정답게 이야기할 수 있어요.","answer":"O","reason_options":[{"t":"어릴 때부터 함께 쓰던 말로 마음을 나누기 때문에","correct":true},{"t":"방언은 친한 사이에서도 쓰면 안 되기 때문에","mis":"K5-2-u3-X14"}],"mis":"K5-2-u3-X14","explanation":["정을 나눠요.","친근해요.","고향 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#8','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C21',1,'mc','auto','「감 따는 날」에서 외할머니가 하준이에게 시킨 일은 무엇인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":8,"concept":"K5-2-u3-C21","difficulty":1,"kind":"mc","stem":"「감 따는 날」에서 외할머니가 하준이에게 시킨 일은 무엇인가요?","options":[{"t":"바구니 잡기","correct":true},{"t":"물 길어 오기","mis":"K5-2-u3-X21"},{"t":"정자 청소하기","mis":"K5-2-u3-X21"},{"t":"시장 다녀오기","mis":"K5-2-u3-X21"}],"explanation":["글에 없어요.","글에 없어요.","다섯째 줄에 나와요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#9','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C12',2,'mc','auto','글쓴이가 학교 발표에서 표준어로 바꾸어 소개하기로 한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X19','K5-2-u3-X14']::text[],false,'{"seq":9,"concept":"K5-2-u3-C12","difficulty":2,"kind":"mc","stem":"글쓴이가 학교 발표에서 표준어로 바꾸어 소개하기로 한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"반 친구들이 모두 알아듣게 하려고","correct":true},{"t":"가족의 방언이 틀린 말이라서","mis":"K5-2-u3-X01"},{"t":"가족의 말을 부끄럽게 여겨서","mis":"K5-2-u3-X19"},{"t":"선생님이 방언을 쓰지 말라고 해서","mis":"K5-2-u3-X14"}],"explanation":["틀린 말이 아니에요.","뜻과 함께 소개해요.","여러 친구가 들어요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#10','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C8',2,'mc','auto','표준어와 방언 사이를 가장 알맞게 설명한 것은 어느 것인가요?',ARRAY['K5-2-u3-X08','K5-2-u3-X06','K5-2-u3-X30']::text[],false,'{"seq":10,"concept":"K5-2-u3-C8","difficulty":2,"kind":"mc","stem":"표준어와 방언 사이를 가장 알맞게 설명한 것은 어느 것인가요?","options":[{"t":"꽉 막힌 벽이 아니라 널리 쓰이면 오가기도 하는 움직이는 경계이다","correct":true},{"t":"방언은 영원히 방언으로만 남는다","mis":"K5-2-u3-X08"},{"t":"표준어는 방언보다 높은 말이다","mis":"K5-2-u3-X06"},{"t":"둘은 서로 아무 관계가 없다","mis":"K5-2-u3-X30"}],"explanation":["멍게를 떠올려요.","높고 낮음이 없어요.","서로 오가기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#11','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C30',2,'mc','auto','상황 카드 고르기를 하고 나서 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X30','K5-2-u3-X12']::text[],false,'{"seq":11,"concept":"K5-2-u3-C30","difficulty":2,"kind":"mc","stem":"상황 카드 고르기를 하고 나서 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어느 말이 늘 더 좋은 것이 아니라 상황에 따라 어울리는 말이 다르다","correct":true},{"t":"표준어가 언제나 정답이다","mis":"K5-2-u3-X30"},{"t":"방언이 언제나 정답이다","mis":"K5-2-u3-X30"},{"t":"상황과 말은 관계가 없다","mis":"K5-2-u3-X12"}],"explanation":["늘 정답은 없어요.","늘 정답은 없어요.","상황에 따라 골라요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#12','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C20',2,'mc','auto','방언을 지키려는 노력으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X15','K5-2-u3-X14']::text[],false,'{"seq":12,"concept":"K5-2-u3-C20","difficulty":2,"kind":"mc","stem":"방언을 지키려는 노력으로 알맞은 것은 어느 것인가요?","options":[{"t":"어르신들의 말을 녹음해 방언 사전이나 그림책을 만든다","correct":true},{"t":"방언을 쓰는 사람을 놀린다","mis":"K5-2-u3-X29"},{"t":"방언을 모두 표준어로 고쳐 쓴다","mis":"K5-2-u3-X15"},{"t":"방언을 쓰지 말자는 포스터를 붙인다","mis":"K5-2-u3-X14"}],"explanation":["존중해야 해요.","고치기가 아니에요.","기록해 물려줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#13','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C22',2,'blank','auto','「서울서 왔당께.」를 표준어로 바꾸면 「서울에서 ( ? )」예요. 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u3-X22','K5-2-u3-X15']::text[],false,'{"seq":13,"concept":"K5-2-u3-C22","difficulty":2,"kind":"blank","stem":"「서울서 왔당께.」를 표준어로 바꾸면 「서울에서 ( ? )」예요. 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"왔다니까","correct":true},{"t":"왔겠지","mis":"K5-2-u3-X22"},{"t":"왔는데","mis":"K5-2-u3-X22"},{"t":"왔당께","mis":"K5-2-u3-X15"}],"explanation":["뜻이 달라요.","뜻이 달라요.","「~당께」는 「~다니까」예요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#14','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C26',2,'mc','auto','방언을 활용한 작품 활동끼리 바르게 묶은 것은 어느 것인가요?',ARRAY['K5-2-u3-X26','K5-2-u3-X29']::text[],false,'{"seq":14,"concept":"K5-2-u3-C26","difficulty":2,"kind":"mc","stem":"방언을 활용한 작품 활동끼리 바르게 묶은 것은 어느 것인가요?","options":[{"t":"방언 지도 · 방언 노랫말 · 방언 상황극","correct":true},{"t":"방언 지도 · 받아쓰기 시험 · 곱셈 구구표","mis":"K5-2-u3-X26"},{"t":"방언 흉내 대회 · 방언 노랫말 · 상황극","mis":"K5-2-u3-X29"},{"t":"방언 지도 한 가지뿐","mis":"K5-2-u3-X26"}],"explanation":["방언 작품이 아니에요.","흉내는 알맞지 않아요.","세 가지가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#15','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C11',2,'ox','auto','같은 지역 안에서도 마을에 따라 방언이 다를 수 있어요.',ARRAY['K5-2-u3-X11']::text[],false,'{"seq":15,"concept":"K5-2-u3-C11","difficulty":2,"kind":"ox","stem":"같은 지역 안에서도 마을에 따라 방언이 다를 수 있어요.","answer":"O","reason_options":[{"t":"방언은 지역 경계와 똑같이 나뉘지 않고 마을마다 다르기도 하기 때문에","correct":true},{"t":"같은 지역이면 방언이 모두 똑같기 때문에","mis":"K5-2-u3-X11"}],"mis":"K5-2-u3-X11","explanation":["마을마다 달라요.","정답은 하나가 아니에요.","근거로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#16','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C32',2,'mc','auto','동형어의 뜻을 가리는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":16,"concept":"K5-2-u3-C32","difficulty":2,"kind":"mc","stem":"동형어의 뜻을 가리는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"문장 속 앞뒤 말을 살펴본다","correct":true},{"t":"처음 떠오른 뜻으로 정한다","mis":"K5-2-u3-X32"},{"t":"글자 수를 세어 본다","mis":"K5-2-u3-X32"},{"t":"소리 내어 빨리 읽는다","mis":"K5-2-u3-X32"}],"explanation":["뜻이 여럿이에요.","글자 수는 같아요.","앞뒤 말로 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#17','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C12',3,'error','auto','「우리 집 말 조사 일지」를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X14','K5-2-u3-X13','K5-2-u3-X09']::text[],false,'{"seq":17,"concept":"K5-2-u3-C12","difficulty":3,"kind":"error","stem":"「우리 집 말 조사 일지」를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「글쓴이는 가족 앞에서도 표준어만 써야 해.」","correct":true,"mis_target":"K5-2-u3-X14"},{"t":"「발표 자리에서 표준어로 바꾸는 건 친구들이 알아듣게 하려는 거야.」","mis":"K5-2-u3-X13"},{"t":"「가족의 말을 조사하니 우리 집에도 여러 지역 말이 살아 있어.」","mis":"K5-2-u3-X09"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","가족과는 정다운 말도 어울려요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#18','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C14',3,'mc','auto','할아버지께서 고향 친구분과 통화하실 때 방언을 쓰시는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X14','K5-2-u3-X03','K5-2-u3-X12']::text[],false,'{"seq":18,"concept":"K5-2-u3-C14","difficulty":3,"kind":"mc","stem":"할아버지께서 고향 친구분과 통화하실 때 방언을 쓰시는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어릴 적부터 함께 쓰던 말로 편하고 정답게 마음을 나누시려고","correct":true},{"t":"표준어를 모르셔서","mis":"K5-2-u3-X14"},{"t":"친구분이 표준어를 못 알아들으셔서","mis":"K5-2-u3-X03"},{"t":"전화로는 방언만 써야 해서","mis":"K5-2-u3-X12"}],"explanation":["몰라서가 아니에요.","알아들으세요.","정을 나누시려고요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#19','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C23',3,'error','auto','방언 낭독과 표준어 낭독을 견준 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X24','K5-2-u3-X23']::text[],false,'{"seq":19,"concept":"K5-2-u3-C23","difficulty":3,"kind":"error","stem":"방언 낭독과 표준어 낭독을 견준 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「표준어로 읽어야 바른 낭독이니 방언 낭독은 할 필요가 없어.」","correct":true,"mis_target":"K5-2-u3-X24"},{"t":"「방언 낭독에서 할머니 얼굴이 더 떠올랐어.」","mis":"K5-2-u3-X23"},{"t":"「표준어 낭독도 뜻은 잘 전해졌어.」","mis":"K5-2-u3-X23"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","방언 낭독에서 정이 살아나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#20','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C18',3,'error','auto','방언 속 지역 이야기 카드를 본 친구들의 말이에요. 방언의 가치를 가장 잘못 이해한 말은 어느 것인가요?',ARRAY['K5-2-u3-X18','K5-2-u3-X17']::text[],false,'{"seq":20,"concept":"K5-2-u3-C18","difficulty":3,"kind":"error","stem":"방언 속 지역 이야기 카드를 본 친구들의 말이에요. 방언의 가치를 가장 잘못 이해한 말은 어느 것인가요?","options":[{"t":"「뜻만 적으면 됐지 그 지역 자연이나 생활은 적을 필요 없어.」","correct":true,"mis_target":"K5-2-u3-X18"},{"t":"「돔배기에는 동해와 가까운 생활이 담겨 있어.」","mis":"K5-2-u3-X18"},{"t":"「정낭에는 이웃을 믿던 마을 생활이 담겨 있어.」","mis":"K5-2-u3-X17"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","자연과 생활까지 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#21','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C27',3,'mc','auto','방언 지도를 만들며 「이 방언은 어떤 생활 모습과 관련이 있을까?」라고 묻는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X28','K5-2-u3-X29','K5-2-u3-X27']::text[],false,'{"seq":21,"concept":"K5-2-u3-C27","difficulty":3,"kind":"mc","stem":"방언 지도를 만들며 「이 방언은 어떤 생활 모습과 관련이 있을까?」라고 묻는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"방언의 뜻을 적는 데 그치지 않고 지역의 생활까지 조사하려고","correct":true},{"t":"방언 개수를 늘리려고","mis":"K5-2-u3-X28"},{"t":"흉내 낼 말을 고르려고","mis":"K5-2-u3-X29"},{"t":"지도를 빨리 마치려고","mis":"K5-2-u3-X27"}],"explanation":["개수가 목적이 아니에요.","흉내는 알맞지 않아요.","생활까지 조사해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#22','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C6',3,'mc','auto','표준어를 정한 까닭과 방언이 소중한 까닭을 함께 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u3-X06','K5-2-u3-X03','K5-2-u3-X07']::text[],false,'{"seq":22,"concept":"K5-2-u3-C6","difficulty":3,"kind":"mc","stem":"표준어를 정한 까닭과 방언이 소중한 까닭을 함께 바르게 말한 것은 어느 것인가요?","options":[{"t":"표준어는 원활한 의사소통을, 방언은 지역의 특성과 정서를 지켜 준다","correct":true},{"t":"표준어는 고운 말이라서, 방언은 재미있는 말이라서","mis":"K5-2-u3-X06"},{"t":"표준어는 서울 말이라서, 방언은 시골 말이라서","mis":"K5-2-u3-X03"},{"t":"표준어는 짧아서, 방언은 길어서","mis":"K5-2-u3-X07"}],"explanation":["곱고 재미있음이 까닭이 아니에요.","사는 곳이 까닭이 아니에요.","하는 일이 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#23','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C32',4,'essay','teacher','「배」 · 「눈」 · 「말」 가운데 하나를 골라 서로 다른 두 뜻으로 문장을 하나씩 만들어 쓰고, 뜻을 어떻게 가렸는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u3-C32","difficulty":4,"kind":"essay","stem":"「배」 · 「눈」 · 「말」 가운데 하나를 골라 서로 다른 두 뜻으로 문장을 하나씩 만들어 쓰고, 뜻을 어떻게 가렸는지 쓰세요.","answer_guide":{"answer":"예: 눈 — 「눈이 소복이 쌓였다.」, 「눈을 크게 뜨고 바라보았다.」 앞 문장은 「쌓였다」를 보고 하늘에서 내리는 눈, 뒤 문장은 「뜨고」를 보고 보는 눈임을 알았다.","scoring_points":["낱말을 하나 골랐는가","서로 다른 두 뜻으로 문장을 만들었는가","앞뒤 말로 뜻을 가렸다고 썼는가"]},"explanation":["하나를 골라요.","두 뜻으로 써요.","앞뒤 말이 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#24','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C9',4,'essay','teacher','「우리 집 말 조사 일지」처럼 우리 가족이 쓰는 말을 하나 조사해 방언과 표준어, 쓰는 사람과 상황을 정리해 쓰세요. 방언이 떠오르지 않으면 가족이 즐겨 쓰는 표준어 표현으로 써도 돼요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u3-C9","difficulty":4,"kind":"essay","stem":"「우리 집 말 조사 일지」처럼 우리 가족이 쓰는 말을 하나 조사해 방언과 표준어, 쓰는 사람과 상황을 정리해 쓰세요. 방언이 떠오르지 않으면 가족이 즐겨 쓰는 표준어 표현으로 써도 돼요.","answer_guide":{"answer":"예: 방언 — 정구지, 표준어 — 부추, 쓰는 사람 — 경상 지역에 사시는 외할머니, 상황 — 부침개를 부치시며 「정구지 좀 더 넣자.」 하고 말씀하실 때. 가족끼리 편하게 이야기하실 때 쓰신다.","scoring_points":["조사한 말과 뜻을 썼는가","쓰는 사람을 썼는가","쓰는 상황을 썼는가"]},"explanation":["말과 뜻이에요.","누가 쓰는지예요.","어떤 상황인지예요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#25','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C15',4,'essay','teacher','방언을 표준어로 바꾸어 보는 활동이 방언을 고치는 일이 아닌 까닭을 예를 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u3-C15","difficulty":4,"kind":"essay","stem":"방언을 표준어로 바꾸어 보는 활동이 방언을 고치는 일이 아닌 까닭을 예를 들어 쓰세요.","answer_guide":{"answer":"예: 「일찍 왔네유.」를 「일찍 왔네요.」로 바꾸어도 뜻은 같다. 고향 집 마당에서는 방언이 정답고, 여러 사람 앞 발표에서는 표준어가 알맞다. 그러므로 바꾸어 보는 것은 틀린 말을 고치는 것이 아니라, 같은 뜻을 상황에 따라 골라 쓴다는 것을 알기 위한 활동이다.","scoring_points":["예를 들었는가","뜻은 같다는 것을 썼는가","상황에 따른 선택을 알기 위함을 썼는가"]},"explanation":["예를 들어요.","뜻은 같아요.","선택을 알기 위해서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#1','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C3',1,'ox','auto','방언은 시골에서만 쓰는 말이에요.',ARRAY['K5-2-u3-X03']::text[],false,'{"seq":1,"concept":"K5-2-u3-C3","difficulty":1,"kind":"ox","stem":"방언은 시골에서만 쓰는 말이에요.","answer":"X","reason_options":[{"t":"큰 도시에서도 그 지역에서 주로 쓰는 말이 있기 때문에","correct":true},{"t":"도시 사람은 모두 표준어만 쓰기 때문에","mis":"K5-2-u3-X03"}],"mis":"K5-2-u3-X03","explanation":["도시에도 방언이 있어요.","지역의 말이에요.","시골 말만이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#2','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C32',1,'ox','auto','「배」는 먹는 배, 타는 배, 몸의 배처럼 여러 뜻으로 쓰여요.',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":2,"concept":"K5-2-u3-C32","difficulty":1,"kind":"ox","stem":"「배」는 먹는 배, 타는 배, 몸의 배처럼 여러 뜻으로 쓰여요.","answer":"O","reason_options":[{"t":"글자 모양은 같지만 뜻이 다른 동형어이기 때문에","correct":true},{"t":"한 낱말에는 뜻이 하나뿐이기 때문에","mis":"K5-2-u3-X32"}],"mis":"K5-2-u3-X32","explanation":["뜻이 여럿이에요.","앞뒤 말로 가려요.","동형어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#3','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C8',1,'ox','auto','「멍게」는 원래 방언이었지만 지금은 표준어예요.',ARRAY['K5-2-u3-X08']::text[],false,'{"seq":3,"concept":"K5-2-u3-C8","difficulty":1,"kind":"ox","stem":"「멍게」는 원래 방언이었지만 지금은 표준어예요.","answer":"O","reason_options":[{"t":"표준어 「우렁쉥이」보다 더 널리 쓰이게 되어 함께 표준어가 되었기 때문에","correct":true},{"t":"방언은 어떤 경우에도 표준어가 될 수 없기 때문에","mis":"K5-2-u3-X08"}],"mis":"K5-2-u3-X08","explanation":["널리 쓰였어요.","둘 다 표준어예요.","움직이는 경계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#4','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C14',1,'mc','auto','상황 카드 ㉱ 「우리 지역 축제를 홍보할 때」 방언을 쓰기도 하는 까닭은 무엇인가요?',ARRAY['K5-2-u3-X20','K5-2-u3-X14','K5-2-u3-X29']::text[],false,'{"seq":4,"concept":"K5-2-u3-C14","difficulty":1,"kind":"mc","stem":"상황 카드 ㉱ 「우리 지역 축제를 홍보할 때」 방언을 쓰기도 하는 까닭은 무엇인가요?","options":[{"t":"지역의 정서와 특성을 잘 보여 주려고","correct":true},{"t":"다른 지역 사람이 오지 못하게 하려고","mis":"K5-2-u3-X20"},{"t":"표준어를 몰라서","mis":"K5-2-u3-X14"},{"t":"웃음거리로 삼으려고","mis":"K5-2-u3-X29"}],"explanation":["반기려는 거예요.","몰라서가 아니에요.","지역의 정서를 보여 줘요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#5','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C9',1,'mc','auto','「무시」를 표준어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":5,"concept":"K5-2-u3-C9","difficulty":1,"kind":"mc","stem":"「무시」를 표준어로 바꾸면 어느 것인가요?","options":[{"t":"무","correct":true},{"t":"배추","mis":"K5-2-u3-X10"},{"t":"파","mis":"K5-2-u3-X10"},{"t":"감자","mis":"K5-2-u3-X10"}],"explanation":["관계없어요.","관계없어요.","무시는 무예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#6','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C18',1,'mc','auto','「뻘」이라는 방언과 이어지는 자연환경은 어느 것인가요?',ARRAY['K5-2-u3-X18']::text[],false,'{"seq":6,"concept":"K5-2-u3-C18","difficulty":1,"kind":"mc","stem":"「뻘」이라는 방언과 이어지는 자연환경은 어느 것인가요?","options":[{"t":"넓은 갯벌","correct":true},{"t":"높은 산","mis":"K5-2-u3-X18"},{"t":"넓은 사막","mis":"K5-2-u3-X18"},{"t":"깊은 동굴","mis":"K5-2-u3-X18"}],"explanation":["관계없어요.","관계없어요.","서해안 갯벌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#7','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C13',1,'ox','auto','전국에 방송되는 일기 예보는 방언만 써도 모두 똑같이 알아들어요.',ARRAY['K5-2-u3-X13']::text[],false,'{"seq":7,"concept":"K5-2-u3-C13","difficulty":1,"kind":"ox","stem":"전국에 방송되는 일기 예보는 방언만 써도 모두 똑같이 알아들어요.","answer":"X","reason_options":[{"t":"말이 달라 알아듣기 어려운 사람이 생길 수 있기 때문에","correct":true},{"t":"방언은 어느 지역 사람이든 다 알기 때문에","mis":"K5-2-u3-X13"}],"mis":"K5-2-u3-X13","explanation":["알아듣기 어려워요.","여러 지역 사람이 봐요.","표준어가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#8','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C24',1,'ox','auto','방언이 나오는 작품은 지역의 말을 기록하고 지키는 데에도 도움이 돼요.',ARRAY['K5-2-u3-X24']::text[],false,'{"seq":8,"concept":"K5-2-u3-C24","difficulty":1,"kind":"ox","stem":"방언이 나오는 작품은 지역의 말을 기록하고 지키는 데에도 도움이 돼요.","answer":"O","reason_options":[{"t":"작품에 담긴 방언이 글로 남아 다음 사람에게 전해지기 때문에","correct":true},{"t":"작품 속 방언은 아무도 읽지 않기 때문에","mis":"K5-2-u3-X24"}],"mis":"K5-2-u3-X24","explanation":["글로 남아요.","전해져요.","지역의 말을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#9','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C3',2,'mc','auto','「우리 집 말 조사 일지」에서 「깨깟허다」라고 말씀하시는 분은 누구인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":9,"concept":"K5-2-u3-C3","difficulty":2,"kind":"mc","stem":"「우리 집 말 조사 일지」에서 「깨깟허다」라고 말씀하시는 분은 누구인가요?","options":[{"t":"충청 지역에 사시는 고모","correct":true},{"t":"제주 지역이 고향인 외할머니","mis":"K5-2-u3-X21"},{"t":"강원 지역 큰아버지","mis":"K5-2-u3-X21"},{"t":"글쓴이","mis":"K5-2-u3-X21"}],"explanation":["할망이라고 하세요.","낭구라고 하세요.","셋째 줄에 나와요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#10','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C5',2,'mc','auto','방언이 생긴 까닭과 가장 관계 깊은 것은 어느 것인가요?',ARRAY['K5-2-u3-X05']::text[],false,'{"seq":10,"concept":"K5-2-u3-C5","difficulty":2,"kind":"mc","stem":"방언이 생긴 까닭과 가장 관계 깊은 것은 어느 것인가요?","options":[{"t":"지역 사이에 이야기할 기회가 적었던 것","correct":true},{"t":"지역마다 글자를 따로 만든 것","mis":"K5-2-u3-X05"},{"t":"방송국이 지역마다 달랐던 것","mis":"K5-2-u3-X05"},{"t":"사람들이 표준어를 외우지 않은 것","mis":"K5-2-u3-X05"}],"explanation":["글자는 같아요.","옛날 일이에요.","오가기 어려웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#11','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C31',2,'match','auto','상황 카드와 그 말을 고른 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"K5-2-u3-C31","difficulty":2,"kind":"match","stem":"상황 카드와 그 말을 고른 까닭을 알맞게 이으세요.","pairs":[{"l":"㉯ 뉴스","r":"여러 지역 사람들이 보기 때문에"},{"l":"㉮ 고향 친구","r":"어릴 적부터 쓰던 말로 마음을 나누기 때문에"},{"l":"㉱ 축제 홍보","r":"지역의 정서와 특성을 보여 주기 때문에"}],"mis":"K5-2-u3-X31","explanation":["표준어예요.","방언이에요.","방언을 쓰기도 해요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#12','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C17',2,'error','auto','「삼춘」에 대해 말한 친구들이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X17','K5-2-u3-X19']::text[],false,'{"seq":12,"concept":"K5-2-u3-C17","difficulty":2,"kind":"error","stem":"「삼춘」에 대해 말한 친구들이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「삼춘은 삼촌을 틀리게 쓴 말일 뿐이야.」","correct":true,"mis_target":"K5-2-u3-X01"},{"t":"「피를 나누지 않은 이웃 어른도 가족처럼 부르는 말이야.」","mis":"K5-2-u3-X17"},{"t":"「이웃을 가족처럼 여기는 마을 모습이 담겨 있어.」","mis":"K5-2-u3-X19"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","틀린 말이 아니라 담긴 생활이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#13','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C23',2,'ox','auto','「못 보던 얼굴인디, 누구 손주여?」를 표준어로 바꾸어도 뜻은 같아요.',ARRAY['K5-2-u3-X23']::text[],false,'{"seq":13,"concept":"K5-2-u3-C23","difficulty":2,"kind":"ox","stem":"「못 보던 얼굴인디, 누구 손주여?」를 표준어로 바꾸어도 뜻은 같아요.","answer":"O","reason_options":[{"t":"뜻은 같고 느낌이나 분위기가 달라지기 때문에","correct":true},{"t":"표준어로 바꾸면 뜻까지 완전히 달라지기 때문에","mis":"K5-2-u3-X23"}],"mis":"K5-2-u3-X23","explanation":["뜻은 같아요.","느낌이 달라요.","견주어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#14','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C29',2,'error','auto','방언 상황극을 준비하는 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X26','K5-2-u3-X27']::text[],false,'{"seq":14,"concept":"K5-2-u3-C29","difficulty":2,"kind":"error","stem":"방언 상황극을 준비하는 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「말투를 크게 부풀려야 관객이 더 웃을 거야.」","correct":true,"mis_target":"K5-2-u3-X29"},{"t":"「방언이 실감 나는 장면을 먼저 정하자.」","mis":"K5-2-u3-X26"},{"t":"「그 지역 사람의 마음을 살려 연기하자.」","mis":"K5-2-u3-X27"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","흉내로 웃음거리를 만들지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#15','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C16',2,'mc','auto','조사표 「시장에서 상인이 단골손님에게 — 방언」 뒤에 덧붙일 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X13','K5-2-u3-X14','K5-2-u3-X16']::text[],false,'{"seq":15,"concept":"K5-2-u3-C16","difficulty":2,"kind":"mc","stem":"조사표 「시장에서 상인이 단골손님에게 — 방언」 뒤에 덧붙일 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"더 친근하고 정답게 이야기하려고","correct":true},{"t":"손님이 알아듣지 못하게 하려고","mis":"K5-2-u3-X13"},{"t":"표준어를 몰라서","mis":"K5-2-u3-X14"},{"t":"까닭은 적지 않아도 된다","mis":"K5-2-u3-X16"}],"explanation":["반기려는 말이에요.","몰라서가 아니에요.","정을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#16','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C32',2,'mc','auto','「말」이 「사람이 하는 말」의 뜻으로 쓰인 문장은 어느 것인가요?',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":16,"concept":"K5-2-u3-C32","difficulty":2,"kind":"mc","stem":"「말」이 「사람이 하는 말」의 뜻으로 쓰인 문장은 어느 것인가요?","options":[{"t":"친구에게 고맙다는 말을 했다.","correct":true},{"t":"목장에서 말을 탔다.","mis":"K5-2-u3-X32"},{"t":"말이 들판을 달린다.","mis":"K5-2-u3-X32"},{"t":"말에게 당근을 주었다.","mis":"K5-2-u3-X32"}],"explanation":["타는 말이에요.","동물이에요.","사람이 하는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#17','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C10',3,'mc','auto','글쓴이가 조사한 방언이 맞는지 더 확인하려면 어떻게 하는 것이 가장 좋을까요?',ARRAY['K5-2-u3-X11','K5-2-u3-X10','K5-2-u3-X19']::text[],false,'{"seq":17,"concept":"K5-2-u3-C10","difficulty":3,"kind":"mc","stem":"글쓴이가 조사한 방언이 맞는지 더 확인하려면 어떻게 하는 것이 가장 좋을까요?","options":[{"t":"지역어 누리집에서 낱말을 찾아 쓰는 지역과 뜻을 확인한다","correct":true},{"t":"친구 한 명에게만 물어본다","mis":"K5-2-u3-X11"},{"t":"뜻을 짐작해 그대로 둔다","mis":"K5-2-u3-X10"},{"t":"조사한 말을 모두 지운다","mis":"K5-2-u3-X19"}],"explanation":["한 사람 말은 부족해요.","근거가 없어요.","근거로 확인해요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#18','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C13',3,'error','auto','학교 방송부가 「우리 고장 소개」 방송 계획을 세웠어요. 듣는 사람을 가장 덜 생각한 계획은 어느 것인가요?',ARRAY['K5-2-u3-X13','K5-2-u3-X30','K5-2-u3-X22']::text[],false,'{"seq":18,"concept":"K5-2-u3-C13","difficulty":3,"kind":"error","stem":"학교 방송부가 「우리 고장 소개」 방송 계획을 세웠어요. 듣는 사람을 가장 덜 생각한 계획은 어느 것인가요?","options":[{"t":"「다른 지역 학교에도 보낼 방송이지만 설명까지 모두 방언으로만 하자.」","correct":true,"mis_target":"K5-2-u3-X13"},{"t":"「소개는 표준어로 하고 어르신 인터뷰는 방언 그대로 싣자.」","mis":"K5-2-u3-X30"},{"t":"「방언이 나오면 자막으로 뜻을 함께 보여 주자.」","mis":"K5-2-u3-X22"}],"explanation":["둘 다 살렸어요.","뜻을 도와요.","다른 지역 학생이 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#19','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C21',3,'mc','auto','「처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다.」에서 하준이 마음이 바뀐 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X23','K5-2-u3-X21']::text[],false,'{"seq":19,"concept":"K5-2-u3-C21","difficulty":3,"kind":"mc","stem":"「처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다.」에서 하준이 마음이 바뀐 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마을 사람들의 반가운 마음을 함께 지내며 느꼈기 때문에","correct":true},{"t":"할머니들이 표준어로 말을 바꾸었기 때문에","mis":"K5-2-u3-X23"},{"t":"하준이가 방언 뜻을 모두 외웠기 때문에","mis":"K5-2-u3-X21"},{"t":"감이 맛있었기 때문에","mis":"K5-2-u3-X21"}],"explanation":["말은 그대로예요.","외운 이야기는 없어요.","정을 느꼈어요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#20','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C19',3,'mc','auto','「표준어만 있으면 충분하니 방언은 필요 없다.」라는 주장에 대한 반론으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X30','K5-2-u3-X20','K5-2-u3-X19']::text[],false,'{"seq":20,"concept":"K5-2-u3-C19","difficulty":3,"kind":"mc","stem":"「표준어만 있으면 충분하니 방언은 필요 없다.」라는 주장에 대한 반론으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"방언에는 표준어로 다 담기 어려운 지역의 생활과 정서가 들어 있다","correct":true},{"t":"표준어는 쓸모없는 말이다","mis":"K5-2-u3-X30"},{"t":"방언은 다른 지역 사람과 소통을 막는다","mis":"K5-2-u3-X20"},{"t":"방언은 옛날 말이라 소중하지 않다","mis":"K5-2-u3-X19"}],"explanation":["표준어도 소중해요.","주장을 돕는 말이에요.","방언의 가치로 반론해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#21','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C26',3,'error','auto','방언 노랫말 만들기 계획이에요. 활동의 목적에서 가장 벗어난 계획은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X26','K5-2-u3-X28']::text[],false,'{"seq":21,"concept":"K5-2-u3-C26","difficulty":3,"kind":"error","stem":"방언 노랫말 만들기 계획이에요. 활동의 목적에서 가장 벗어난 계획은 어느 것인가요?","options":[{"t":"「뜻은 신경 쓰지 말고 웃긴 말투만 골라 넣자.」","correct":true,"mis_target":"K5-2-u3-X29"},{"t":"「아는 노래에 우리 지역 인사말을 넣어 바꾸어 부르자.」","mis":"K5-2-u3-X26"},{"t":"「넣은 방언의 뜻을 노랫말 아래에 함께 적자.」","mis":"K5-2-u3-X28"}],"explanation":["알맞은 계획이에요.","알맞은 계획이에요.","웃음거리로 삼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#22','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C15',3,'mc','auto','「일찍 왔네유.」를 「일찍 왔네요.」로 바꾸어 본 친구의 말 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X15','K5-2-u3-X23','K5-2-u3-X14']::text[],false,'{"seq":22,"concept":"K5-2-u3-C15","difficulty":3,"kind":"mc","stem":"「일찍 왔네유.」를 「일찍 왔네요.」로 바꾸어 본 친구의 말 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「뜻은 같지만 고향 집에서는 방언이, 발표에서는 표준어가 더 어울려.」","correct":true},{"t":"「이제 틀린 말을 고쳤어.」","mis":"K5-2-u3-X15"},{"t":"「바꾸었더니 뜻이 완전히 달라졌어.」","mis":"K5-2-u3-X23"},{"t":"「방언은 앞으로 쓰지 말아야겠어.」","mis":"K5-2-u3-X14"}],"explanation":["고치기가 아니에요.","뜻은 같아요.","자리에 따라 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#23','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C12',4,'essay','teacher','같은 날 전국 어린이 회의에서 발표하고 저녁에 할머니 고향 마을 잔치에 간다면 각 자리에서 어떤 말을 쓸지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u3-C12","difficulty":4,"kind":"essay","stem":"같은 날 전국 어린이 회의에서 발표하고 저녁에 할머니 고향 마을 잔치에 간다면 각 자리에서 어떤 말을 쓸지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 어린이 회의에서는 여러 지역 친구들이 모두 알아듣도록 표준어로 발표하겠다. 잔치에서는 할머니 고향 어르신들과 더 가깝게 이야기하고 싶어 어르신들이 쓰시는 말을 귀담아듣고 정답게 인사하겠다. 우리 집이 표준어를 쓰는 지역이라면 잔치에서도 표준어로 정답게 말하면 된다.","scoring_points":["회의 자리의 말과 까닭을 썼는가","잔치 자리의 말과 까닭을 썼는가","자리에 따라 고르는 기준이 드러나는가"]},"explanation":["회의 자리예요.","잔치 자리예요.","자리에 따라 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#24','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C5',4,'essay','teacher','방언이 생긴 까닭을 옛날의 지형과 교통과 이어 설명하고, 오늘날 방언이 어떻게 달라질지 내 생각을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u3-C5","difficulty":4,"kind":"essay","stem":"방언이 생긴 까닭을 옛날의 지형과 교통과 이어 설명하고, 오늘날 방언이 어떻게 달라질지 내 생각을 쓰세요.","answer_guide":{"answer":"예: 옛날에는 산과 강이 많고 교통이 발달하지 않아 지역 사이를 오가기 어려웠고, 이야기할 기회가 적어 지역마다 말이 달라졌다. 오늘날에는 교통과 통신이 발달해 표준어와 닮아 가는 방언도 있겠지만, 지역 사람들이 아끼고 기록한다면 계속 남을 것이다.","scoring_points":["지형과 교통을 들어 까닭을 썼는가","오늘날의 변화를 짐작했는가","내 생각에 까닭이 있는가"]},"explanation":["지형과 교통이에요.","오늘날을 생각해요.","까닭을 덧붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#25','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C29',4,'essay','teacher','이 단원을 배우며 방언을 대하는 내 생각이나 태도가 어떻게 달라졌는지 쓰고, 앞으로 실천할 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u3-C29","difficulty":4,"kind":"essay","stem":"이 단원을 배우며 방언을 대하는 내 생각이나 태도가 어떻게 달라졌는지 쓰고, 앞으로 실천할 일을 쓰세요.","answer_guide":{"answer":"예: 전에는 방언을 들으면 우습다고 생각했는데, 이제는 그 말에 지역의 생활과 정이 담겨 있다는 것을 알게 되었다. 앞으로는 낯선 방언을 흉내 내지 않고 궁금한 마음으로 뜻을 묻고, 할머니께 고향 말을 여쭈어 기록해 보겠다.","scoring_points":["달라진 생각이나 태도를 썼는가","방언을 존중하는 까닭이 드러나는가","앞으로 실천할 일을 썼는가"]},"explanation":["달라진 점이에요.","존중하는 까닭이에요.","실천할 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
